use std::fmt;
use std::ptr;

pub struct CRC32 {
    m_hash: u32,
}

impl CRC32 {
    pub const HASH_BYTES: usize = 4; // Equivalent to HashBytes in C++ version

    /// same as reset()
    pub fn new() -> Self {
        let mut instance = CRC32 { m_hash: 0 };
        instance.reset();
        instance
    }

    /// restart
    pub fn reset(&mut self) {
        self.m_hash = 0;
    }

    /// add arbitrary number of bytes
    pub fn add(&mut self, data: &[u8]) {
        let mut num_bytes = data.len();
        let mut current = data.as_ptr();
        let mut crc = !self.m_hash;

        // process eight bytes at once
        while num_bytes >= 8 {
            let one = unsafe { ptr::read_unaligned(current as *const u32) } ^ crc;
            let two = unsafe { ptr::read_unaligned(current.add(4) as *const u32) };
            crc = CRC32_LOOKUP[7][(one & 0xFF) as usize]
                ^ CRC32_LOOKUP[6][((one >> 8) & 0xFF) as usize]
                ^ CRC32_LOOKUP[5][((one >> 16) & 0xFF) as usize]
                ^ CRC32_LOOKUP[4][(one >> 24) as usize]
                ^ CRC32_LOOKUP[3][(two & 0xFF) as usize]
                ^ CRC32_LOOKUP[2][((two >> 8) & 0xFF) as usize]
                ^ CRC32_LOOKUP[1][((two >> 16) & 0xFF) as usize]
                ^ CRC32_LOOKUP[0][(two >> 24) as usize];

            num_bytes -= 8;
            current = unsafe { current.add(8) };
        }

        // remaining 1 to 7 bytes (standard CRC table-based algorithm)
        while num_bytes > 0 {
            crc = (crc >> 8)
                ^ CRC32_LOOKUP[0][(((crc & 0xFF) as u8) ^ unsafe { *current }) as usize];
            current = unsafe { current.add(1) };
            num_bytes -= 1;
        }

        self.m_hash = !crc;
    }

    /// return latest hash as 8 hex characters
    pub fn get_hash(&self) -> String {
        format!("{:08x}", self.m_hash)
    }

    /// return latest hash as bytes
    pub fn get_hash_bytes(&self, buffer: &mut [u8; Self::HASH_BYTES]) {
        buffer[0] = (self.m_hash >> 24) as u8;
        buffer[1] = (self.m_hash >> 16) as u8;
        buffer[2] = (self.m_hash >> 8) as u8;
        buffer[3] = self.m_hash as u8;
    }

    /// compute CRC32 of a memory block
    pub fn compute(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    /// compute CRC32 of a string, excluding final zero
    pub fn compute_from_string(&mut self, text: &str) -> String {
        self.reset();
        self.add(text.as_bytes());
        self.get_hash()
    }
}

impl fmt::Debug for CRC32 {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
