        let mut num_bytes = data.len();
        let mut current = data.as_ptr() as *const u32;
        let mut crc = !self.m_hash;

        while num_bytes >= 8 {
            unsafe {
                #[cfg(target_endian = "big")]
                let one = (*current ^ swap(crc.to_be())) as u32;
                #[cfg(not(target_endian = "big"))]
                let one = (*current ^ crc) as u32;

                let two = *(current.add(1)) as u32;

                current = current.add(2);

                crc = CRC32_LOOKUP[7][(one & 0xFF) as usize]
                    ^ CRC32_LOOKUP[6][((one >> 8) & 0xFF) as usize]
                    ^ CRC32_LOOKUP[5][((one >> 16) & 0xFF) as usize]
                    ^ CRC32_LOOKUP[4][(one >> 24) as usize]
                    ^ CRC32_LOOKUP[3][(two & 0xFF) as usize]
                    ^ CRC32_LOOKUP[2][((two >> 8) & 0xFF) as usize]
                    ^ CRC32_LOOKUP[1][((two >> 16) & 0xFF) as usize]
                    ^ CRC32_LOOKUP[0][(two >> 24) as usize];
            }

            num_bytes -= 8;
        }

        unsafe {
            let mut current_char = current as *const u8;
            while num_bytes > 0 {
                crc = (crc >> 8) ^ CRC32_LOOKUP[0][((crc & 0xFF) ^ *current_char as u32) as usize];
                current_char = current_char.add(1);
                num_bytes -= 1;
            }
        }

        self.m_hash = !crc;
    }

