            crc = CRC32_LOOKUP[7][(one & 0xFF) as usize]
                ^ CRC32_LOOKUP[6][((one >> 8) & 0xFF) as usize]
                ^ CRC32_LOOKUP[5][((one >> 16) & 0xFF) as usize]
                ^ CRC32_LOOKUP[4][((one >> 24) & 0xFF) as usize]
                ^ CRC32_LOOKUP[3][(two & 0xFF) as usize]
                ^ CRC32_LOOKUP[2][((two >> 8) & 0xFF) as usize]
                ^ CRC32_LOOKUP[1][((two >> 16) & 0xFF) as usize]
                ^ CRC32_LOOKUP[0][((two >> 24) & 0xFF) as usize];

            num_bytes -= 8;
        }

        let mut current_char = data_ptr as *const u8;
        while num_bytes != 0 {
            crc = (crc >> 8) ^ CRC32_LOOKUP[0][((crc & 0xFF) ^ (unsafe { *current_char } as u32)) as usize];
            current_char = unsafe { current_char.add(1) };
            num_bytes -= 1;
        }

        self.m_hash = !crc;
    }

    /// return latest hash as 8 hex characters
    pub fn get_hash(&self) -> String {
        format!("{:08x}", self.m_hash)
    }

    /// return latest hash as bytes
    pub fn get_hash_bytes(&self, buffer: &mut [u8; 4]) {
        buffer[0] = ((self.m_hash >> 24) & 0xFF) as u8;
        buffer[1] = ((self.m_hash >> 16) & 0xFF) as u8;
        buffer[2] = ((self.m_hash >> 8) & 0xFF) as u8;
        buffer[3] = (self.m_hash & 0xFF) as u8;
    }

    /// compute CRC32 of a memory block
    pub fn compute(data: &[u8]) -> String {
        let mut crc32 = CRC32::new();
        crc32.add(data);
        crc32.get_hash()
    }

    /// compute CRC32 of a string, excluding final zero
    pub fn compute_str(text: &str) -> String {
        let mut crc32 = CRC32::new();
        crc32.add(text.as_bytes());
        crc32.get_hash()
    }
}

// look-up table
static CRC32_LOOKUP: [[u32; 256]; 8] = [
    [0x00000000; 256],
    [0x00000000; 256],
    [0x00000000; 256],
    [0x00000000; 256],
    [0x00000000; 256],
    [0x00000000; 256],
    [0x00000000; 256],
    [0x00000000; 256],
];

// Inline function to swap the bytes of a u32
fn swap(x: u32) -> u32 {
    x.swap_bytes()
}

