    /// Resets the hash state.
    pub fn reset(&mut self) {
        self.m_hash.iter_mut().for_each(|x| *x = 0);
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;
    }

    /// Processes a full block of data.
    pub fn process_block(&mut self, data: &[u8]) {
        let data64 = unsafe { std::slice::from_raw_parts(data.as_ptr() as *const u64, data.len() / 8) };

        // Mix data into state
        for i in 0..self.m_block_size / 8 {
            self.m_hash[i] ^= Self::little_endian(data64[i]);
        }

        // Re-compute state
        for round in 0..KeccakRounds {
            // Theta
            let mut coefficients = [0u64; 5];
            for i in 0..5 {
                coefficients[i] = self.m_hash[i]
                    ^ self.m_hash[i + 5]
                    ^ self.m_hash[i + 10]
                    ^ self.m_hash[i + 15]
                    ^ self.m_hash[i + 20];
            }

            for i in 0..5 {
                let one = coefficients[Self::mod5(i + 4)] ^ Self::rotate_left(coefficients[Self::mod5(i + 1)], 1);
                self.m_hash[i] ^= one;
                self.m_hash[i + 5] ^= one;
                self.m_hash[i + 10] ^= one;
                self.m_hash[i + 15] ^= one;
                self.m_hash[i + 20] ^= one;
            }

            // Rho Pi
            let mut last = self.m_hash[1];
            for &(idx, shift) in &[
                (10, 1), (7, 3), (11, 6), (17, 10), (18, 15), (3, 21), (5, 28),
                (16, 36), (8, 45), (21, 55), (24, 2), (4, 14), (15, 27), (23, 41),
                (19, 56), (13, 8), (12, 25), (2, 43), (20, 62), (14, 18), (22, 39),
                (9, 61), (6, 20), (1, 44)
            ] {
                let one = self.m_hash[idx];
                self.m_hash[idx] = Self::rotate_left(last, shift);
                last = one;
            }

            // Chi
            for j in (0..StateSize).step_by(5) {
                let one = self.m_hash[j];
                let two = self.m_hash[j + 1];
                self.m_hash[j] ^= self.m_hash[j + 2] & !two;
                self.m_hash[j + 1] ^= self.m_hash[j + 3] & !self.m_hash[j + 2];
                self.m_hash[j + 2] ^= self.m_hash[j + 4] & !self.m_hash[j + 3];
                self.m_hash[j + 3] ^= one & !self.m_hash[j + 4];
                self.m_hash[j + 4] ^= two & !one;
            }

            // Iota
            self.m_hash[0] ^= XorMasks[round];
        }
    }

    /// Adds an arbitrary number of bytes to be processed.
    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;

        if self.m_buffer_size > 0 {
            while !current.is_empty() && self.m_buffer_size < self.m_block_size {
                self.m_buffer[self.m_buffer_size] = current[0];
                self.m_buffer_size += 1;
                current = &current[1..];
            }

            if self.m_buffer_size == self.m_block_size {
                let buffer_copy = self.m_buffer;
                self.process_block(&buffer_copy);
                self.m_num_bytes += self.m_block_size;
                self.m_buffer_size = 0;
            }
        }

        while current.len() >= self.m_block_size {
            self.process_block(current);
            current = &current[self.m_block_size..];
            self.m_num_bytes += self.m_block_size;
        }

        self.m_buffer[..current.len()].copy_from_slice(current);
        self.m_buffer_size = current.len();
    }

    /// Processes everything left in the internal buffer.
    fn process_buffer(&mut self) {
        let block_size = 200 - 2 * (self.m_bits as usize / 8);

        let mut offset = self.m_buffer_size;
        self.m_buffer[offset] = 1;
        offset += 1;
        self.m_buffer[offset..block_size - 1].iter_mut().for_each(|x| *x = 0);
        self.m_buffer[block_size - 1] |= 0x80;

        let buffer_copy = self.m_buffer[..block_size].to_vec();
        self.process_block(&buffer_copy);
    }

    /// Returns the latest hash as a string of hex characters.
    pub fn get_hash(&mut self) -> String {
        let mut old_hash = [0u64; StateSize];
        old_hash.copy_from_slice(&self.m_hash);

        self.process_buffer();

        let mut result = String::new();
        let hash_length = self.m_bits as usize / 64;

        for i in 0..hash_length {
            for j in 0..8 {
                let byte = (self.m_hash[i] >> (8 * j)) as u8;
                result.push_str(&format!("{:02x}", byte));
            }
        }

        let remainder = self.m_bits as usize - hash_length * 64;
        let mut processed = 0;
        while processed < remainder {
            let byte = ((self.m_hash[hash_length] >> processed) & 0xff) as u8;
            result.push_str(&format!("{:02x}", byte));
            processed += 8;
        }

        self.m_hash.copy_from_slice(&old_hash);

        result
    }

    /// Computes the Keccak hash of a memory block.
    pub fn compute(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    /// Computes the Keccak hash of a string, excluding final zero.
    pub fn compute_str(&mut self, text: &str) -> String {
        self.reset();
        self.add(text.as_bytes());
        self.get_hash()
    }

    /// Helper: Rotate left and wrap around
    fn rotate_left(x: u64, num_bits: u8) -> u64 {
        x << num_bits | x >> (64 - num_bits)
    }

    /// Helper: Convert little vs big endian
    fn little_endian(x: u64) -> u64 {
        if cfg!(target_endian = "big") {
            u64::from_be(x)
        } else {
            x
        }
    }

    /// Helper: Return x % 5 for 0 <= x <= 9
    fn mod5(x: usize) -> usize {
        if x < 5 {
            x
        } else {
            x - 5
        }
    }
}

