struct Keccak {
    m_hash: [u64; 25],
    m_buffer: [u8; 200],
    m_num_bytes: usize,
    m_buffer_size: usize,
    m_block_size: usize,
    m_bits: usize,
}

impl Keccak {
    fn new(bits: usize) -> Self {
        let block_size = 200 - 2 * (bits / 8);
        let mut keccak = Keccak {
            m_hash: [0; 25],
            m_buffer: [0; 200],
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_block_size: block_size,
            m_bits: bits,
        };
        keccak.reset();
        keccak
    }

    fn reset(&mut self) {
        self.m_hash.iter_mut().for_each(|x| *x = 0);
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;
    }

    fn process_block(&mut self, data: &[u8]) {
        let data64: &[u64] = unsafe { std::slice::from_raw_parts(data.as_ptr() as *const u64, data.len() / 8) };
        for i in 0..(self.m_block_size / 8) {
            self.m_hash[i] ^= swap(data64[i]);
        }

        for round in 0..KECCAK_ROUNDS {
            let mut coefficients = [0u64; 5];
            for i in 0..5 {
                coefficients[i] = self.m_hash[i] ^ self.m_hash[i + 5] ^ self.m_hash[i + 10] ^ self.m_hash[i + 15] ^ self.m_hash[i + 20];
            }

            for i in 0..5 {
                let one = coefficients[mod5(i + 4)] ^ rotate_left(coefficients[mod5(i + 1)], 1);
                for j in (0..25).step_by(5) {
                    self.m_hash[i + j] ^= one;
                }
            }

            let mut one;
            let mut last = self.m_hash[1];
            one = self.m_hash[10]; self.m_hash[10] = rotate_left(last, 1); last = one;
            one = self.m_hash[7]; self.m_hash[7] = rotate_left(last, 3); last = one;
            one = self.m_hash[11]; self.m_hash[11] = rotate_left(last, 6); last = one;
            one = self.m_hash[17]; self.m_hash[17] = rotate_left(last, 10); last = one;
            one = self.m_hash[18]; self.m_hash[18] = rotate_left(last, 15); last = one;
            one = self.m_hash[3]; self.m_hash[3] = rotate_left(last, 21); last = one;
            one = self.m_hash[5]; self.m_hash[5] = rotate_left(last, 28); last = one;
            one = self.m_hash[16]; self.m_hash[16] = rotate_left(last, 36); last = one;
            one = self.m_hash[8]; self.m_hash[8] = rotate_left(last, 45); last = one;
            one = self.m_hash[21]; self.m_hash[21] = rotate_left(last, 55); last = one;
            one = self.m_hash[24]; self.m_hash[24] = rotate_left(last, 2); last = one;
            one = self.m_hash[4]; self.m_hash[4] = rotate_left(last, 14); last = one;
            one = self.m_hash[15]; self.m_hash[15] = rotate_left(last, 27); last = one;
            one = self.m_hash[23]; self.m_hash[23] = rotate_left(last, 41); last = one;
            one = self.m_hash[19]; self.m_hash[19] = rotate_left(last, 56); last = one;
            one = self.m_hash[13]; self.m_hash[13] = rotate_left(last, 8); last = one;
            one = self.m_hash[12]; self.m_hash[12] = rotate_left(last, 25); last = one;
            one = self.m_hash[2]; self.m_hash[2] = rotate_left(last, 43); last = one;
            one = self.m_hash[20]; self.m_hash[20] = rotate_left(last, 62); last = one;
            one = self.m_hash[14]; self.m_hash[14] = rotate_left(last, 18); last = one;
            one = self.m_hash[22]; self.m_hash[22] = rotate_left(last, 39); last = one;
            one = self.m_hash[9]; self.m_hash[9] = rotate_left(last, 61); last = one;
            one = self.m_hash[6]; self.m_hash[6] = rotate_left(last, 20);
            self.m_hash[1] = rotate_left(one, 44);

            for j in (0..25).step_by(5) {
                let one = self.m_hash[j];
                let two = self.m_hash[j + 1];
                self.m_hash[j] ^= self.m_hash[j + 2] & !two;
                self.m_hash[j + 1] ^= self.m_hash[j + 3] & !self.m_hash[j + 2];
                self.m_hash[j + 2] ^= self.m_hash[j + 4] & !self.m_hash[j + 3];
                self.m_hash[j + 3] ^= one & !self.m_hash[j + 4];
                self.m_hash[j + 4] ^= two & !one;
            }

            self.m_hash[0] ^= XOR_MASKS[round];
        }
    }

    fn add(&mut self, data: &[u8]) {
        let mut current = data;

        if self.m_buffer_size > 0 {
            while !current.is_empty() && self.m_buffer_size < self.m_block_size {
                self.m_buffer[self.m_buffer_size] = current[0];
                self.m_buffer_size += 1;
                current = &current[1..];
            }
        }

        if self.m_buffer_size == self.m_block_size {
            let block = self.m_buffer.clone();
            self.process_block(&block[..self.m_block_size]);
            self.m_num_bytes += self.m_block_size;
            self.m_buffer_size = 0;
        }

        if current.is_empty() {
            return;
        }

        while current.len() >= self.m_block_size {
            self.process_block(&current[..self.m_block_size]);
            current = &current[self.m_block_size..];
            self.m_num_bytes += self.m_block_size;
        }

        while !current.is_empty() {
            self.m_buffer[self.m_buffer_size] = current[0];
            self.m_buffer_size += 1;
            current = &current[1..];
        }
    }

    fn process_buffer(&mut self) {
        let block_size = 200 - 2 * (self.m_bits / 8);
        let mut offset = self.m_buffer_size;
        self.m_buffer[offset] = 1;
        offset += 1;

        while offset < block_size {
            self.m_buffer[offset] = 0;
            offset += 1;
        }

        self.m_buffer[block_size - 1] |= 0x80;
        let block = self.m_buffer.clone();
        self.process_block(&block[..block_size]);
    }

    fn get_hash(&mut self) -> String {
        let mut old_hash = [0u64; 25];
        old_hash.copy_from_slice(&self.m_hash);

        self.process_buffer();

        let dec2hex = b"0123456789abcdef";
        let hash_length = self.m_bits / 64;
        let mut result = String::new();

        for i in 0..hash_length {
            for j in 0..8 {
                let one_byte = (self.m_hash[i] >> (8 * j)) as u8;
                result.push(dec2hex[(one_byte >> 4) as usize] as char);
                result.push(dec2hex[(one_byte & 0x0F) as usize] as char);
            }
        }

        let remainder = self.m_bits - (hash_length * 64);
        let mut processed = 0;
        while processed < remainder {
            let one_byte = (self.m_hash[hash_length] >> processed) as u8;
            result.push(dec2hex[(one_byte >> 4) as usize] as char);
            result.push(dec2hex[(one_byte & 0x0F) as usize] as char);
            processed += 8;
        }

        self.m_hash.copy_from_slice(&old_hash);
        result
    }

    fn hash_data(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    fn hash_string(&mut self, text: &str) -> String {
        self.reset();
        self.add(text.as_bytes());
        self.get_hash()
    }
}

