        let mut processed = 0;

        while processed < remainder {
            let byte = (self.m_hash[hash_len] >> processed) as u8;
            write!(result, "{:02x}", byte).unwrap();
            processed += 8;
        }

        self.m_hash = old_hash;
        result
    }
