    (x >> 56) |
    ((x >> 40) & 0x000000000000FF00) |
    ((x >> 24) & 0x0000000000FF0000) |
    ((x >> 8) & 0x00000000FF000000) |
    ((x << 8) & 0x000000FF00000000) |
    ((x << 24) & 0x0000FF0000000000) |
    ((x << 40) & 0x00FF000000000000) |
    (x << 56)
}

