            }
        }

        let data64: &[u64] = unsafe { &*(data.as_ptr() as *const [u64; 25]) };
        for i in 0..(self.m_block_size / 8) {
            self.m_hash[i] ^= little_endian(data64[i]);
        }

        for round in 0..KeccakRounds {
            // Theta
            let mut coefficients: [u64; 5] = [0; 5];
            for i in 0..5 {
                coefficients[i] = self.m_hash[i] ^ self.m_hash[i + 5] ^ self.m_hash[i + 10] ^ self.m_hash[i + 15] ^ self.m_hash[i + 20];
            }

            for i in 0..5 {
                let one = coefficients[mod5(i + 4)] ^ rotate_left(coefficients[mod5(i + 1)], 1);
                for j in (0..StateSize).step_by(5) {
                    self.m_hash[i + j] ^= one;
                }
            }

            // Rho Pi
            let mut last = self.m_hash[1];
            let mut one;
            let transformed = [
                (10, 1), (7, 3), (11, 6), (17, 10), (18, 15),
                (3, 21), (5, 28), (16, 36), (8, 45), (21, 55),
                (24, 2), (4, 14), (15, 27), (23, 41), (19, 56),
                (13, 8), (12, 25), (2, 43), (20, 62), (14, 18),
                (22, 39), (9, 61), (6, 20) // Last transformation on index 1
            ];

            for &(index, shift) in &transformed {
                one = self.m_hash[index];
                self.m_hash[index] = rotate_left(last, shift);
                last = one;
            }
            self.m_hash[1] = rotate_left(last, 44);

            // Chi
            for j in (0..StateSize).step_by(5) {
                let one = self.m_hash[j];
                let two = self.m_hash[j + 1];

                self.m_hash[j] ^= self.m_hash[j + 2] & !two;
                self.m_hash[j + 1] ^= self.m_hash[j + 3] & !self.m_hash[j + 2];
                self.m_hash[j + 2] ^= self.m_hash[j + 4] & !self.m_hash[j + 3];
                self.m_hash[j + 3] ^= one & !self.m_hash[j + 4];
                self.m_hash[j + 4] ^= two & !one;
            }

            // Iota
            self.m_hash[0] ^= XorMasks[round];
        }
    }

    /// add arbitrary number of bytes
    fn add(&mut self, data: &[u8]) {
        let mut current = data;

        if self.m_buffer_size > 0 {
            while !current.is_empty() && self.m_buffer_size < self.m_block_size {
                self.m_buffer[self.m_buffer_size] = current[0];
                current = &current[1..];
                self.m_buffer_size += 1;
            }
        }

        if self.m_buffer_size == self.m_block_size {
            let buffer_copy = self.m_buffer.clone();
            Keccak::process_block(self, &buffer_copy);
            self.m_num_bytes += self.m_block_size;
            self.m_buffer_size = 0;
        }

        if current.is_empty() {
            return;
        }

        while current.len() >= self.m_block_size {
            self.process_block(current);
            self.m_num_bytes += self.m_block_size;
            current = &current[self.m_block_size..];
        }

        for &byte in current {
            self.m_buffer[self.m_buffer_size] = byte;
            self.m_buffer_size += 1;
        }
    }

    /// process everything left in the internal buffer
    fn process_buffer(&mut self) {
        let block_size = 200 - 2 * (self.m_bits as usize / 8);

        self.m_buffer[self.m_buffer_size] = 1;
        for byte in &mut self.m_buffer[self.m_buffer_size + 1..block_size] {
            *byte = 0;
        }
        self.m_buffer[block_size - 1] |= 0x80;

        let buffer_copy = self.m_buffer.clone();
        Keccak::process_block(self, &buffer_copy);
    }

    /// return latest hash as 16 hex characters
    fn get_hash(&mut self) -> String {
        let old_hash = self.m_hash;
        self.process_buffer();

        const DEC2HEX: &[u8; 16] = b"0123456789abcdef";
        let hash_length = self.m_bits as usize / 64;
        let mut result = String::new();

        for i in 0..hash_length {
            for j in 0..8 {
                let one_byte = (self.m_hash[i] >> (8 * j)) as u8;
                result.push(DEC2HEX[(one_byte >> 4) as usize] as char);
                result.push(DEC2HEX[(one_byte & 0x0F) as usize] as char);
            }
        }

        let remainder = self.m_bits as usize - hash_length * 64;
        let mut processed = 0;
        while processed < remainder {
            let one_byte = (self.m_hash[hash_length] >> processed) as u8;
            result.push(DEC2HEX[(one_byte >> 4) as usize] as char);
            result.push(DEC2HEX[(one_byte & 0x0F) as usize] as char);

            processed += 8;
        }

        self.m_hash = old_hash;
        result
    }

    /// compute Keccak hash of a memory block
    fn compute_hash(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    /// compute Keccak hash of a string, excluding final zero
    fn compute_hash_str(&mut self, text: &str) -> String {
        self.reset();
        self.add(text.as_bytes());
        self.get_hash()
    }
}

const KeccakRounds: usize = 24;
const XorMasks: [u64; KeccakRounds] = [
    0x0000000000000001, 0x0000000000008082, 0x800000000000808A,
    0x8000000080008000, 0x000000000000808B, 0x0000000080000001,
    0x8000000080008081, 0x8000000000008009, 0x000000000000008A,
