impl Keccak {
    pub fn new(bits: Bits) -> Self {
        let block_size = match bits {
            Bits::B224 => 200 - 2 * (224 / 8),
            Bits::B256 => 200 - 2 * (256 / 8),
            Bits::B384 => 200 - 2 * (384 / 8),
            Bits::B512 => 200 - 2 * (512 / 8),
