        keccak.reset();
        keccak
    }

    pub fn reset(&mut self) {
        for i in 0..STATE_SIZE {
            self.m_hash[i] = 0;
        }
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;
    }

    fn rotate_left(x: u64, num_bits: u8) -> u64 {
        (x << num_bits as u64) | (x >> (64 - num_bits) as u64)
    }

    fn swap(x: u64) -> u64 {
        x.swap_bytes()
    }

    fn mod5(x: usize) -> usize {
        if x < 5 {
            x
        } else {
            x - 5
        }
