                let one = coefficients[Self::mod5(i + 4)]
                    ^ Self::rotate_left(coefficients[Self::mod5(i + 1)], 1);
                self.m_hash[i] ^= one;
                self.m_hash[i + 5] ^= one;
                self.m_hash[i + 10] ^= one;
                self.m_hash[i + 15] ^= one;
                self.m_hash[i + 20] ^= one;
