            let mut last = self.m_hash[1];
            let mut one;

            one = self.m_hash[10];
            self.m_hash[10] = Self::rotate_left(last, 1);
            last = one;
            one = self.m_hash[7];
            self.m_hash[7] = Self::rotate_left(last, 3);
            last = one;
            one = self.m_hash[11];
            self.m_hash[11] = Self::rotate_left(last, 6);
            last = one;
            one = self.m_hash[17];
            self.m_hash[17] = Self::rotate_left(last, 10);
            last = one;
            one = self.m_hash[18];
            self.m_hash[18] = Self::rotate_left(last, 15);
            last = one;
            one = self.m_hash[3];
            self.m_hash[3] = Self::rotate_left(last, 21);
            last = one;
            one = self.m_hash[5];
            self.m_hash[5] = Self::rotate_left(last, 28);
            last = one;
