                0x8000000080008081, 0x8000000000008080, 0x0000000080000001, 0x8000000080008008,
            ];
            self.m_hash[0] ^= XOR_MASKS[round];
        }
    }

    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;

        if self.m_buffer_size > 0 {
            while !current.is_empty() && self.m_buffer_size < self.m_block_size {
                self.m_buffer[self.m_buffer_size] = current[0];
                self.m_buffer_size += 1;
                current = &current[1..];
            }
        }

        if self.m_buffer_size == self.m_block_size {
            let block = self.m_buffer[..self.m_block_size].to_vec(); // create a separate block
            self.process_block(&block);
            self.m_num_bytes += self.m_block_size;
            self.m_buffer_size = 0;
        }

        while current.len() >= self.m_block_size {
            let block = current[0..self.m_block_size].to_vec(); // create a separate block
            self.process_block(&block);
            current = &current[self.m_block_size..];
            self.m_num_bytes += self.m_block_size;
        }

        while !current.is_empty() {
            self.m_buffer[self.m_buffer_size] = current[0];
            self.m_buffer_size += 1;
            current = &current[1..];
        }
    }

    pub fn process_buffer(&mut self) {
        let block_size = 200 - 2 * (self.m_bits as usize);

        let mut offset = self.m_buffer_size;
        self.m_buffer[offset] = 1;
        offset += 1;

        while offset < block_size {
            self.m_buffer[offset] = 0;
            offset += 1;
        }

        self.m_buffer[block_size - 1] |= 0x80;

        let block = self.m_buffer[..block_size].to_vec(); // create a separate block
        self.process_block(&block);
    }

    pub fn get_hash(&mut self) -> String {
        let old_hash = self.m_hash;

        self.process_buffer();

        let mut result = String::new();

        let hash_length = match self.m_bits {
            Bits::B224 => 224 / 8,
            Bits::B256 => 256 / 8,
            Bits::B384 => 384 / 8,
            Bits::B512 => 512 / 8,
        };

        for i in 0..hash_length {
            for j in 0..8 {
                let byte = (self.m_hash[i] >> (8 * j)) as u8;
                result.push_str(&format!("{:02x}", byte));
            }
        }

        let remainder = match self.m_bits {
            Bits::B224 => 224 % 8,
            Bits::B256 => 256 % 8,
            Bits::B384 => 384 % 8,
            Bits::B512 => 512 % 8,
        };

        if remainder > 0 {
            let processed = 8 * hash_length;
            let byte = (self.m_hash[hash_length] >> processed) as u8;
            result.push_str(&format!("{:02x}", byte));
        }

        self.m_hash = old_hash;

        result
    }

    pub fn hash_memory(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    pub fn hash_string(&mut self, text: &str) -> String {
        self.reset();
        self.add(text.as_bytes());
        self.get_hash()
    }
}

