const KeccakRounds: usize = 24;
const XorMasks: [u64; KeccakRounds] = [
    0x0000000000000001, 0x0000000000008082, 0x800000000000808a,
    0x8000000080008000, 0x000000000000808b, 0x0000000080000001,
    0x8000000080008081, 0x8000000000008009, 0x000000000000008a,
    0x0000000000000088, 0x0000000080008009, 0x000000008000000a,
    0x000000008000808b, 0x800000000000008b, 0x8000000000008089,
    0x8000000000008003, 0x8000000000008002, 0x8000000000000080,
    0x000000000000800a, 0x800000008000000a, 0x8000000080008081,
    0x8000000000008080, 0x0000000080000001, 0x8000000080008008,
];

fn rotate_left(x: u64, num_bits: u32) -> u64 {
    (x << num_bits) | (x >> (64 - num_bits))
}

#[cfg(target_endian = "big")]
fn swap(x: u64) -> u64 {
    x.swap_bytes()
}

#[cfg(not(target_endian = "big"))]
fn swap(x: u64) -> u64 {
    x
}

fn mod5(x: usize) -> usize {
    if x < 5 {
        x
    } else {
        x - 5
    }
}

pub struct Keccak {
    m_hash: [u64; 25],
    m_num_bytes: usize,
    m_buffer_size: usize,
    m_block_size: usize,
    m_bits: usize,
    m_buffer: [u8; 200],
}

impl Keccak {
    pub fn new(bits: usize) -> Self {
        let block_size = 200 - 2 * (bits / 8);
        let mut keccak = Keccak {
            m_hash: [0; 25],
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_block_size: block_size,
            m_bits: bits,
            m_buffer: [0; 200],
        };
        keccak.reset();
        keccak
    }

    pub fn reset(&mut self) {
        for i in 0..self.m_hash.len() {
            self.m_hash[i] = 0;
        }
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;
    }

    fn process_block(&mut self, data: &[u8]) {
        let data64: &[u64] = unsafe { std::slice::from_raw_parts(data.as_ptr() as *const u64, data.len() / 8) };
        // mix data into state
        for i in 0..(self.m_block_size / 8) {
            self.m_hash[i] ^= swap(data64[i]);
        }

        // re-compute state
        for round in 0..KeccakRounds {
            // Theta
            let mut coefficients = [0u64; 5];
            for i in 0..5 {
                coefficients[i] = self.m_hash[i]
                    ^ self.m_hash[i + 5]
                    ^ self.m_hash[i + 10]
                    ^ self.m_hash[i + 15]
                    ^ self.m_hash[i + 20];
            }

            for i in 0..5 {
                let one = coefficients[mod5(i + 4)] ^ rotate_left(coefficients[mod5(i + 1)], 1);
                for j in (0..25).step_by(5).filter(|&j| j + i < 25) {
                    self.m_hash[j + i] ^= one;
                }
            }

            // Rho Pi
            let mut last = self.m_hash[1];
            let indices = [
                (10, 1), (7, 3), (11, 6), (17, 10), (18, 15),
                (3, 21), (5, 28), (16, 36), (8, 45), (21, 55),
                (24, 2), (4, 14), (15, 27), (23, 41), (19, 56),
                (13, 8), (12, 25), (2, 43), (20, 62), (14, 18),
                (22, 39), (9, 61), (6, 20), (1, 44)
            ];
            for &(idx, shift) in indices.iter() {
                let one = self.m_hash[idx];
                self.m_hash[idx] = rotate_left(last, shift);
                last = one;
            }

            // Chi
            for j in (0..self.m_hash.len()).step_by(5) {
                let one = self.m_hash[j];
                let two = self.m_hash[j + 1];

                self.m_hash[j] ^= self.m_hash[j + 2] & !two;
                self.m_hash[j + 1] ^= self.m_hash[j + 3] & !self.m_hash[j + 2];
                self.m_hash[j + 2] ^= self.m_hash[j + 4] & !self.m_hash[j + 3];
                self.m_hash[j + 3] ^= one & !self.m_hash[j + 4];
                self.m_hash[j + 4] ^= two & !one;
            }

            // Iota
            self.m_hash[0] ^= XorMasks[round];
        }
    }

    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;

        if self.m_buffer_size > 0 {
            while current.len() > 0 && self.m_buffer_size < self.m_block_size {
                self.m_buffer[self.m_buffer_size] = current[0];
                self.m_buffer_size += 1;
                current = &current[1..];
            }
        }

        // full buffer
        if self.m_buffer_size == self.m_block_size {
            let block = self.m_buffer.clone();
            self.process_block(&block[..self.m_block_size]);
            self.m_num_bytes += self.m_block_size;
            self.m_buffer_size = 0;
        }

        // process full blocks
        while current.len() >= self.m_block_size {
            self.process_block(&current[..self.m_block_size]);
            current = &current[self.m_block_size..];
            self.m_num_bytes += self.m_block_size;
        }

        // keep remaining bytes in buffer
        while !current.is_empty() {
            self.m_buffer[self.m_buffer_size] = current[0];
            self.m_buffer_size += 1;
            current = &current[1..];
        }
    }

    fn process_buffer(&mut self) {
        let block_size = 200 - 2 * (self.m_bits / 8);

        // add padding
        let mut offset = self.m_buffer_size;
        self.m_buffer[offset] = 1;
        offset += 1;

        // fill with zeros
        while offset < block_size {
            self.m_buffer[offset] = 0;
            offset += 1;
        }

        // add single set bit
        self.m_buffer[block_size - 1] |= 0x80;
        let block = self.m_buffer.clone();
        self.process_block(&block[..block_size]);
    }

    pub fn get_hash(&mut self) -> String {
        // save hash state
        let old_hash = self.m_hash;

        // process remaining bytes
        self.process_buffer();

        // convert hash to string
        let dec2hex = b"0123456789abcdef";
        let hash_length = self.m_bits / 64;

        let mut result = String::new();
        for &hash_part in &self.m_hash[..hash_length] {
            for byte_idx in 0..8 {
                let one_byte = (hash_part >> (8 * byte_idx)) as u8;
                result.push(dec2hex[(one_byte >> 4) as usize] as char);
                result.push(dec2hex[(one_byte & 0xf) as usize] as char);
            }
        }

        // Keccak224's last entry in m_hash provides only 32 bits instead of 64 bits
        let remainder = self.m_bits - hash_length * 64;
        let mut processed = 0;
        while processed < remainder {
            let one_byte = (self.m_hash[hash_length] >> processed) as u8;
            result.push(dec2hex[(one_byte >> 4) as usize] as char);
            result.push(dec2hex[(one_byte & 0xf) as usize] as char);
            processed += 8;
        }

        // restore state
        self.m_hash = old_hash;
        result
    }

    pub fn hash_memory(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    pub fn hash_string(&mut self, text: &str) -> String {
        self.reset();
        self.add(text.as_bytes());
        self.get_hash()
    }
}

