    /// add arbitrary number of bytes
    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;

        if self.m_buffer_size > 0 {
            while !current.is_empty() && self.m_buffer_size < BlockSize {
                self.m_buffer[self.m_buffer_size] = current[0];
                self.m_buffer_size += 1;
                current = &current[1..];
            }
        }

        // full buffer
        if self.m_buffer_size == BlockSize {
            let buffer_copy = self.m_buffer;
            self.process_block(&buffer_copy);
            self.m_num_bytes += BlockSize;
            self.m_buffer_size = 0;
        }

        // no more data ?
        if current.is_empty() {
            return;
        }

        // process full blocks
        while current.len() >= BlockSize {
            self.process_block(&current[..BlockSize]);
            current = &current[BlockSize..];
            self.m_num_bytes += BlockSize;
        }

        // keep remaining bytes in buffer
        while !current.is_empty() {
            self.m_buffer[self.m_buffer_size] = current[0];
            self.m_buffer_size += 1;
            current = &current[1..];
        }
    }

    /// process final block, less than 64 bytes
    fn process_buffer(&mut self) {
        // the input bytes are considered as bits strings, where the first bit is the most significant bit of the byte

        // - append "1" bit to message
        // - append "0" bits until message length in bit mod 512 is 448
        // - append length as 64 bit integer

        // number of bits
        let mut padded_length = self.m_buffer_size * 8;

        // plus one bit set to 1 (always appended)
        padded_length += 1;

        // number of bits must be (numBits % 512) = 448
        let lower11bits = padded_length & 511;
        if lower11bits <= 448 {
            padded_length += 448 - lower11bits;
        } else {
            padded_length += 512 + 448 - lower11bits;
        }
        // convert from bits to bytes
        padded_length /= 8;

        // only needed if additional data flows over into a second block
        let mut extra = [0u8; BlockSize];

        // append a "1" bit, 128 => binary 10000000
        if self.m_buffer_size < BlockSize {
            self.m_buffer[self.m_buffer_size] = 128;
        } else {
            extra[0] = 128;
        }

        let mut i = self.m_buffer_size + 1;
        while i < BlockSize {
            self.m_buffer[i] = 0;
            i += 1;
        }
        while i < padded_length {
            extra[i - BlockSize] = 0;
            i += 1;
        }

        // add message length in bits as 64 bit number
        let mut msg_bits = 8 * (self.m_num_bytes + self.m_buffer_size);
        // find right position
        let add_length = if padded_length < BlockSize {
            &mut self.m_buffer[padded_length..]
        } else {
            &mut extra[padded_length - BlockSize..]
        };

        // must be little endian
        for j in 0..8 {
            add_length[j] = (msg_bits & 0xFF) as u8;
            msg_bits >>= 8;
        }

        // process blocks
        {
            let buffer_copy = self.m_buffer;
            self.process_block(&buffer_copy);
        }
        // flowed over into a second block ?
        if padded_length > BlockSize {
            self.process_block(&extra);
        }
    }

    /// return latest hash as 32 hex characters
    pub fn get_hash(&mut self) -> String {
        // compute hash (as raw bytes)
        let mut raw_hash = [0u8; HashBytes];
        self.get_hash_bytes(&mut raw_hash);

        // convert to hex string
        let mut result = String::with_capacity(2 * HashBytes);
        for i in 0..HashBytes {
            result.push_str(&format!("{:02x}", raw_hash[i]));
        }

        result
    }

    /// return latest hash as bytes
    pub fn get_hash_bytes(&mut self, buffer: &mut [u8; HashBytes]) {
        // save old hash if buffer is partially filled
        let old_hash = self.m_hash;

        // process remaining bytes
        self.process_buffer();

        let mut current = buffer.iter_mut();
        for &value in &self.m_hash {
            *current.next().unwrap() = (value & 0xFF) as u8;
            *current.next().unwrap() = ((value >> 8) & 0xFF) as u8;
            *current.next().unwrap() = ((value >> 16) & 0xFF) as u8;
            *current.next().unwrap() = ((value >> 24) & 0xFF) as u8;
        }

        // restore old hash
        self.m_hash = old_hash;
    }

    /// compute MD5 of a memory block
    pub fn compute_from_bytes(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
