    /// Add arbitrary number of bytes
    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;

        if self.m_buffer_size > 0 {
            while !current.is_empty() && self.m_buffer_size < BLOCK_SIZE {
                self.m_buffer[self.m_buffer_size] = current[0];
                self.m_buffer_size += 1;
                current = &current[1..];
            }
        }

        // Full buffer
        if self.m_buffer_size == BLOCK_SIZE {
            let buffer_copy = self.m_buffer; // Copy to a temporary variable
            self.process_block(&buffer_copy);
            self.m_num_bytes += BLOCK_SIZE as u64;
            self.m_buffer_size = 0;
        }

        // Process full blocks
        while current.len() >= BLOCK_SIZE {
            let block = current[..BLOCK_SIZE].try_into().unwrap();
            self.process_block(block);
            self.m_num_bytes += BLOCK_SIZE as u64;
            current = &current[BLOCK_SIZE..];
        }

        // Keep remaining bytes in buffer
        if !current.is_empty() {
            let data_len = current.len();
            self.m_buffer[self.m_buffer_size..self.m_buffer_size + data_len].copy_from_slice(current);
            self.m_buffer_size += data_len;
        }
    }

    /// Process final block, less than 64 bytes
    fn process_buffer(&mut self) {
        // The input bytes are considered as bit strings, where the first bit is the most significant bit of the byte

        // - Append "1" bit to message
        // - Append "0" bits until message length in bit mod 512 is 448
        // - Append length as 64 bit integer

        // Number of bits
        let mut padded_length = self.m_buffer_size * 8;

        // Plus one bit set to 1 (always appended)
        padded_length += 1;

        // Number of bits must be (numBits % 512) = 448
        let lower11bits = padded_length % 512;
        if lower11bits <= 448 {
            padded_length += 448 - lower11bits;
        } else {
            padded_length += 512 + 448 - lower11bits;
        }
        // Convert from bits to bytes
        padded_length /= 8;

        // Only needed if additional data flows over into a second block
        let mut extra = [0u8; BLOCK_SIZE];

        // Append a "1" bit, 128 => binary 10000000
        if self.m_buffer_size < BLOCK_SIZE {
            self.m_buffer[self.m_buffer_size] = 128;
        } else {
            extra[0] = 128;
        }

        for i in self.m_buffer_size + 1..BLOCK_SIZE {
            self.m_buffer[i] = 0;
        }
        for i in BLOCK_SIZE..padded_length {
            extra[i - BLOCK_SIZE] = 0;
        }

        // Add message length in bits as 64 bit number
        let mut msg_bits = 8 * (self.m_num_bytes + self.m_buffer_size as u64);
        let mut add_length_position = if padded_length < BLOCK_SIZE {
            &mut self.m_buffer[padded_length] as *mut u8
        } else {
            &mut extra[padded_length - BLOCK_SIZE] as *mut u8
        };

        // Must be little endian
        for _ in 0..8 {
            unsafe {
                std::ptr::write(add_length_position, msg_bits as u8);
                msg_bits >>= 8;
                add_length_position = add_length_position.add(1);
            }
        }

        // Process blocks
        {
            let buffer_copy = self.m_buffer; // Copy to a temporary variable
            self.process_block(&buffer_copy);
        }
        // Flowed over into a second block?
        if padded_length > BLOCK_SIZE {
            self.process_block(&extra);
        }
    }

    /// Return latest hash as 32 hex characters
    pub fn get_hash(&mut self) -> String {
        // Compute hash (as raw bytes)
        let mut raw_hash = [0u8; HASH_BYTES];
        self.get_hash_bytes(&mut raw_hash);

        // Convert to hex string
        let mut result = String::with_capacity(2 * HASH_BYTES);
        for byte in &raw_hash {
            result.push_str(&format!("{:02x}", byte));
        }

        result
    }

    /// Return latest hash as bytes
    fn get_hash_bytes(&mut self, buffer: &mut [u8; HASH_BYTES]) {
        // Save old hash if buffer is partially filled
        let old_hash = self.m_hash;

        // Process remaining bytes
        self.process_buffer();

        let mut buffer_pos = 0;
        for &h in &self.m_hash {
            buffer[buffer_pos] = (h & 0xFF) as u8;
            buffer[buffer_pos + 1] = ((h >> 8) & 0xFF) as u8;
            buffer[buffer_pos + 2] = ((h >> 16) & 0xFF) as u8;
            buffer[buffer_pos + 3] = ((h >> 24) & 0xFF) as u8;
            buffer_pos += 4;
        }

        // Restore old hash
        self.m_hash = old_hash;
    }

    /// Compute MD5 of a memory block
    pub fn compute(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    /// Compute MD5 of a string, excluding final zero
    pub fn compute_str(&mut self, text: &str) -> String {
        self.reset();
        self.add(text.as_bytes());
        self.get_hash()
    }
}

fn main() {
    let mut md5 = MD5::new();
    let hash = md5.compute_str("hello world");
    println!("MD5 hash of 'hello world': {}", hash);
}

