    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;
        self.m_num_bytes += data.len() as u64;

        if self.m_buffer_size > 0 {
            let mut remaining_buffer_size = BLOCK_SIZE - self.m_buffer_size;
            if data.len() < remaining_buffer_size {
                remaining_buffer_size = data.len();
            }

            self.m_buffer[self.m_buffer_size..self.m_buffer_size + remaining_buffer_size]
                .copy_from_slice(&data[..remaining_buffer_size]);
            self.m_buffer_size += remaining_buffer_size;
            current = &data[remaining_buffer_size..];

            if self.m_buffer_size == BLOCK_SIZE {
                let block = self.m_buffer;
                self.process_block(&block);
                self.m_buffer_size = 0;
            }
        }

        while current.len() >= BLOCK_SIZE {
            let block: &[u8; BLOCK_SIZE] = current[0..BLOCK_SIZE].try_into().unwrap();
            self.process_block(block);
            current = &current[BLOCK_SIZE..];
        }

        if !current.is_empty() {
            self.m_buffer[..current.len()].copy_from_slice(current);
            self.m_buffer_size = current.len();
        }
    }

    pub fn process_buffer(&mut self) {
        let pad_length = if self.m_buffer_size < 56 {
            56 - self.m_buffer_size
        } else {
            64 + 56 - self.m_buffer_size
        };

        self.m_buffer[self.m_buffer_size] = 0x80;
        self.m_buffer_size += 1;

        for _ in 0..(pad_length - 1) {
            if self.m_buffer_size < 64 {
                self.m_buffer[self.m_buffer_size] = 0;
                self.m_buffer_size += 1;
            }
        }

        let bit_count = 8 * self.m_num_bytes;
        let bit_count_bytes = bit_count.to_le_bytes();
        if self.m_buffer_size < 60 {
            self.m_buffer[56..64].copy_from_slice(&bit_count_bytes);
            let block = self.m_buffer;
            self.process_block(&block);
        } else {
            let mut extra = [0u8; BLOCK_SIZE];
            extra[..8].copy_from_slice(&bit_count_bytes);
            let block = self.m_buffer;
            self.process_block(&block);
            self.process_block(&extra);
        }
    }

    pub fn get_hash(&mut self) -> String {
        let mut raw_hash = [0u8; HASH_BYTES];
        self.get_raw_hash(&mut raw_hash);
        raw_hash.iter().map(|byte| format!("{:02x}", byte)).collect()
    }

    fn get_raw_hash(&mut self, buffer: &mut [u8; HASH_BYTES]) {
        self.process_buffer();

        for (i, h) in self.m_hash.iter().enumerate() {
            buffer[i * 4..(i + 1) * 4].copy_from_slice(&h.to_le_bytes());
        }
    }

    pub fn compute(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    pub fn compute_from_str(&mut self, text: &str) -> String {
        self.compute(text.as_bytes())
    }
}

fn f1(b: u32, c: u32, d: u32) -> u32 {
    d ^ (b & (c ^ d))
}

fn f2(b: u32, c: u32, d: u32) -> u32 {
    c ^ (d & (b ^ c))
}

fn f3(b: u32, c: u32, d: u32) -> u32 {
    b ^ c ^ d
}

fn f4(b: u32, c: u32, d: u32) -> u32 {
    c ^ (b | !d)
}

