    // Example usage of the MD5 struct
    let mut md5 = MD5::new();
    let hash = md5.compute_from_str("Hello, world!");
    println!("MD5 hash: {}", hash);
}

use std::convert::TryInto;

const BLOCK_SIZE: usize = 64;
const HASH_BYTES: usize = 16;
const HASH_VALUES: usize = 4;

pub struct MD5 {
    m_num_bytes: usize,
    m_buffer_size: usize,
    m_hash: [u32; HASH_VALUES],
    m_buffer: [u8; BLOCK_SIZE],
}

impl MD5 {
    pub fn new() -> Self {
        let mut md5 = MD5 {
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_hash: [0; HASH_VALUES],
            m_buffer: [0; BLOCK_SIZE],
        };
        md5.reset();
        md5
    }

    pub fn reset(&mut self) {
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;
        self.m_hash = [
            0x67452301,
            0xefcdab89,
            0x98badcfe,
            0x10325476,
        ];
    }

    fn process_block(&mut self, data: &[u8]) {
        let mut a = self.m_hash[0];
        let mut b = self.m_hash[1];
        let mut c = self.m_hash[2];
        let mut d = self.m_hash[3];

        let words: &[u32] = &{
            let mut w: [u32; 16] = [0; 16];
            for (i, chunk) in data.chunks(4).enumerate() {
                w[i] = u32::from_le_bytes(chunk.try_into().expect("chunk should be 4 bytes"));
            }
            w
        };

        macro_rules! little_endian {
            ($x:expr) => {
                $x
            };
        }

        macro_rules! rotate {
            ($a:expr, $c:expr) => {
                ($a << $c) | ($a >> (32 - $c))
            };
        }

        fn f1(b: u32, c: u32, d: u32) -> u32 {
            d ^ (b & (c ^ d))
        }

        fn f2(b: u32, c: u32, d: u32) -> u32 {
            c ^ (d & (b ^ c))
        }

        fn f3(b: u32, c: u32, d: u32) -> u32 {
            b ^ c ^ d
        }

        fn f4(b: u32, c: u32, d: u32) -> u32 {
            c ^ (b | !d)
        }

        let apply_rounds = |a: &mut u32, b: &mut u32, c: &mut u32, d: &mut u32, word: u32, s: u32, k: u32| {
            *a = a.wrapping_add(f1(*b, *c, *d) + word + k);
            *a = rotate!(*a, s);
            *a = a.wrapping_add(*b);
        };

        apply_rounds(&mut a, &mut b, &mut c, &mut d, little_endian!(words[0]), 7, 0xd76aa478);
        apply_rounds(&mut d, &mut a, &mut b, &mut c, little_endian!(words[1]), 12, 0xe8c7b756);
        // ... continue for all rounds ...

        self.m_hash[0] = self.m_hash[0].wrapping_add(a);
        self.m_hash[1] = self.m_hash[1].wrapping_add(b);
        self.m_hash[2] = self.m_hash[2].wrapping_add(c);
        self.m_hash[3] = self.m_hash[3].wrapping_add(d);
    }

    fn add(&mut self, data: &[u8]) {
        let mut current = data;
        while self.m_buffer_size > 0 && !current.is_empty() {
            let &byte = current.first().unwrap();
            self.m_buffer[self.m_buffer_size] = byte;
            self.m_buffer_size += 1;
            current = &current[1..];
        }

        if self.m_buffer_size == BLOCK_SIZE {
            let buffer_copy = self.m_buffer;
            self.process_block(&buffer_copy);
            self.m_num_bytes += BLOCK_SIZE;
            self.m_buffer_size = 0;
        }

        while current.len() >= BLOCK_SIZE {
            self.process_block(&current[..BLOCK_SIZE]);
            current = &current[BLOCK_SIZE..];
            self.m_num_bytes += BLOCK_SIZE;
        }

        for &byte in current {
            self.m_buffer[self.m_buffer_size] = byte;
            self.m_buffer_size += 1;
        }
    }

    fn process_buffer(&mut self) {
        let mut padded_length = self.m_buffer_size * 8;
        padded_length += 1;

        let lower11_bits = padded_length & 511;
        if lower11_bits <= 448 {
            padded_length += 448 - lower11_bits;
        } else {
            padded_length += 512 + 448 - lower11_bits;
        }

        padded_length /= 8;

        let mut extra = [0u8; BLOCK_SIZE];

        if self.m_buffer_size < BLOCK_SIZE {
            self.m_buffer[self.m_buffer_size] = 128;
        } else {
            extra[0] = 128;
        }

        for i in (self.m_buffer_size + 1)..BLOCK_SIZE {
            self.m_buffer[i] = 0;
        }

        for i in BLOCK_SIZE..padded_length {
            extra[i - BLOCK_SIZE] = 0;
        }

        let msg_bits = 8 * (self.m_num_bytes + self.m_buffer_size);
        let add_length = if padded_length < BLOCK_SIZE {
            &mut self.m_buffer[padded_length..]
        } else {
            &mut extra[padded_length - BLOCK_SIZE..]
        };

        let mut length_bytes = msg_bits.to_le_bytes().to_vec();
        length_bytes.resize(8, 0);
        add_length[0..8].copy_from_slice(&length_bytes);

        let buffer_copy = self.m_buffer;
        self.process_block(&buffer_copy);
        if padded_length > BLOCK_SIZE {
            self.process_block(&extra);
        }
    }

    pub fn get_hash(&mut self) -> String {
        let mut raw_hash = [0u8; HASH_BYTES];
        self.get_hash_bytes(&mut raw_hash);

        raw_hash.iter().flat_map(|b| {
            let hex_chars = b"0123456789abcdef";
            let high = hex_chars[(b >> 4) as usize];
            let low = hex_chars[(b & 0xF) as usize];
            vec![high as char, low as char]
        }).collect()
    }

    fn get_hash_bytes(&mut self, buffer: &mut [u8; HASH_BYTES]) {
        let old_hash = self.m_hash;
        self.process_buffer();

        let mut current = buffer.iter_mut();
        for &value in &self.m_hash {
            *current.next().unwrap() = (value & 0xFF) as u8;
            *current.next().unwrap() = ((value >> 8) & 0xFF) as u8;
            *current.next().unwrap() = ((value >> 16) & 0xFF) as u8;
            *current.next().unwrap() = ((value >> 24) & 0xFF) as u8;
        }

        self.m_hash = old_hash;
    }

    pub fn compute_hash(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    pub fn compute_hash_from_str(&mut self, text: &str) -> String {
        self.compute_hash(text.as_bytes())
    }
}

fn main() {
    let mut md5 = MD5::new();
    let hash = md5.compute_hash_from_str("Hello World");
    println!("MD5 Hash: {}", hash);
}

const BLOCK_SIZE: usize = 64;
const HASH_WORDS: usize = 4;
const HASH_BYTES: usize = 16;

/// MD5 hasher structure
pub struct MD5 {
    m_num_bytes: u64,          // number of processed bytes
    m_buffer_size: usize,      // buffer size
    m_buffer: [u8; BLOCK_SIZE], // buffer
    m_hash: [u32; HASH_WORDS], // MD5 hash
}

impl MD5 {
    /// Create a new MD5 instance
    pub fn new() -> Self {
        let mut md5 = MD5 {
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_buffer: [0; BLOCK_SIZE],
            m_hash: [0; HASH_WORDS],
        };
        md5.reset();
        md5
    }

    /// Reset the MD5 hasher to its initial state
    pub fn reset(&mut self) {
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;

        // according to RFC 1321
        self.m_hash[0] = 0x67452301;
        self.m_hash[1] = 0xefcdab89;
        self.m_hash[2] = 0x98badcfe;
        self.m_hash[3] = 0x10325476;
    }

    /// Process 64 bytes
    fn process_block(&mut self, data: &[u8]) {
        // get last hash
        let mut a = self.m_hash[0];
        let mut b = self.m_hash[1];
        let mut c = self.m_hash[2];
        let mut d = self.m_hash[3];

        // data represented as 16x 32-bit words
        let mut words = [0u32; 16];
        for i in 0..16 {
            words[i] = u32::from_le_bytes([data[4*i], data[4*i + 1], data[4*i + 2], data[4*i + 3]]);
        }

        // first round
        let process = |a: &mut u32, b: u32, c: u32, d: u32, x: u32, t: u32, s: u32| {
            *a = a.wrapping_add(f1(b, c, d)).wrapping_add(x).wrapping_add(t);
            *a = rotate(*a, s).wrapping_add(b);
        };

        process(&mut a, b, c, d, words[0], 0xd76aa478,  7);
        process(&mut d, a, b, c, words[1], 0xe8c7b756, 12);
        process(&mut c, d, a, b, words[2], 0x242070db, 17);
        process(&mut b, c, d, a, words[3], 0xc1bdceee, 22);
        process(&mut a, b, c, d, words[4], 0xf57c0faf,  7);
        process(&mut d, a, b, c, words[5], 0x4787c62a, 12);
        process(&mut c, d, a, b, words[6], 0xa8304613, 17);
        process(&mut b, c, d, a, words[7], 0xfd469501, 22);
        process(&mut a, b, c, d, words[8], 0x698098d8,  7);
        process(&mut d, a, b, c, words[9], 0x8b44f7af, 12);
        process(&mut c, d, a, b, words[10], 0xffff5bb1, 17);
        process(&mut b, c, d, a, words[11], 0x895cd7be, 22);
        process(&mut a, b, c, d, words[12], 0x6b901122,  7);
        process(&mut d, a, b, c, words[13], 0xfd987193, 12);
        process(&mut c, d, a, b, words[14], 0xa679438e, 17);
        process(&mut b, c, d, a, words[15], 0x49b40821, 22);

        // second round
        let process2 = |a: &mut u32, b: u32, c: u32, d: u32, x: u32, t: u32, s: u32| {
            *a = a.wrapping_add(f2(b, c, d)).wrapping_add(x).wrapping_add(t);
            *a = rotate(*a, s).wrapping_add(b);
        };

        process2(&mut a, b, c, d, words[1], 0xf61e2562,  5);
        process2(&mut d, a, b, c, words[6], 0xc040b340,  9);
        process2(&mut c, d, a, b, words[11], 0x265e5a51, 14);
        process2(&mut b, c, d, a, words[0], 0xe9b6c7aa, 20);
        process2(&mut a, b, c, d, words[5], 0xd62f105d,  5);
        process2(&mut d, a, b, c, words[10], 0x02441453,  9);
        process2(&mut c, d, a, b, words[15], 0xd8a1e681, 14);
        process2(&mut b, c, d, a, words[4], 0xe7d3fbc8, 20);
        process2(&mut a, b, c, d, words[9], 0x21e1cde6,  5);
        process2(&mut d, a, b, c, words[14], 0xc33707d6,  9);
        process2(&mut c, d, a, b, words[3], 0xf4d50d87, 14);
        process2(&mut b, c, d, a, words[8], 0x455a14ed, 20);
        process2(&mut a, b, c, d, words[13], 0xa9e3e905,  5);
        process2(&mut d, a, b, c, words[2], 0xfcefa3f8,  9);
        process2(&mut c, d, a, b, words[7], 0x676f02d9, 14);
        process2(&mut b, c, d, a, words[12], 0x8d2a4c8a, 20);

        // third round
        let process3 = |a: &mut u32, b: u32, c: u32, d: u32, x: u32, t: u32, s: u32| {
            *a = a.wrapping_add(f3(b, c, d)).wrapping_add(x).wrapping_add(t);
            *a = rotate(*a, s).wrapping_add(b);
        };

        process3(&mut a, b, c, d, words[5], 0xfffa3942,  4);
        process3(&mut d, a, b, c, words[8], 0x8771f681, 11);
        process3(&mut c, d, a, b, words[11], 0x6d9d6122, 16);
        process3(&mut b, c, d, a, words[14], 0xfde5380c, 23);
        process3(&mut a, b, c, d, words[1], 0xa4beea44,  4);
        process3(&mut d, a, b, c, words[4], 0x4bdecfa9, 11);
        process3(&mut c, d, a, b, words[7], 0xf6bb4b60, 16);
        process3(&mut b, c, d, a, words[10], 0xbebfbc70, 23);
        process3(&mut a, b, c, d, words[13], 0x289b7ec6,  4);
        process3(&mut d, a, b, c, words[0], 0xeaa127fa, 11);
        process3(&mut c, d, a, b, words[3], 0xd4ef3085, 16);
        process3(&mut b, c, d, a, words[6], 0x04881d05, 23);
        process3(&mut a, b, c, d, words[9], 0xd9d4d039,  4);
        process3(&mut d, a, b, c, words[12], 0xe6db99e5, 11);
        process3(&mut c, d, a, b, words[15], 0x1fa27cf8, 16);
        process3(&mut b, c, d, a, words[2], 0xc4ac5665, 23);

        // fourth round
        let process4 = |a: &mut u32, b: u32, c: u32, d: u32, x: u32, t: u32, s: u32| {
            *a = a.wrapping_add(f4(b, c, d)).wrapping_add(x).wrapping_add(t);
            *a = rotate(*a, s).wrapping_add(b);
        };

        process4(&mut a, b, c, d, words[0], 0xf4292244,  6);
        process4(&mut d, a, b, c, words[7], 0x432aff97, 10);
        process4(&mut c, d, a, b, words[14], 0xab9423a7, 15);
        process4(&mut b, c, d, a, words[5], 0xfc93a039, 21);
        process4(&mut a, b, c, d, words[12], 0x655b59c3,  6);
        process4(&mut d, a, b, c, words[3], 0x8f0ccc92, 10);
        process4(&mut c, d, a, b, words[10], 0xffeff47d, 15);
        process4(&mut b, c, d, a, words[1], 0x85845dd1, 21);
        process4(&mut a, b, c, d, words[8], 0x6fa87e4f,  6);
        process4(&mut d, a, b, c, words[15], 0xfe2ce6e0, 10);
        process4(&mut c, d, a, b, words[6], 0xa3014314, 15);
        process4(&mut b, c, d, a, words[13], 0x4e0811a1, 21);
        process4(&mut a, b, c, d, words[4], 0xf7537e82,  6);
        process4(&mut d, a, b, c, words[11], 0xbd3af235, 10);
        process4(&mut c, d, a, b, words[2], 0x2ad7d2bb, 15);
        process4(&mut b, c, d, a, words[9], 0xeb86d391, 21);

        // update hash
        self.m_hash[0] = self.m_hash[0].wrapping_add(a);
        self.m_hash[1] = self.m_hash[1].wrapping_add(b);
        self.m_hash[2] = self.m_hash[2].wrapping_add(c);
        self.m_hash[3] = self.m_hash[3].wrapping_add(d);
    }

    /// Add arbitrary number of bytes
    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;
        if self.m_buffer_size > 0 {
            while !current.is_empty() && self.m_buffer_size < BLOCK_SIZE {
                self.m_buffer[self.m_buffer_size] = current[0];
                self.m_buffer_size += 1;
                current = &current[1..];
            }
        }

        if self.m_buffer_size == BLOCK_SIZE {
            let buffer_copy = self.m_buffer.clone();
            self.process_block(&buffer_copy);
            self.m_num_bytes += BLOCK_SIZE as u64;
            self.m_buffer_size = 0;
        }

        while current.len() >= BLOCK_SIZE {
            self.process_block(&current[0..BLOCK_SIZE]);
            current = &current[BLOCK_SIZE..];
            self.m_num_bytes += BLOCK_SIZE as u64;
        }

        for &byte in current {
            self.m_buffer[self.m_buffer_size] = byte;
            self.m_buffer_size += 1;
        }
    }

    /// Process final block, less than 64 bytes
    fn process_buffer(&mut self) {
        let mut padded_length = self.m_buffer_size * 8;
        padded_length += 1;

        let lower11_bits = padded_length & 511;
        if lower11_bits <= 448 {
            padded_length += 448 - lower11_bits;
        } else {
            padded_length += 512 + 448 - lower11_bits;
        }

        padded_length /= 8;

        let mut extra = [0u8; BLOCK_SIZE];
        if self.m_buffer_size < BLOCK_SIZE {
            self.m_buffer[self.m_buffer_size] = 128;
        } else {
            extra[0] = 128;
        }

        for i in (self.m_buffer_size + 1)..BLOCK_SIZE {
            self.m_buffer[i] = 0;
        }

        for i in BLOCK_SIZE..padded_length {
            extra[i - BLOCK_SIZE] = 0;
        }

        let mut msg_bits = 8 * (self.m_num_bytes + self.m_buffer_size as u64);
        let add_length_pos = if padded_length < BLOCK_SIZE {
            self.m_buffer[padded_length]
        } else {
            extra[padded_length - BLOCK_SIZE]
        };

        let add_length = add_length_pos as usize;

        for i in 0..8 {
            if add_length < BLOCK_SIZE {
                self.m_buffer[add_length + i] = (msg_bits & 0xFF) as u8;
            } else {
                extra[add_length - BLOCK_SIZE + i] = (msg_bits & 0xFF) as u8;
            }
            msg_bits >>= 8;
        }

        let buffer_copy = self.m_buffer.clone();
        self.process_block(&buffer_copy);
        if padded_length > BLOCK_SIZE {
            self.process_block(&extra);
        }
    }

    /// Return latest hash as 32 hex characters
    pub fn get_hash(&mut self) -> String {
        let mut raw_hash = [0u8; HASH_BYTES];
        self.get_hash_bytes(&mut raw_hash);

        let mut result = String::with_capacity(2 * HASH_BYTES);
        for &byte in &raw_hash {
            result.push(hex_digit(byte >> 4));
            result.push(hex_digit(byte & 0xF));
        }

        result
    }

    /// Return latest hash as bytes
    pub fn get_hash_bytes(&mut self, buffer: &mut [u8; HASH_BYTES]) {
        let mut old_hash = [0u32; HASH_WORDS];
        old_hash.copy_from_slice(&self.m_hash);

        self.process_buffer();

        let mut current = 0;
        for i in 0..HASH_WORDS {
            buffer[current] = (self.m_hash[i] & 0xFF) as u8;
            buffer[current + 1] = ((self.m_hash[i] >> 8) & 0xFF) as u8;
            buffer[current + 2] = ((self.m_hash[i] >> 16) & 0xFF) as u8;
            buffer[current + 3] = ((self.m_hash[i] >> 24) & 0xFF) as u8;

            self.m_hash[i] = old_hash[i];
            current += 4;
        }
    }

    /// Compute MD5 of a memory block
    pub fn compute(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    /// Compute MD5 of a string, excluding final zero
    pub fn compute_str(&mut self, text: &str) -> String {
        self.reset();
        self.add(text.as_bytes());
        self.get_hash()
    }
}

fn f1(b: u32, c: u32, d: u32) -> u32 {
    d ^ (b & (c ^ d))
}

fn f2(b: u32, c: u32, d: u32) -> u32 {
    c ^ (d & (b ^ c))
}

fn f3(b: u32, c: u32, d: u32) -> u32 {
    b ^ c ^ d
}

fn f4(b: u32, c: u32, d: u32) -> u32 {
    c ^ (b | !d)
}

fn rotate(a: u32, c: u32) -> u32 {
    (a << c) | (a >> (32 - c))
}

fn hex_digit(value: u8) -> char {
    const DEC2HEX: &[u8; 16] = b"0123456789abcdef";
    DEC2HEX[value as usize] as char
}

