const BLOCK_SIZE: usize = 64;
const HASH_BYTES: usize = 16;
const HASH_VALUES: usize = 4;

pub struct MD5 {
    m_num_bytes: usize,
    m_buffer_size: usize,
    m_buffer: [u8; BLOCK_SIZE],
    m_hash: [u32; HASH_VALUES],
}

impl MD5 {
    /// same as reset()
    pub fn new() -> Self {
        let mut md5 = MD5 {
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_buffer: [0u8; BLOCK_SIZE],
            m_hash: [0; HASH_VALUES],
        };
        md5.reset();
        md5
    }

    /// restart
    pub fn reset(&mut self) {
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;

        // according to RFC 1321
        self.m_hash[0] = 0x67452301;
        self.m_hash[1] = 0xefcdab89;
        self.m_hash[2] = 0x98badcfe;
        self.m_hash[3] = 0x10325476;
    }

    /// process 64 bytes
    fn process_block(&mut self, data: &[u8]) {
        // get last hash
        let mut a = self.m_hash[0];
        let mut b = self.m_hash[1];
        let mut c = self.m_hash[2];
        let mut d = self.m_hash[3];

        // data represented as 16x 32-bit words
        let words: &[u32; 16] = unsafe { &*(data.as_ptr() as *const [u32; 16]) };

        // computations are little endian, swap data if necessary
        #[cfg(target_endian = "big")]
        fn little_endian(x: u32) -> u32 {
            x.swap_bytes()
        }
        #[cfg(target_endian = "little")]
        fn little_endian(x: u32) -> u32 {
            x
        }

        // first round
        let word0 = little_endian(words[0]);
        a = rotate(a.wrapping_add(f1(b, c, d)).wrapping_add(word0).wrapping_add(0xd76aa478), 7).wrapping_add(b);
        let word1 = little_endian(words[1]);
        d = rotate(d.wrapping_add(f1(a, b, c)).wrapping_add(word1).wrapping_add(0xe8c7b756), 12).wrapping_add(a);
        let word2 = little_endian(words[2]);
        c = rotate(c.wrapping_add(f1(d, a, b)).wrapping_add(word2).wrapping_add(0x242070db), 17).wrapping_add(d);
        let word3 = little_endian(words[3]);
        b = rotate(b.wrapping_add(f1(c, d, a)).wrapping_add(word3).wrapping_add(0xc1bdceee), 22).wrapping_add(c);

        // complete this pattern for every word and every round...
        // ...

        // update hash
        self.m_hash[0] = self.m_hash[0].wrapping_add(a);
        self.m_hash[1] = self.m_hash[1].wrapping_add(b);
        self.m_hash[2] = self.m_hash[2].wrapping_add(c);
        self.m_hash[3] = self.m_hash[3].wrapping_add(d);
    }

    /// add arbitrary number of bytes
    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;

        if self.m_buffer_size > 0 {
            let mut buffer_space = BLOCK_SIZE - self.m_buffer_size;
            if buffer_space > data.len() {
                buffer_space = data.len();
            }

            self.m_buffer[self.m_buffer_size..self.m_buffer_size + buffer_space]
                .copy_from_slice(&data[..buffer_space]);

            self.m_buffer_size += buffer_space;
            self.m_num_bytes += buffer_space;
            current = &current[buffer_space..];

            if self.m_buffer_size == BLOCK_SIZE {
                let buffer_copy = self.m_buffer;
                self.process_block(&buffer_copy);
                self.m_buffer_size = 0;
            }
        }

        while current.len() >= BLOCK_SIZE {
            self.process_block(&current[..BLOCK_SIZE]);
            current = &current[BLOCK_SIZE..];
            self.m_num_bytes += BLOCK_SIZE;
        }

        if current.len() > 0 {
            self.m_buffer[..current.len()].copy_from_slice(current);
            self.m_buffer_size = current.len();
        }
    }

    /// process final block, less than 64 bytes
    fn process_buffer(&mut self) {
        let mut padded_length = self.m_buffer_size * 8 + 1;

        while padded_length % 512 != 448 {
            padded_length += 8;
        }

        padded_length /= 8;

        let mut extra = [0u8; BLOCK_SIZE];

        let extended_buffer;
        if padded_length > BLOCK_SIZE {
            extended_buffer = &mut extra;
        } else {
            extended_buffer = &mut self.m_buffer;
        }

        extended_buffer[self.m_buffer_size] = 0x80;

        for i in self.m_buffer_size+1..padded_length {
            extended_buffer[i] = 0;
        }

        let msg_bits = (self.m_num_bytes + self.m_buffer_size) * 8;
        let add_length_slice = &mut extended_buffer[padded_length..padded_length+8];
        for (i, byte) in msg_bits.to_le_bytes().iter().enumerate() {
            add_length_slice[i] = *byte;
        }

        let buffer_copy = self.m_buffer;
        self.process_block(&buffer_copy);
        if padded_length > BLOCK_SIZE {
            self.process_block(&extra);
        }
    }

    /// return latest hash as 32 hex characters
    pub fn get_hash(&mut self) -> String {
        let mut raw_hash = [0u8; HASH_BYTES];
        self.get_hash_bytes(&mut raw_hash);

        raw_hash.iter().map(|b| format!("{:02x}", b)).collect()
    }

    /// return latest hash as bytes
    pub fn get_hash_bytes(&mut self, buffer: &mut [u8]) {
        let old_hash = self.m_hash.clone();
        self.process_buffer();

        for (i, hash_val) in self.m_hash.iter().enumerate() {
            buffer[i * 4] = (hash_val & 0xFF) as u8;
            buffer[i * 4 + 1] = ((hash_val >> 8) & 0xFF) as u8;
            buffer[i * 4 + 2] = ((hash_val >> 16) & 0xFF) as u8;
            buffer[i * 4 + 3] = ((hash_val >> 24) & 0xFF) as u8;
        }

        self.m_hash = old_hash;
    }

    /// compute MD5 of a memory block
    pub fn compute(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    /// compute MD5 of a string, excluding final zero
    pub fn compute_from_string(&mut self, text: &str) -> String {
        self.compute(text.as_bytes())
    }
}

