    }

    fn add(&mut self, data: &[u8]) {
        let mut current = data;
        self.num_bytes += data.len() as u64;

        if self.buffer_size > 0 {
            let remaining_space = BLOCK_SIZE - self.buffer_size;
            let to_fill = remaining_space.min(current.len());
            self.buffer[self.buffer_size..self.buffer_size + to_fill]
                .copy_from_slice(&current[..to_fill]);
            self.buffer_size += to_fill;
            current = &current[to_fill..];

            if self.buffer_size == BLOCK_SIZE {
                let tmp_buffer = self.buffer;  // Make a copy to avoid borrow issues
                self.process_block(&tmp_buffer);
                self.buffer_size = 0;
            }
        }

        while current.len() >= BLOCK_SIZE {
            self.process_block(&current[..BLOCK_SIZE]);
            current = &current[BLOCK_SIZE..];
        }

        if !current.is_empty() {
            self.buffer[..current.len()].copy_from_slice(current);
            self.buffer_size = current.len();
        }
    }

    fn process_buffer(&mut self) {
        let padded_length = (self.buffer_size + 1 + size_of::<u64>()) as u64;
        let bit_length = self.num_bytes * 8;
        let mut padding = [0u8; BLOCK_SIZE];
        padding[0] = 128;

        let need_padding_blocks = ((padded_length + BLOCK_SIZE as u64 - 1) / BLOCK_SIZE as u64) as usize;
        for i in 0..need_padding_blocks {
            let block = if i == 0 {
                &mut self.buffer[self.buffer_size..]
            } else {
                &mut padding
            };

            block.fill(0);
            if i == need_padding_blocks - 1 {
                block[BLOCK_SIZE - size_of::<u64>()..].copy_from_slice(&bit_length.to_le_bytes());
            }
            let tmp_block: [u8; BLOCK_SIZE] = block[0..BLOCK_SIZE].try_into().unwrap();
            self.process_block(&tmp_block);
        }
    }

    fn get_hash(&mut self) -> String {
        self.process_buffer();

        let mut result = String::with_capacity(HASH_BYTES * 2);
        for &segment in &self.hash {
            result.push_str(&format!("{:02x}{:02x}{:02x}{:02x}",
                (segment & 0x000000FF),
                (segment & 0x0000FF00) >> 8,
                (segment & 0x00FF0000) >> 16,
                (segment & 0xFF000000) >> 24));
        }

        self.reset();
        result
    }
}

impl MD5 {
    fn from_memory_block(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    fn from_string(&mut self, text: &str) -> String {
        self.reset();
        self.add(text.as_bytes());
        self.get_hash()
    }
}

fn main() {
    let mut md5 = MD5::new();
    let hash = md5.from_string("Hello, World!");
    println!("MD5 Hash: {}", hash);
}

const BLOCK_SIZE: usize = 64;
const HASH_BYTES: usize = 16;
const HASH_VALUES: usize = 4;

pub struct MD5 {
    m_num_bytes: usize,
    m_buffer_size: usize,
    m_hash: [u32; HASH_VALUES],
    m_buffer: [u8; BLOCK_SIZE],
}

impl MD5 {
    /// same as reset()
    pub fn new() -> Self {
        let mut md5 = Self {
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_hash: [0; HASH_VALUES],
            m_buffer: [0; BLOCK_SIZE],
        };
        md5.reset();
        md5
    }

    pub fn reset(&mut self) {
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;
        // according to RFC 1321
        self.m_hash[0] = 0x67452301;
        self.m_hash[1] = 0xefcdab89;
        self.m_hash[2] = 0x98badcfe;
        self.m_hash[3] = 0x10325476;
    }

    fn process_block(&mut self, data: &[u8]) {
        let words: &[u32; 16] = unsafe { &*(data.as_ptr() as *const [u32; 16]) };

