        d = rotate!(d.wrapping_add(f1!(a, b, c)).wrapping_add(little_endian_word!(5)).wrapping_add(0x4787c62a), 12).wrapping_add(a);
        c = rotate!(c.wrapping_add(f1!(d, a, b)).wrapping_add(little_endian_word!(6)).wrapping_add(0xa8304613), 17).wrapping_add(d);
