            e = rotate(e, 30);
            b = b.wrapping_add(rotate(c, 5)).wrapping_add(f2(d, e, a)).wrapping_add(words[offset + 3]).wrapping_add(0x6ed9eba1);
            d = rotate(d, 30);
            a = a.wrapping_add(rotate(b, 5)).wrapping_add(f2(c, d, e)).wrapping_add(words[offset + 4]).wrapping_add(0x6ed9eba1);
