            b = b.wrapping_add(rotate(c, 5)).wrapping_add(f3(d, e, a)).wrapping_add(words[offset + 3]).wrapping_add(0x8f1bbcdc);
            d = rotate(d, 30);
            a = a.wrapping_add(rotate(b, 5)).wrapping_add(f3(c, d, e)).wrapping_add(words[offset + 4]).wrapping_add(0x8f1bbcdc);
            c = rotate(c, 30);
        }

        // fourth round
        for i in 12..16 {
            let offset = 5 * i;
            e = e.wrapping_add(rotate(a, 5)).wrapping_add(f2(b, c, d)).wrapping_add(words[offset]).wrapping_add(0xca62c1d6);
            b = rotate(b, 30);
            d = d.wrapping_add(rotate(e, 5)).wrapping_add(f2(a, b, c)).wrapping_add(words[offset + 1]).wrapping_add(0xca62c1d6);
            a = rotate(a, 30);
            c = c.wrapping_add(rotate(d, 5)).wrapping_add(f2(e, a, b)).wrapping_add(words[offset + 2]).wrapping_add(0xca62c1d6);
            e = rotate(e, 30);
            b = b.wrapping_add(rotate(c, 5)).wrapping_add(f2(d, e, a)).wrapping_add(words[offset + 3]).wrapping_add(0xca62c1d6);
            d = rotate(d, 30);
            a = a.wrapping_add(rotate(b, 5)).wrapping_add(f2(c, d, e)).wrapping_add(words[offset + 4]).wrapping_add(0xca62c1d6);
            c = rotate(c, 30);
        }

        // update hash
        self.m_hash[0] = self.m_hash[0].wrapping_add(a);
        self.m_hash[1] = self.m_hash[1].wrapping_add(b);
        self.m_hash[2] = self.m_hash[2].wrapping_add(c);
        self.m_hash[3] = self.m_hash[3].wrapping_add(d);
        self.m_hash[4] = self.m_hash[4].wrapping_add(e);
    }

    /// add arbitrary number of bytes
    fn add(&mut self, data: &[u8]) {
        let mut current = data;

        if self.m_buffer_size > 0 {
            while !current.is_empty() && self.m_buffer_size < BLOCK_SIZE {
                self.m_buffer[self.m_buffer_size] = current[0];
                self.m_buffer_size += 1;
                current = &current[1..];
            }
        }

        // full buffer
        if self.m_buffer_size == BLOCK_SIZE {
            let buffer_copy = self.m_buffer.clone();
            self.process_block(&buffer_copy);
            self.m_num_bytes += BLOCK_SIZE;
            self.m_buffer_size = 0;
        }

        // no more data ?
        if current.is_empty() {
            return;
        }

        // process full blocks
        while current.len() >= BLOCK_SIZE {
            self.process_block(&current[..BLOCK_SIZE]);
            current = &current[BLOCK_SIZE..];
            self.m_num_bytes += BLOCK_SIZE;
        }

        // keep remaining bytes in buffer
        self.m_buffer[..current.len()].copy_from_slice(current);
        self.m_buffer_size = current.len();
    }

    /// process final block, less than 64 bytes
    fn process_buffer(&mut self) {
        // number of bits
        let mut padded_length = self.m_buffer_size * 8;

        // plus one bit set to 1 (always appended)
        padded_length += 1;

        // number of bits must be (numBits % 512) = 448
        let lower_11_bits = padded_length & 511;
        if lower_11_bits <= 448 {
            padded_length += 448 - lower_11_bits;
        } else {
            padded_length += 512 + 448 - lower_11_bits;
        }
        // convert from bits to bytes
        padded_length /= 8;

        // only needed if additional data flows over into a second block
        let mut extra = [0u8; BLOCK_SIZE];

        // append a "1" bit, 128 => binary 10000000
        if self.m_buffer_size < BLOCK_SIZE {
            self.m_buffer[self.m_buffer_size] = 128;
        } else {
            extra[0] = 128;
        }

        let buffer_end = self.m_buffer_size + 1;
        if buffer_end < BLOCK_SIZE {
            self.m_buffer[buffer_end..BLOCK_SIZE].fill(0);
            extra.fill(0);
        } else {
            extra[(buffer_end - BLOCK_SIZE)..BLOCK_SIZE].fill(0);
        }

        // add message length in bits as 64 bit number
        let msg_bits = (self.m_num_bytes + self.m_buffer_size) * 8;
        let add_length: &mut [u8] = if padded_length < BLOCK_SIZE {
            &mut self.m_buffer[padded_length..]
        } else {
            &mut extra[(padded_length - BLOCK_SIZE)..]
        };

        // must be big endian
        for i in 0..8 {
            add_length[i] = ((msg_bits >> (8 * (7 - i))) & 0xFF) as u8;
        }

        // process blocks
        let buffer_copy = self.m_buffer.clone();
        self.process_block(&buffer_copy);
        // flowed over into a second block ?
        if padded_length > BLOCK_SIZE {
            self.process_block(&extra);
        }
    }

    /// return latest hash as 40 hex characters
    fn get_hash(&mut self) -> String {
        // compute hash (as raw bytes)
        let mut raw_hash = [0u8; HASH_BYTES];
        self.get_hash_bytes(&mut raw_hash);

        // convert to hex string
        let mut result = String::with_capacity(2 * HASH_BYTES);
        for byte in raw_hash.iter() {
            result.push_str(&format!("{:02x}", byte));
        }

        result
    }

    /// return latest hash as bytes
    fn get_hash_bytes(&mut self, buffer: &mut [u8; HASH_BYTES]) {
        // save old hash if buffer is partially filled
        let old_hash = self.m_hash.clone();

        // process remaining bytes
        self.process_buffer();

        for (i, hash_value) in old_hash.iter().enumerate() {
            let byte_offset = 4 * i;
            buffer[byte_offset..byte_offset + 4]
                .copy_from_slice(&hash_value.to_be_bytes());
        }

        // restore old hash
        self.m_hash = old_hash;
    }
}

impl Default for SHA1 {
    fn default() -> Self {
        Self::new()
    }
}

// mix functions for processBlock()
fn f1(b: u32, c: u32, d: u32) -> u32 {
    d ^ (b & (c ^ d))
}

fn f2(b: u32, c: u32, d: u32) -> u32 {
    b ^ c ^ d
}

fn f3(b: u32, c: u32, d: u32) -> u32 {
    (b & c) | (b & d) | (c & d)
}

fn rotate(a: u32, c: u32) -> u32 {
    (a << c) | (a >> (32 - c))
}

