use std::convert::TryInto;

pub struct SHA1 {
    m_num_bytes: usize,
    m_buffer_size: usize,
    m_hash: [u32; 5],
    m_buffer: [u8; SHA1::BLOCK_SIZE],
}

impl Default for SHA1 {
    fn default() -> Self {
        SHA1::new()
    }
}

impl SHA1 {
    const BLOCK_SIZE: usize = 64;
    const HASH_BYTES: usize = 20;
    const HASH_VALUES: usize = 5;

    pub fn new() -> SHA1 {
        let mut sha1 = SHA1 {
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_hash: [0; 5],
            m_buffer: [0; SHA1::BLOCK_SIZE],
        };
        sha1.reset();
        sha1
    }

    pub fn reset(&mut self) {
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;
        self.m_hash = [
            0x67452301,
            0xefcdab89,
            0x98badcfe,
            0x10325476,
            0xc3d2e1f0,
        ];
    }

    fn f1(b: u32, c: u32, d: u32) -> u32 {
        d ^ (b & (c ^ d))
    }

    fn f2(b: u32, c: u32, d: u32) -> u32 {
        b ^ c ^ d
    }

    fn f3(b: u32, c: u32, d: u32) -> u32 {
        (b & c) | (b & d) | (c & d)
    }

    fn rotate(a: u32, c: u32) -> u32 {
        (a << c) | (a >> (32 - c))
    }

    fn swap(x: u32) -> u32 {
        x.swap_bytes()
    }

    pub fn process_block(&mut self, data: &[u8]) {
        assert!(data.len() == SHA1::BLOCK_SIZE);

        let mut words = [0u32; 80];
        for i in 0..16 {
            words[i] = u32::from_be_bytes(data[4 * i..4 * i + 4].try_into().unwrap());
        }

        for i in 16..80 {
            words[i] = Self::rotate(words[i - 3] ^ words[i - 8] ^ words[i - 14] ^ words[i - 16], 1);
        }

        let mut a = self.m_hash[0];
        let mut b = self.m_hash[1];
        let mut c = self.m_hash[2];
        let mut d = self.m_hash[3];
        let mut e = self.m_hash[4];

        for i in 0..4 {
            let offset = 5 * i;
            e = e.wrapping_add(Self::rotate(a, 5))
                .wrapping_add(Self::f1(b, c, d))
                .wrapping_add(words[offset])
                .wrapping_add(0x5a827999);
            b = Self::rotate(b, 30);
            d = d.wrapping_add(Self::rotate(e, 5))
                .wrapping_add(Self::f1(a, b, c))
                .wrapping_add(words[offset + 1])
                .wrapping_add(0x5a827999);
            a = Self::rotate(a, 30);
            c = c.wrapping_add(Self::rotate(d, 5))
                .wrapping_add(Self::f1(e, a, b))
                .wrapping_add(words[offset + 2])
                .wrapping_add(0x5a827999);
            e = Self::rotate(e, 30);
            b = b.wrapping_add(Self::rotate(c, 5))
                .wrapping_add(Self::f1(d, e, a))
                .wrapping_add(words[offset + 3])
                .wrapping_add(0x5a827999);
            d = Self::rotate(d, 30);
            a = a.wrapping_add(Self::rotate(b, 5))
                .wrapping_add(Self::f1(c, d, e))
                .wrapping_add(words[offset + 4])
                .wrapping_add(0x5a827999);
            c = Self::rotate(c, 30);
        }

        for i in 4..8 {
            let offset = 5 * i;
            e = e.wrapping_add(Self::rotate(a, 5))
                .wrapping_add(Self::f2(b, c, d))
                .wrapping_add(words[offset])
                .wrapping_add(0x6ed9eba1);
            b = Self::rotate(b, 30);
            d = d.wrapping_add(Self::rotate(e, 5))
                .wrapping_add(Self::f2(a, b, c))
                .wrapping_add(words[offset + 1])
                .wrapping_add(0x6ed9eba1);
            a = Self::rotate(a, 30);
            c = c.wrapping_add(Self::rotate(d, 5))
                .wrapping_add(Self::f2(e, a, b))
                .wrapping_add(words[offset + 2])
                .wrapping_add(0x6ed9eba1);
            e = Self::rotate(e, 30);
            b = b.wrapping_add(Self::rotate(c, 5))
                .wrapping_add(Self::f2(d, e, a))
                .wrapping_add(words[offset + 3])
                .wrapping_add(0x6ed9eba1);
            d = Self::rotate(d, 30);
            a = a.wrapping_add(Self::rotate(b, 5))
                .wrapping_add(Self::f2(c, d, e))
                .wrapping_add(words[offset + 4])
                .wrapping_add(0x6ed9eba1);
            c = Self::rotate(c, 30);
        }

        for i in 8..12 {
            let offset = 5 * i;
            e = e.wrapping_add(Self::rotate(a, 5))
                .wrapping_add(Self::f3(b, c, d))
                .wrapping_add(words[offset])
                .wrapping_add(0x8f1bbcdc);
            b = Self::rotate(b, 30);
            d = d.wrapping_add(Self::rotate(e, 5))
                .wrapping_add(Self::f3(a, b, c))
                .wrapping_add(words[offset + 1])
                .wrapping_add(0x8f1bbcdc);
            a = Self::rotate(a, 30);
            c = c.wrapping_add(Self::rotate(d, 5))
                .wrapping_add(Self::f3(e, a, b))
                .wrapping_add(words[offset + 2])
                .wrapping_add(0x8f1bbcdc);
            e = Self::rotate(e, 30);
            b = b.wrapping_add(Self::rotate(c, 5))
                .wrapping_add(Self::f3(d, e, a))
                .wrapping_add(words[offset + 3])
                .wrapping_add(0x8f1bbcdc);
            d = Self::rotate(d, 30);
            a = a.wrapping_add(Self::rotate(b, 5))
                .wrapping_add(Self::f3(c, d, e))
                .wrapping_add(words[offset + 4])
                .wrapping_add(0x8f1bbcdc);
            c = Self::rotate(c, 30);
        }

        for i in 12..16 {
            let offset = 5 * i;
            e = e.wrapping_add(Self::rotate(a, 5))
                .wrapping_add(Self::f2(b, c, d))
                .wrapping_add(words[offset])
                .wrapping_add(0xca62c1d6);
            b = Self::rotate(b, 30);
            d = d.wrapping_add(Self::rotate(e, 5))
                .wrapping_add(Self::f2(a, b, c))
                .wrapping_add(words[offset + 1])
                .wrapping_add(0xca62c1d6);
            a = Self::rotate(a, 30);
            c = c.wrapping_add(Self::rotate(d, 5))
                .wrapping_add(Self::f2(e, a, b))
                .wrapping_add(words[offset + 2])
                .wrapping_add(0xca62c1d6);
            e = Self::rotate(e, 30);
            b = b.wrapping_add(Self::rotate(c, 5))
                .wrapping_add(Self::f2(d, e, a))
                .wrapping_add(words[offset + 3])
                .wrapping_add(0xca62c1d6);
            d = Self::rotate(d, 30);
            a = a.wrapping_add(Self::rotate(b, 5))
                .wrapping_add(Self::f2(c, d, e))
                .wrapping_add(words[offset + 4])
                .wrapping_add(0xca62c1d6);
            c = Self::rotate(c, 30);
        }

        self.m_hash[0] = self.m_hash[0].wrapping_add(a);
        self.m_hash[1] = self.m_hash[1].wrapping_add(b);
        self.m_hash[2] = self.m_hash[2].wrapping_add(c);
        self.m_hash[3] = self.m_hash[3].wrapping_add(d);
        self.m_hash[4] = self.m_hash[4].wrapping_add(e);
    }

    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;

        if self.m_buffer_size > 0 {
            let space_left = SHA1::BLOCK_SIZE - self.m_buffer_size;
            let to_copy = space_left.min(current.len());

            self.m_buffer[self.m_buffer_size..self.m_buffer_size + to_copy].copy_from_slice(&current[..to_copy]);
            self.m_buffer_size += to_copy;
            current = &current[to_copy..];
        }

        if self.m_buffer_size == SHA1::BLOCK_SIZE {
            self.process_block(&self.m_buffer.clone());
            self.m_num_bytes += SHA1::BLOCK_SIZE;
            self.m_buffer_size = 0;
        }

        while current.len() >= SHA1::BLOCK_SIZE {
            self.process_block(&current[..SHA1::BLOCK_SIZE]);
            self.m_num_bytes += SHA1::BLOCK_SIZE;
            current = &current[SHA1::BLOCK_SIZE..];
        }

        self.m_buffer[..current.len()].copy_from_slice(current);
        self.m_buffer_size = current.len();
    }

    fn process_buffer(&mut self) {
        let mut padded_length = self.m_buffer_size * 8;

        padded_length += 1;

        let lower11_bits = padded_length % 512;
        if lower11_bits <= 448 {
            padded_length += 448 - lower11_bits;
        } else {
            padded_length += 512 + 448 - lower11_bits;
        }

        padded_length /= 8;

        let mut extra = [0u8; SHA1::BLOCK_SIZE];

        if self.m_buffer_size < SHA1::BLOCK_SIZE {
            self.m_buffer[self.m_buffer_size] = 128;
        } else {
            extra[0] = 128;
        }

        for i in self.m_buffer_size + 1..SHA1::BLOCK_SIZE {
            self.m_buffer[i] = 0;
        }
        for i in SHA1::BLOCK_SIZE..padded_length {
            extra[i - SHA1::BLOCK_SIZE] = 0;
        }

        let msg_bits = (self.m_num_bytes + self.m_buffer_size) as u64 * 8;
        let add_length = if padded_length < SHA1::BLOCK_SIZE {
            &mut self.m_buffer[padded_length..]
        } else {
            &mut extra[padded_length - SHA1::BLOCK_SIZE..]
        };

        add_length[0] = ((msg_bits >> 56) & 0xFF) as u8;
        add_length[1] = ((msg_bits >> 48) & 0xFF) as u8;
        add_length[2] = ((msg_bits >> 40) & 0xFF) as u8;
        add_length[3] = ((msg_bits >> 32) & 0xFF) as u8;
        add_length[4] = ((msg_bits >> 24) & 0xFF) as u8;
        add_length[5] = ((msg_bits >> 16) & 0xFF) as u8;
        add_length[6] = ((msg_bits >> 8) & 0xFF) as u8;
        add_length[7] = (msg_bits & 0xFF) as u8;

        self.process_block(&self.m_buffer.clone());
        if padded_length > SHA1::BLOCK_SIZE {
            self.process_block(&extra);
        }
    }

    pub fn get_hash(&mut self) -> String {
        let mut raw_hash = [0u8; SHA1::HASH_BYTES];
        self.get_hash_bytes(&mut raw_hash);

        raw_hash.iter().map(|&byte| format!("{:02x}", byte)).collect()
    }

    pub fn get_hash_bytes(&mut self, buffer: &mut [u8; SHA1::HASH_BYTES]) {
        assert!(buffer.len() == SHA1::HASH_BYTES);

        let old_hash = self.m_hash;

        self.process_buffer();

        for (i, chunk) in buffer.chunks_mut(4).enumerate() {
            chunk.copy_from_slice(&self.m_hash[i].to_be_bytes());
            self.m_hash[i] = old_hash[i];
        }
    }

    pub fn digest(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    pub fn digest_str(&mut self, text: &str) -> String {
        self.digest(text.as_bytes())
    }
}

fn main() {
    let mut sha1 = SHA1::new();
    let hash = sha1.digest_str("Hello, world!");
    println!("Hash: {}", hash);
}

