const BLOCK_SIZE: usize = 64;
const HASH_BYTES: usize = 20;
const HASH_VALUES: usize = 5;

/// SHA1 struct to handle SHA1 operations
pub struct SHA1 {
    m_num_bytes: usize,
    m_buffer_size: usize,
    m_hash: [u32; HASH_VALUES],
    m_buffer: [u8; BLOCK_SIZE],
}

impl SHA1 {
    /// same as reset()
    pub fn new() -> Self {
        let mut hasher = SHA1 {
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_hash: [0; HASH_VALUES],
            m_buffer: [0; BLOCK_SIZE],
        };
        hasher.reset();
        hasher
    }

    /// restart
    pub fn reset(&mut self) {
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;

        // according to RFC 1321
        self.m_hash[0] = 0x67452301;
        self.m_hash[1] = 0xefcdab89;
        self.m_hash[2] = 0x98badcfe;
        self.m_hash[3] = 0x10325476;
        self.m_hash[4] = 0xc3d2e1f0;
    }

    /// process 64 bytes
    fn process_block(&mut self, data: &[u8]) {
        // get last hash
        let mut a = self.m_hash[0];
        let mut b = self.m_hash[1];
        let mut c = self.m_hash[2];
        let mut d = self.m_hash[3];
        let mut e = self.m_hash[4];

        // data represented as 16x 32-bit words
        let input = unsafe {
            std::slice::from_raw_parts(data.as_ptr() as *const u32, 16)
        };
        // convert to big endian
        let mut words = [0u32; 80];
        for i in 0..16 {
            words[i] = swap(input[i]);
        }

        // extend to 80 words
        for i in 16..80 {
            words[i] = rotate(words[i-3] ^ words[i-8] ^ words[i-14] ^ words[i-16], 1);
        }

        // first round
        macro_rules! round {
            ($f:expr, $k:expr, $i:expr) => {
                let temp = rotate(a, 5)
                    .wrapping_add($f(b, c, d))
                    .wrapping_add(e)
                    .wrapping_add(words[$i])
                    .wrapping_add($k);
                e = d;
                d = c;
                c = rotate(b, 30);
                b = a;
                a = temp;
            };
        }

        let k1 = 0x5a827999u32;
        for i in 0..20 {
            round!(f1, k1, i);
        }

        let k2 = 0x6ed9eba1u32;
        for i in 20..40 {
            round!(f2, k2, i);
        }

        let k3 = 0x8f1bbcdc;
        for i in 40..60 {
            round!(f3, k3, i);
        }

        let k4 = 0xca62c1d6;
        for i in 60..80 {
            round!(f2, k4, i);
        }

        // update hash
        self.m_hash[0] = self.m_hash[0].wrapping_add(a);
        self.m_hash[1] = self.m_hash[1].wrapping_add(b);
        self.m_hash[2] = self.m_hash[2].wrapping_add(c);
        self.m_hash[3] = self.m_hash[3].wrapping_add(d);
        self.m_hash[4] = self.m_hash[4].wrapping_add(e);
    }

    /// add arbitrary number of bytes
    pub fn add(&mut self, data: &[u8]) {
        let mut current = 0;
        let mut num_bytes = data.len();

        if self.m_buffer_size > 0 {
            while num_bytes > 0 && self.m_buffer_size < BLOCK_SIZE {
                self.m_buffer[self.m_buffer_size] = data[current];
                current += 1;
                num_bytes -= 1;
                self.m_buffer_size += 1;
            }
        }

        // full buffer
        if self.m_buffer_size == BLOCK_SIZE {
            let buffer = self.m_buffer;  // create a copy
            self.process_block(&buffer);
            self.m_num_bytes += BLOCK_SIZE;
            self.m_buffer_size = 0;
        }

        // no more data ?
        if num_bytes == 0 {
            return;
        }

        // process full blocks
        while num_bytes >= BLOCK_SIZE {
            self.process_block(&data[current..current + BLOCK_SIZE]);
            current += BLOCK_SIZE;
            self.m_num_bytes += BLOCK_SIZE;
            num_bytes -= BLOCK_SIZE;
        }

        // keep remaining bytes in buffer
        for &byte in &data[current..] {
            self.m_buffer[self.m_buffer_size] = byte;
            self.m_buffer_size += 1;
        }
    }

    /// process final block, less than 64 bytes
    fn process_buffer(&mut self) {
        // number of bits
        let mut padded_length = self.m_buffer_size * 8;

        // plus one bit set to 1 (always appended)
        padded_length += 1;

        // number of bits must be (numBits % 512) = 448
        let lower_11_bits = padded_length & 511;
        if lower_11_bits <= 448 {
            padded_length += 448 - lower_11_bits;
        } else {
            padded_length += 512 + 448 - lower_11_bits;
        }
        // convert from bits to bytes
        padded_length /= 8;

        // only needed if additional data flows over into a second block
        let mut extra = [0u8; BLOCK_SIZE];

        // append a "1" bit, 128 => binary 10000000
        if self.m_buffer_size < BLOCK_SIZE {
            self.m_buffer[self.m_buffer_size] = 128;
        } else {
            extra[0] = 128;
        }

        for i in self.m_buffer_size + 1..BLOCK_SIZE {
            self.m_buffer[i] = 0;
        }
        for i in BLOCK_SIZE..padded_length {
            extra[i - BLOCK_SIZE] = 0;
        }

        // add message length in bits as 64 bit number
        let msg_bits = 8 * (self.m_num_bytes + self.m_buffer_size);
        // find right position
        let add_length = if padded_length < BLOCK_SIZE {
            &mut self.m_buffer[padded_length..]
        } else {
            &mut extra[padded_length - BLOCK_SIZE..]
        };

        // must be big endian
        add_length[0] = ((msg_bits >> 56) & 0xFF) as u8;
        add_length[1] = ((msg_bits >> 48) & 0xFF) as u8;
        add_length[2] = ((msg_bits >> 40) & 0xFF) as u8;
        add_length[3] = ((msg_bits >> 32) & 0xFF) as u8;
        add_length[4] = ((msg_bits >> 24) & 0xFF) as u8;
        add_length[5] = ((msg_bits >> 16) & 0xFF) as u8;
        add_length[6] = ((msg_bits >> 8) & 0xFF) as u8;
        add_length[7] = (msg_bits & 0xFF) as u8;

        // process blocks
        let buffer = self.m_buffer;
        self.process_block(&buffer);
        if padded_length > BLOCK_SIZE {
            self.process_block(&extra);
        }
    }

    /// return latest hash as 40 hex characters
    pub fn get_hash(&mut self) -> String {
        // compute hash (as raw bytes)
        let mut raw_hash = [0u8; HASH_BYTES];
        self.get_hash_bytes(&mut raw_hash);

        // convert to hex string
        let mut result = String::with_capacity(2 * HASH_BYTES);
        for &byte in &raw_hash {
            result.push_str(&format!("{:02x}", byte));
        }

        result
    }

    /// return latest hash as bytes
    pub fn get_hash_bytes(&mut self, buffer: &mut [u8]) {
        // save old hash if buffer is partially filled
        let old_hash = self.m_hash;

        // process remaining bytes
        self.process_buffer();

        let mut current = 0;
        for &value in &self.m_hash {
            buffer[current] = ((value >> 24) & 0xFF) as u8;
            buffer[current + 1] = ((value >> 16) & 0xFF) as u8;
            buffer[current + 2] = ((value >> 8) & 0xFF) as u8;
            buffer[current + 3] = (value & 0xFF) as u8;
            current += 4;
        }

        // restore old hash
        self.m_hash = old_hash;
    }

    /// compute SHA1 of a memory block
    pub fn hash(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    /// compute SHA1 of a string, excluding final zero
    pub fn hash_str(&mut self, text: &str) -> String {
        self.hash(text.as_bytes())
    }
}

fn f1(b: u32, c: u32, d: u32) -> u32 {
    d ^ (b & (c ^ d))
}

fn f2(b: u32, c: u32, d: u32) -> u32 {
    b ^ c ^ d
}

fn f3(b: u32, c: u32, d: u32) -> u32 {
    (b & c) | (b & d) | (c & d)
}

fn rotate(value: u32, shift: u32) -> u32 {
    (value << shift) | (value >> (32 - shift))
}

fn swap(value: u32) -> u32 {
    value.to_be()
}

// Usage example
fn main() {
    let mut hasher = SHA1::new();
    let hash = hasher.hash_str("Hello, world!");
    println!("SHA1: {}", hash);
}

