// Constants used for SHA-1 algorithm
const BLOCK_SIZE: usize = 64;
const HASH_BYTES: usize = 20;
const HASH_VALUES: usize = 5;

/// SHA1 struct representing the hasher state
pub struct SHA1 {
    m_num_bytes: usize,
    m_buffer_size: usize,
    m_hash: [u32; HASH_VALUES],
    m_buffer: [u8; BLOCK_SIZE],
}

impl SHA1 {
    /// Creates a new SHA1 instance and resets its state
    pub fn new() -> Self {
        let mut sha1 = SHA1 {
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_hash: [0; HASH_VALUES],
            m_buffer: [0; BLOCK_SIZE],
        };
        sha1.reset();
        sha1
    }

    /// Resets the SHA1 instance to its initial state
    pub fn reset(&mut self) {
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;

        // According to RFC 1321
        self.m_hash[0] = 0x67452301;
        self.m_hash[1] = 0xefcdab89;
        self.m_hash[2] = 0x98badcfe;
        self.m_hash[3] = 0x10325476;
        self.m_hash[4] = 0xc3d2e1f0;
    }

    /// Processes a block of 64 bytes
    fn process_block(&mut self, data: &[u8]) {
        assert_eq!(data.len(), BLOCK_SIZE);

        // Get last hash
        let mut a = self.m_hash[0];
        let mut b = self.m_hash[1];
        let mut c = self.m_hash[2];
        let mut d = self.m_hash[3];
        let mut e = self.m_hash[4];

        // Data represented as 16x 32-bit words
        let input: &[u32] = unsafe { std::slice::from_raw_parts(data.as_ptr() as *const u32, 16) };

        // Convert to big endian
        let mut words = [0u32; 80];
        for i in 0..16 {
            words[i] = u32::from_be(input[i]);
        }

        // Extend to 80 words
        for i in 16..80 {
            words[i] = rotate(words[i - 3] ^ words[i - 8] ^ words[i - 14] ^ words[i - 16], 1);
        }

        // first round
        for i in 0..4 {
            let offset = 5 * i;
            e = e.wrapping_add(rotate(a, 5)).wrapping_add(f1(b, c, d)).wrapping_add(words[offset]).wrapping_add(0x5a827999); b = rotate(b, 30);
            d = d.wrapping_add(rotate(e, 5)).wrapping_add(f1(a, b, c)).wrapping_add(words[offset + 1]).wrapping_add(0x5a827999); a = rotate(a, 30);
            c = c.wrapping_add(rotate(d, 5)).wrapping_add(f1(e, a, b)).wrapping_add(words[offset + 2]).wrapping_add(0x5a827999); e = rotate(e, 30);
            b = b.wrapping_add(rotate(c, 5)).wrapping_add(f1(d, e, a)).wrapping_add(words[offset + 3]).wrapping_add(0x5a827999); d = rotate(d, 30);
            a = a.wrapping_add(rotate(b, 5)).wrapping_add(f1(c, d, e)).wrapping_add(words[offset + 4]).wrapping_add(0x5a827999); c = rotate(c, 30);
        }

        // second round
        for i in 4..8 {
            let offset = 5 * i;
            e = e.wrapping_add(rotate(a, 5)).wrapping_add(f2(b, c, d)).wrapping_add(words[offset]).wrapping_add(0x6ed9eba1); b = rotate(b, 30);
            d = d.wrapping_add(rotate(e, 5)).wrapping_add(f2(a, b, c)).wrapping_add(words[offset + 1]).wrapping_add(0x6ed9eba1); a = rotate(a, 30);
            c = c.wrapping_add(rotate(d, 5)).wrapping_add(f2(e, a, b)).wrapping_add(words[offset + 2]).wrapping_add(0x6ed9eba1); e = rotate(e, 30);
            b = b.wrapping_add(rotate(c, 5)).wrapping_add(f2(d, e, a)).wrapping_add(words[offset + 3]).wrapping_add(0x6ed9eba1); d = rotate(d, 30);
            a = a.wrapping_add(rotate(b, 5)).wrapping_add(f2(c, d, e)).wrapping_add(words[offset + 4]).wrapping_add(0x6ed9eba1); c = rotate(c, 30);
        }

        // third round
        for i in 8..12 {
            let offset = 5 * i;
            e = e.wrapping_add(rotate(a, 5)).wrapping_add(f3(b, c, d)).wrapping_add(words[offset]).wrapping_add(0x8f1bbcdc); b = rotate(b, 30);
            d = d.wrapping_add(rotate(e, 5)).wrapping_add(f3(a, b, c)).wrapping_add(words[offset + 1]).wrapping_add(0x8f1bbcdc); a = rotate(a, 30);
            c = c.wrapping_add(rotate(d, 5)).wrapping_add(f3(e, a, b)).wrapping_add(words[offset + 2]).wrapping_add(0x8f1bbcdc); e = rotate(e, 30);
            b = b.wrapping_add(rotate(c, 5)).wrapping_add(f3(d, e, a)).wrapping_add(words[offset + 3]).wrapping_add(0x8f1bbcdc); d = rotate(d, 30);
            a = a.wrapping_add(rotate(b, 5)).wrapping_add(f3(c, d, e)).wrapping_add(words[offset + 4]).wrapping_add(0x8f1bbcdc); c = rotate(c, 30);
        }

        // fourth round
        for i in 12..16 {
            let offset = 5 * i;
            e = e.wrapping_add(rotate(a, 5)).wrapping_add(f2(b, c, d)).wrapping_add(words[offset]).wrapping_add(0xca62c1d6); b = rotate(b, 30);
            d = d.wrapping_add(rotate(e, 5)).wrapping_add(f2(a, b, c)).wrapping_add(words[offset + 1]).wrapping_add(0xca62c1d6); a = rotate(a, 30);
            c = c.wrapping_add(rotate(d, 5)).wrapping_add(f2(e, a, b)).wrapping_add(words[offset + 2]).wrapping_add(0xca62c1d6); e = rotate(e, 30);
            b = b.wrapping_add(rotate(c, 5)).wrapping_add(f2(d, e, a)).wrapping_add(words[offset + 3]).wrapping_add(0xca62c1d6); d = rotate(d, 30);
            a = a.wrapping_add(rotate(b, 5)).wrapping_add(f2(c, d, e)).wrapping_add(words[offset + 4]).wrapping_add(0xca62c1d6); c = rotate(c, 30);
        }

        // update hash
        self.m_hash[0] = self.m_hash[0].wrapping_add(a);
        self.m_hash[1] = self.m_hash[1].wrapping_add(b);
        self.m_hash[2] = self.m_hash[2].wrapping_add(c);
        self.m_hash[3] = self.m_hash[3].wrapping_add(d);
        self.m_hash[4] = self.m_hash[4].wrapping_add(e);
    }

    /// Add an arbitrary number of bytes to the message
    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;

        if self.m_buffer_size > 0 {
            let buffer_space = BLOCK_SIZE - self.m_buffer_size;
            let to_copy = buffer_space.min(current.len());
            self.m_buffer[self.m_buffer_size..self.m_buffer_size + to_copy]
                .copy_from_slice(&current[..to_copy]);
            self.m_buffer_size += to_copy;
            current = &current[to_copy..];
        }

        if self.m_buffer_size == BLOCK_SIZE {
            let buffer = self.m_buffer.clone(); // Clone the buffer for immutable borrowing
            self.process_block(&buffer);
            self.m_num_bytes += BLOCK_SIZE;
            self.m_buffer_size = 0;
        }

        while current.len() >= BLOCK_SIZE {
            self.process_block(&current[..BLOCK_SIZE]);
            self.m_num_bytes += BLOCK_SIZE;
            current = &current[BLOCK_SIZE..];
        }

        if current.len() > 0 {
            self.m_buffer[..current.len()].copy_from_slice(current);
            self.m_buffer_size = current.len();
        }
    }

    /// Process the final block, which is less than 64 bytes
    fn process_buffer(&mut self) {
        let mut padded_length = self.m_buffer_size * 8;
        padded_length += 1;

        let lower11_bits = padded_length & 511;
        if lower11_bits <= 448 {
            padded_length += 448 - lower11_bits;
        } else {
            padded_length += 512 + 448 - lower11_bits;
        }

        padded_length /= 8;

        let mut extra = [0u8; BLOCK_SIZE];

        if self.m_buffer_size < BLOCK_SIZE {
            self.m_buffer[self.m_buffer_size] = 128;
        } else {
            extra[0] = 128;
        }

        if self.m_buffer_size < BLOCK_SIZE {
            for i in self.m_buffer_size + 1..BLOCK_SIZE {
                self.m_buffer[i] = 0;
            }
        }

        for i in BLOCK_SIZE..padded_length {
            extra[i - BLOCK_SIZE] = 0;
        }

        let msg_bits = 8 * (self.m_num_bytes + self.m_buffer_size) as u64;

        let mut add_length = if padded_length < BLOCK_SIZE {
            self.m_buffer.clone()
        } else {
            extra.clone()
        };

        let bit_length_bytes: [u8; 8] = msg_bits.to_be_bytes();
        add_length[BLOCK_SIZE - 8..].copy_from_slice(&bit_length_bytes);

        if padded_length >= BLOCK_SIZE {
            self.process_block(&extra);
        }
        self.process_block(&add_length);
    }

    /// Return the latest hash as 40 hex characters
    pub fn get_hash(&mut self) -> String {
        let mut raw_hash = [0u8; HASH_BYTES];
        self.get_hash_bytes(&mut raw_hash);

        raw_hash.iter().map(|byte| format!("{:02x}", byte)).collect()
    }

    /// Returns the latest hash as bytes
    fn get_hash_bytes(&mut self, buffer: &mut [u8; HASH_BYTES]) {
        let old_hash = self.m_hash;

        self.process_buffer();

        for (i, &word) in self.m_hash.iter().enumerate() {
            let start = i * 4;
            buffer[start..start + 4].copy_from_slice(&word.to_be_bytes());
        }

        self.m_hash = old_hash;
    }

    /// Compute SHA1 of a memory block
    pub fn calculate(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    /// Compute SHA1 of a string, excluding final zero
    pub fn calculate_str(&mut self, text: &str) -> String {
        self.calculate(text.as_bytes())
    }
}

/// Mix functions for process_block()
fn f1(b: u32, c: u32, d: u32) -> u32 {
    d ^ (b & (c ^ d))
}

fn f2(b: u32, c: u32, d: u32) -> u32 {
    b ^ c ^ d
}

fn f3(b: u32, c: u32, d: u32) -> u32 {
    (b & c) | (b & d) | (c & d)
}

fn rotate(a: u32, c: u32) -> u32 {
    (a << c) | (a >> (32 - c))
}

