/// SHA1 operates on 512 bit blocks
const BLOCK_SIZE: usize = 64;
/// Number of 32-bit words in a SHA1 hash
const HASH_VALUES: usize = 5;

pub struct SHA1 {
    m_hash: [u32; HASH_VALUES],
    m_num_bytes: u64,
    m_buffer_size: usize,
    m_buffer: [u8; BLOCK_SIZE],
}

impl SHA1 {
    pub fn new() -> SHA1 {
        let mut sha1 = SHA1 {
            m_hash: [0; HASH_VALUES],
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_buffer: [0; BLOCK_SIZE],
        };
        sha1.reset();
        sha1
    }

    pub fn reset(&mut self) {
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;

        self.m_hash[0] = 0x67452301;
        self.m_hash[1] = 0xefcdab89;
        self.m_hash[2] = 0x98badcfe;
        self.m_hash[3] = 0x10325476;
        self.m_hash[4] = 0xc3d2e1f0;
    }

    fn process_block(&mut self, data: &[u8]) {
        // Convert data into a 16-element array of 32-bit words.
        let input: &[u32; 16] = unsafe { transmute(data.as_ptr()) };
        let mut words = [0u32; 80];

        for i in 0..16 {
            words[i] = swap(input[i]);
        }

        for i in 16..80 {
            words[i] = rotate(words[i - 3] ^ words[i - 8] ^ words[i - 14] ^ words[i - 16], 1);
        }

        // Assign initial hash value as per the current state
        let mut a = self.m_hash[0];
        let mut b = self.m_hash[1];
        let mut c = self.m_hash[2];
        let mut d = self.m_hash[3];
        let mut e = self.m_hash[4];

        // Perform the 4 rounds of SHA-1 processing
        for i in 0..4 {
            let offset = 5 * i;
            e = e.wrapping_add(rotate(a, 5)).wrapping_add(f1(b, c, d)).wrapping_add(words[offset])
                .wrapping_add(0x5a827999);
            b = rotate(b, 30);
            d = d.wrapping_add(rotate(e, 5)).wrapping_add(f1(a, b, c)).wrapping_add(words[offset + 1])
                .wrapping_add(0x5a827999);
            a = rotate(a, 30);
            c = c.wrapping_add(rotate(d, 5)).wrapping_add(f1(e, a, b)).wrapping_add(words[offset + 2])
                .wrapping_add(0x5a827999);
            e = rotate(e, 30);
            b = b.wrapping_add(rotate(c, 5)).wrapping_add(f1(d, e, a)).wrapping_add(words[offset + 3])
                .wrapping_add(0x5a827999);
            d = rotate(d, 30);
            a = a.wrapping_add(rotate(b, 5)).wrapping_add(f1(c, d, e)).wrapping_add(words[offset + 4])
                .wrapping_add(0x5a827999);
            c = rotate(c, 30);
        }

        for i in 4..8 {
            let offset = 5 * i;
            e = e.wrapping_add(rotate(a, 5)).wrapping_add(f2(b, c, d)).wrapping_add(words[offset])
                .wrapping_add(0x6ed9eba1);
            b = rotate(b, 30);
            d = d.wrapping_add(rotate(e, 5)).wrapping_add(f2(a, b, c)).wrapping_add(words[offset + 1])
                .wrapping_add(0x6ed9eba1);
            a = rotate(a, 30);
            c = c.wrapping_add(rotate(d, 5)).wrapping_add(f2(e, a, b)).wrapping_add(words[offset + 2])
                .wrapping_add(0x6ed9eba1);
            e = rotate(e, 30);
            b = b.wrapping_add(rotate(c, 5)).wrapping_add(f2(d, e, a)).wrapping_add(words[offset + 3])
                .wrapping_add(0x6ed9eba1);
            d = rotate(d, 30);
            a = a.wrapping_add(rotate(b, 5)).wrapping_add(f2(c, d, e)).wrapping_add(words[offset + 4])
                .wrapping_add(0x6ed9eba1);
            c = rotate(c, 30);
        }

        for i in 8..12 {
            let offset = 5 * i;
            e = e.wrapping_add(rotate(a, 5)).wrapping_add(f3(b, c, d)).wrapping_add(words[offset])
                .wrapping_add(0x8f1bbcdc);
            b = rotate(b, 30);
            d = d.wrapping_add(rotate(e, 5)).wrapping_add(f3(a, b, c)).wrapping_add(words[offset + 1])
                .wrapping_add(0x8f1bbcdc);
            a = rotate(a, 30);
            c = c.wrapping_add(rotate(d, 5)).wrapping_add(f3(e, a, b)).wrapping_add(words[offset + 2])
                .wrapping_add(0x8f1bbcdc);
            e = rotate(e, 30);
            b = b.wrapping_add(rotate(c, 5)).wrapping_add(f3(d, e, a)).wrapping_add(words[offset + 3])
                .wrapping_add(0x8f1bbcdc);
            d = rotate(d, 30);
            a = a.wrapping_add(rotate(b, 5)).wrapping_add(f3(c, d, e)).wrapping_add(words[offset + 4])
                .wrapping_add(0x8f1bbcdc);
            c = rotate(c, 30);
        }

        for i in 12..16 {
            let offset = 5 * i;
            e = e.wrapping_add(rotate(a, 5)).wrapping_add(f2(b, c, d)).wrapping_add(words[offset])
                .wrapping_add(0xca62c1d6);
            b = rotate(b, 30);
            d = d.wrapping_add(rotate(e, 5)).wrapping_add(f2(a, b, c)).wrapping_add(words[offset + 1])
                .wrapping_add(0xca62c1d6);
            a = rotate(a, 30);
            c = c.wrapping_add(rotate(d, 5)).wrapping_add(f2(e, a, b)).wrapping_add(words[offset + 2])
                .wrapping_add(0xca62c1d6);
            e = rotate(e, 30);
            b = b.wrapping_add(rotate(c, 5)).wrapping_add(f2(d, e, a)).wrapping_add(words[offset + 3])
                .wrapping_add(0xca62c1d6);
            d = rotate(d, 30);
            a = a.wrapping_add(rotate(b, 5)).wrapping_add(f2(c, d, e)).wrapping_add(words[offset + 4])
                .wrapping_add(0xca62c1d6);
            c = rotate(c, 30);
        }

        self.m_hash[0] = self.m_hash[0].wrapping_add(a);
        self.m_hash[1] = self.m_hash[1].wrapping_add(b);
        self.m_hash[2] = self.m_hash[2].wrapping_add(c);
        self.m_hash[3] = self.m_hash[3].wrapping_add(d);
        self.m_hash[4] = self.m_hash[4].wrapping_add(e);
    }

    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;
        if self.m_buffer_size > 0 {
            while !current.is_empty() && self.m_buffer_size < BLOCK_SIZE {
                self.m_buffer[self.m_buffer_size] = current[0];
                self.m_buffer_size += 1;
                current = &current[1..];
            }

            if self.m_buffer_size == BLOCK_SIZE {
                let buffer_copy = self.m_buffer.clone(); // create a local copy
                self.process_block(&buffer_copy);
                self.m_num_bytes += BLOCK_SIZE as u64;
                self.m_buffer_size = 0;
            }
        }

        while current.len() >= BLOCK_SIZE {
            self.process_block(&current[0..BLOCK_SIZE]);
            self.m_num_bytes += BLOCK_SIZE as u64;
            current = &current[BLOCK_SIZE..];
        }

        for &byte in current.iter() {
            self.m_buffer[self.m_buffer_size] = byte;
            self.m_buffer_size += 1;
        }
    }

    fn process_buffer(&mut self) {
        let mut padded_length = self.m_buffer_size * 8;
        padded_length += 1;
        let lower11_bits = padded_length & 511;
        if lower11_bits <= 448 {
            padded_length += 448 - lower11_bits;
        } else {
            padded_length += 512 + 448 - lower11_bits;
        }
        padded_length /= 8;

        let mut extra = [0u8; BLOCK_SIZE];
        if self.m_buffer_size < BLOCK_SIZE {
            self.m_buffer[self.m_buffer_size] = 128;
        } else {
            extra[0] = 128;
        }

        for i in self.m_buffer_size + 1..BLOCK_SIZE {
            self.m_buffer[i] = 0;
        }

        for i in BLOCK_SIZE..padded_length {
            extra[i - BLOCK_SIZE] = 0;
        }

        let msg_bits = 8 * (self.m_num_bytes + self.m_buffer_size as u64);

        let mut add_length_idx = if padded_length < BLOCK_SIZE {
            padded_length
        } else {
            padded_length - BLOCK_SIZE
        };

        for i in 0..8 {
            if padded_length < BLOCK_SIZE {
                self.m_buffer[add_length_idx] = (msg_bits >> (56 - 8 * i)) as u8;
            } else {
                extra[add_length_idx] = (msg_bits >> (56 - 8 * i)) as u8;
            }
            if i != 7 {
                add_length_idx += 1;
            }
        }

        let buffer_copy = self.m_buffer.clone();
        self.process_block(&buffer_copy);
        if padded_length > BLOCK_SIZE {
            self.process_block(&extra);
        }
    }

    pub fn get_hash(&mut self) -> String {
        let mut raw_hash = [0u8; HASH_BYTES];
        self.get_hash_bytes(&mut raw_hash);

        let mut result = String::with_capacity(2 * HASH_BYTES);
        const DEC2HEX: &[u8] = b"0123456789abcdef";

        for &byte in raw_hash.iter() {
            result.push(DEC2HEX[(byte >> 4) as usize] as char);
            result.push(DEC2HEX[(byte & 15) as usize] as char);
        }

        result
    }

    pub fn get_hash_bytes(&mut self, buffer: &mut [u8; HASH_BYTES]) {
        let mut old_hash = [0u32; HASH_VALUES];
        for i in 0..HASH_VALUES {
            old_hash[i] = self.m_hash[i];
        }

        self.process_buffer();

        let mut current = 0;
        for &m in self.m_hash.iter() {
            buffer[current] = (m >> 24) as u8;
            buffer[current + 1] = (m >> 16) as u8;
            buffer[current + 2] = (m >> 8) as u8;
            buffer[current + 3] = m as u8;
            current += 4;
        }

        for i in 0..HASH_VALUES {
            self.m_hash[i] = old_hash[i];
        }
    }

    pub fn calculate_from_bytes(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    pub fn calculate_from_str(&mut self, text: &str) -> String {
        self.reset();
        self.add(text.as_bytes());
        self.get_hash()
    }
}

fn f1(b: u32, c: u32, d: u32) -> u32 {
    d ^ (b & (c ^ d))
}

fn f2(b: u32, c: u32, d: u32) -> u32 {
    b ^ c ^ d
}

fn f3(b: u32, c: u32, d: u32) -> u32 {
    (b & c) | (b & d) | (c & d)
}

fn rotate(value: u32, bits: u32) -> u32 {
    (value << bits) | (value >> (32 - bits))
}

fn swap(x: u32) -> u32 {
    x.swap_bytes()
}

