        let add_length = if padded_length < BLOCK_SIZE {
            &mut self.m_buffer[padded_length..]
        } else {
            &mut extra[(padded_length - BLOCK_SIZE)..]
        };

        add_length[0] = ((msg_bits >> 56) & 0xFF) as u8;
        add_length[1] = ((msg_bits >> 48) & 0xFF) as u8;
        add_length[2] = ((msg_bits >> 40) & 0xFF) as u8;
        add_length[3] = ((msg_bits >> 32) & 0xFF) as u8;
        add_length[4] = ((msg_bits >> 24) & 0xFF) as u8;
        add_length[5] = ((msg_bits >> 16) & 0xFF) as u8;
        add_length[6] = ((msg_bits >> 8) & 0xFF) as u8;
        add_length[7] = (msg_bits & 0xFF) as u8;

        let block_data = unsafe { std::slice::from_raw_parts(self.m_buffer.as_ptr() as *const u32, 16) };
        self.process_block(block_data);
        if padded_length > BLOCK_SIZE {
            let extra_data = unsafe { std::slice::from_raw_parts(extra.as_ptr() as *const u32, 16) };
            self.process_block(extra_data);
        }
    }

    /// return latest hash as 40 hex characters
    pub fn get_hash(&mut self) -> String {
        let mut raw_hash = [0u8; HASH_BYTES];
        self.get_hash_raw(&mut raw_hash);

        let mut result = String::with_capacity(2 * HASH_BYTES);
        for &byte in &raw_hash {
            result.push(format!("{:02x}", byte).chars().nth(0).unwrap());
            result.push(format!("{:02x}", byte).chars().nth(1).unwrap());
        }

        result
    }

    /// return latest hash as bytes
    fn get_hash_raw(&mut self, buffer: &mut [u8; HASH_BYTES]) {
        let old_hash = self.m_hash;

        self.process_buffer();

        for (i, chunk) in buffer.chunks_mut(4).enumerate() {
            let byte_array: [u8; 4] = self.m_hash[i].to_be_bytes();
            chunk.copy_from_slice(&byte_array);
        }

        self.m_hash = old_hash;
    }

    /// compute SHA1 of a memory block
    pub fn compute(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    /// compute SHA1 of a string, excluding final zero
    pub fn compute_from_string(&mut self, text: &str) -> String {
        self.compute(text.as_bytes())
    }
