                self.m_buffer[self.m_bufferSize] = unsafe { *current };
                self.m_bufferSize += 1;
                current = unsafe { current.add(1) };
                num_bytes -= 1;
            }
        }

        if self.m_bufferSize == BLOCK_SIZE {
            let buffer_copy = self.m_buffer.clone();
            self.process_block(&buffer_copy);
            self.m_numBytes += BLOCK_SIZE as u64;
            self.m_bufferSize = 0;
        }

        if num_bytes == 0 {
            return;
        }

        while num_bytes >= BLOCK_SIZE as u64 {
            let chunk = unsafe { std::slice::from_raw_parts(current, BLOCK_SIZE) };
            self.process_block(chunk);
            current = unsafe { current.add(BLOCK_SIZE) };
            self.m_numBytes += BLOCK_SIZE as u64;
            num_bytes -= BLOCK_SIZE as u64;
        }

        while num_bytes > 0 {
            self.m_buffer[self.m_bufferSize] = unsafe { *current };
            self.m_bufferSize += 1;
            current = unsafe { current.add(1) };
            num_bytes -= 1;
        }
    }

    fn process_buffer(&mut self) {
        let mut padded_length = self.m_bufferSize * 8;
        padded_length += 1;
        let lower11_bits = padded_length & 511;
        if lower11_bits <= 448 {
            padded_length += 448 - lower11_bits;
        } else {
            padded_length += 512 + 448 - lower11_bits;
        }
        padded_length /= 8;

        let mut extra = [0u8; BLOCK_SIZE];
        if self.m_bufferSize < BLOCK_SIZE {
            self.m_buffer[self.m_bufferSize] = 128;
        } else {
            extra[0] = 128;
        }

        for i in self.m_bufferSize + 1..BLOCK_SIZE {
            self.m_buffer[i] = 0;
        }
        for i in BLOCK_SIZE..padded_length {
            extra[i - BLOCK_SIZE] = 0;
        }

        let msg_bits = 8 * (self.m_numBytes + self.m_bufferSize as u64);
        let add_length = if padded_length < BLOCK_SIZE {
            &mut self.m_buffer[padded_length..]
        } else {
            &mut extra[padded_length - BLOCK_SIZE..]
        };

        for (i, shift) in (0..8).rev().enumerate() {
            add_length[i] = ((msg_bits >> (shift * 8)) & 0xFF) as u8;
        }

        let buffer_copy = self.m_buffer.clone();
        self.process_block(&buffer_copy);
        if padded_length > BLOCK_SIZE {
            self.process_block(&extra);
        }
    }

    pub fn get_hash(&mut self) -> String {
        let mut raw_hash = [0u8; HASH_BYTES];
        self.get_hash_bytes(&mut raw_hash);

        let mut result = String::with_capacity(2 * HASH_BYTES);
        for byte in &raw_hash {
            result.push_str(&format!("{:02x}", byte));
        }
        result
    }

    fn get_hash_bytes(&mut self, buffer: &mut [u8; HASH_BYTES]) {
        let mut old_hash = [0u32; HASH_VALUES];
        old_hash.copy_from_slice(&self.m_hash);
        self.process_buffer();

        let mut current = buffer.as_mut_ptr();
        for i in 0..HASH_VALUES {
            unsafe {
                *current = ((self.m_hash[i] >> 24) & 0xFF) as u8;
                current = current.add(1);
                *current = ((self.m_hash[i] >> 16) & 0xFF) as u8;
                current = current.add(1);
                *current = ((self.m_hash[i] >> 8) & 0xFF) as u8;
                current = current.add(1);
                *current = (self.m_hash[i] & 0xFF) as u8;
                current = current.add(1);
            }
            self.m_hash[i] = old_hash[i];
        }
    }

    pub fn compute(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    pub fn compute_from_string(&mut self, text: &str) -> String {
        self.reset();
        self.add(text.as_bytes());
        self.get_hash()
    }
}

