use std::convert::TryInto;

const BLOCK_SIZE: usize = 64;
const HASH_BYTES: usize = 20;
const HASH_VALUES: usize = 5;

/// The SHA1 hash algorithm
pub struct SHA1 {
    m_num_bytes: u64,
    m_buffer_size: usize,
    m_hash: [u32; HASH_VALUES],
    m_buffer: [u8; BLOCK_SIZE],
}

impl SHA1 {
    /// Same as reset()
    pub fn new() -> Self {
        let mut sha1 = SHA1 {
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_hash: [0; HASH_VALUES],
            m_buffer: [0; BLOCK_SIZE],
        };
        sha1.reset();
        sha1
    }

    /// Restart
    pub fn reset(&mut self) {
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;

        // According to RFC 1321
        self.m_hash[0] = 0x67452301;
        self.m_hash[1] = 0xefcdab89;
        self.m_hash[2] = 0x98badcfe;
        self.m_hash[3] = 0x10325476;
        self.m_hash[4] = 0xc3d2e1f0;
    }

    /// Process 64 bytes
    fn process_block(&mut self, data: &[u8]) {
        // Ensure data length is 64 bytes
        assert_eq!(data.len(), BLOCK_SIZE);

        // Fetch last hash
        let mut a = self.m_hash[0];
        let mut b = self.m_hash[1];
        let mut c = self.m_hash[2];
        let mut d = self.m_hash[3];
        let mut e = self.m_hash[4];

        // Data represented as 16x 32-bit words
        let mut words = [0u32; 80];
        for i in 0..16 {
            words[i] = u32::from_be_bytes(data[i * 4..i * 4 + 4].try_into().unwrap());
        }

        for i in 16..80 {
            words[i] = rotate(words[i - 3] ^ words[i - 8] ^ words[i - 14] ^ words[i - 16], 1);
        }

        // First round
        for i in 0..4 {
            let offset = 5 * i;
            e = e.wrapping_add(rotate(a, 5)).wrapping_add(f1(b, c, d))
                .wrapping_add(words[offset]).wrapping_add(0x5a827999);
            b = rotate(b, 30);
            d = d.wrapping_add(rotate(e, 5)).wrapping_add(f1(a, b, c))
                .wrapping_add(words[offset + 1]).wrapping_add(0x5a827999);
            a = rotate(a, 30);
            c = c.wrapping_add(rotate(d, 5)).wrapping_add(f1(e, a, b))
                .wrapping_add(words[offset + 2]).wrapping_add(0x5a827999);
            e = rotate(e, 30);
            b = b.wrapping_add(rotate(c, 5)).wrapping_add(f1(d, e, a))
                .wrapping_add(words[offset + 3]).wrapping_add(0x5a827999);
            d = rotate(d, 30);
            a = a.wrapping_add(rotate(b, 5)).wrapping_add(f1(c, d, e))
                .wrapping_add(words[offset + 4]).wrapping_add(0x5a827999);
            c = rotate(c, 30);
        }

        // Second round
        for i in 4..8 {
            let offset = 5 * i;
            e = e.wrapping_add(rotate(a, 5)).wrapping_add(f2(b, c, d))
                .wrapping_add(words[offset]).wrapping_add(0x6ed9eba1);
            b = rotate(b, 30);
            d = d.wrapping_add(rotate(e, 5)).wrapping_add(f2(a, b, c))
                .wrapping_add(words[offset + 1]).wrapping_add(0x6ed9eba1);
            a = rotate(a, 30);
            c = c.wrapping_add(rotate(d, 5)).wrapping_add(f2(e, a, b))
                .wrapping_add(words[offset + 2]).wrapping_add(0x6ed9eba1);
            e = rotate(e, 30);
            b = b.wrapping_add(rotate(c, 5)).wrapping_add(f2(d, e, a))
                .wrapping_add(words[offset + 3]).wrapping_add(0x6ed9eba1);
            d = rotate(d, 30);
            a = a.wrapping_add(rotate(b, 5)).wrapping_add(f2(c, d, e))
                .wrapping_add(words[offset + 4]).wrapping_add(0x6ed9eba1);
            c = rotate(c, 30);
        }

        // Third round
        for i in 8..12 {
            let offset = 5 * i;
            e = e.wrapping_add(rotate(a, 5)).wrapping_add(f3(b, c, d))
                .wrapping_add(words[offset]).wrapping_add(0x8f1bbcdc);
            b = rotate(b, 30);
            d = d.wrapping_add(rotate(e, 5)).wrapping_add(f3(a, b, c))
                .wrapping_add(words[offset + 1]).wrapping_add(0x8f1bbcdc);
            a = rotate(a, 30);
            c = c.wrapping_add(rotate(d, 5)).wrapping_add(f3(e, a, b))
                .wrapping_add(words[offset + 2]).wrapping_add(0x8f1bbcdc);
            e = rotate(e, 30);
            b = b.wrapping_add(rotate(c, 5)).wrapping_add(f3(d, e, a))
                .wrapping_add(words[offset + 3]).wrapping_add(0x8f1bbcdc);
            d = rotate(d, 30);
            a = a.wrapping_add(rotate(b, 5)).wrapping_add(f3(c, d, e))
                .wrapping_add(words[offset + 4]).wrapping_add(0x8f1bbcdc);
            c = rotate(c, 30);
        }

        // Fourth round
        for i in 12..16 {
            let offset = 5 * i;
            e = e.wrapping_add(rotate(a, 5)).wrapping_add(f2(b, c, d))
                .wrapping_add(words[offset]).wrapping_add(0xca62c1d6);
            b = rotate(b, 30);
            d = d.wrapping_add(rotate(e, 5)).wrapping_add(f2(a, b, c))
                .wrapping_add(words[offset + 1]).wrapping_add(0xca62c1d6);
            a = rotate(a, 30);
            c = c.wrapping_add(rotate(d, 5)).wrapping_add(f2(e, a, b))
                .wrapping_add(words[offset + 2]).wrapping_add(0xca62c1d6);
            e = rotate(e, 30);
            b = b.wrapping_add(rotate(c, 5)).wrapping_add(f2(d, e, a))
                .wrapping_add(words[offset + 3]).wrapping_add(0xca62c1d6);
            d = rotate(d, 30);
            a = a.wrapping_add(rotate(b, 5)).wrapping_add(f2(c, d, e))
                .wrapping_add(words[offset + 4]).wrapping_add(0xca62c1d6);
            c = rotate(c, 30);
        }

        // Update hash
        self.m_hash[0] = self.m_hash[0].wrapping_add(a);
        self.m_hash[1] = self.m_hash[1].wrapping_add(b);
        self.m_hash[2] = self.m_hash[2].wrapping_add(c);
        self.m_hash[3] = self.m_hash[3].wrapping_add(d);
        self.m_hash[4] = self.m_hash[4].wrapping_add(e);
    }

    /// Add arbitrary number of bytes
    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;

        if self.m_buffer_size > 0 {
            while !current.is_empty() && self.m_buffer_size < BLOCK_SIZE {
                self.m_buffer[self.m_buffer_size] = current[0];
                self.m_buffer_size += 1;
                current = &current[1..];
            }
        }

        if self.m_buffer_size == BLOCK_SIZE {
            let buffer_copy = self.m_buffer;
            self.process_block(&buffer_copy);
            self.m_num_bytes += BLOCK_SIZE as u64;
            self.m_buffer_size = 0;
        }

        if current.is_empty() {
            return;
        }

        while current.len() >= BLOCK_SIZE {
            self.process_block(&current[..BLOCK_SIZE]);
            current = &current[BLOCK_SIZE..];
            self.m_num_bytes += BLOCK_SIZE as u64;
        }

        for &byte in current {
            self.m_buffer[self.m_buffer_size] = byte;
            self.m_buffer_size += 1;
        }
    }

    /// Process final block, less than 64 bytes
    fn process_buffer(&mut self) {
        let mut padded_length = self.m_buffer_size * 8;
        padded_length += 1;

        let lower11_bits = padded_length & 511;
        if lower11_bits <= 448 {
            padded_length += 448 - lower11_bits;
        } else {
            padded_length += 512 + 448 - lower11_bits;
        }
        padded_length /= 8;

        let mut extra = [0u8; BLOCK_SIZE];

        if self.m_buffer_size < BLOCK_SIZE {
            self.m_buffer[self.m_buffer_size] = 128;
        } else {
            extra[0] = 128;
        }

        for i in self.m_buffer_size + 1..BLOCK_SIZE {
            self.m_buffer[i] = 0;
        }
        for i in BLOCK_SIZE..padded_length {
            extra[i - BLOCK_SIZE] = 0;
        }

        let msg_bits = 8 * (self.m_num_bytes + self.m_buffer_size as u64);
        let add_length = if padded_length < BLOCK_SIZE {
            &mut self.m_buffer[padded_length..]
        } else {
            &mut extra[padded_length - BLOCK_SIZE..]
        };

        add_length[0] = ((msg_bits >> 56) & 0xFF) as u8;
        add_length[1] = ((msg_bits >> 48) & 0xFF) as u8;
        add_length[2] = ((msg_bits >> 40) & 0xFF) as u8;
        add_length[3] = ((msg_bits >> 32) & 0xFF) as u8;
        add_length[4] = ((msg_bits >> 24) & 0xFF) as u8;
        add_length[5] = ((msg_bits >> 16) & 0xFF) as u8;
        add_length[6] = ((msg_bits >> 8) & 0xFF) as u8;
        add_length[7] = (msg_bits & 0xFF) as u8;

        let buffer_copy = self.m_buffer;
        self.process_block(&buffer_copy);
        if padded_length > BLOCK_SIZE {
            self.process_block(&extra);
        }
    }

    /// Return latest hash as 40 hex characters
    pub fn get_hash(&mut self) -> String {
        let mut raw_hash = [0u8; HASH_BYTES];
        self.get_hash_bytes(&mut raw_hash);

        let mut result = String::with_capacity(2 * HASH_BYTES);
        for byte in &raw_hash {
            result.push_str(&format!("{:02x}", byte));
        }

        result
    }

    /// Return latest hash as bytes
    fn get_hash_bytes(&mut self, buffer: &mut [u8; HASH_BYTES]) {
        let old_hash = self.m_hash.clone();

        self.process_buffer();

        for (i, chunk) in buffer.chunks_mut(4).enumerate() {
            let h = self.m_hash[i];
            chunk[0] = (h >> 24) as u8;
            chunk[1] = (h >> 16) as u8;
            chunk[2] = (h >> 8) as u8;
            chunk[3] = h as u8;
        }

        self.m_hash = old_hash;
    }

    /// Compute SHA1 of a memory block
    pub fn compute_from(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    /// Compute SHA1 of a Rust string, excluding final zero
    pub fn compute_from_str(&mut self, text: &str) -> String {
        self.reset();
        self.add(text.as_bytes());
        self.get_hash()
    }
}

fn f1(b: u32, c: u32, d: u32) -> u32 {
    d ^ (b & (c ^ d))
}

fn f2(b: u32, c: u32, d: u32) -> u32 {
    b ^ c ^ d
}

fn f3(b: u32, c: u32, d: u32) -> u32 {
    (b & c) | (b & d) | (c & d)
}

fn rotate(a: u32, c: u32) -> u32 {
    (a << c) | (a >> (32 - c))
}

fn main() {
    let mut sha1 = SHA1::new();
    sha1.compute_from(b"example");
    println!("SHA1 hash: {}", sha1.get_hash());
}

