const BLOCK_SIZE: usize = 64;
const HASH_BYTES: usize = 32;
const HASH_VALUES: usize = 8;

#[derive(Clone)]
pub struct SHA256 {
    m_num_bytes: u64,
    m_buffer_size: usize,
    m_buffer: [u8; BLOCK_SIZE],
    m_hash: [u32; HASH_VALUES],
}

impl SHA256 {
    pub fn new() -> Self {
        let mut sha256 = SHA256 {
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_buffer: [0; BLOCK_SIZE],
            m_hash: [0; HASH_VALUES],
        };
        sha256.reset();
        sha256
    }

    pub fn reset(&mut self) {
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;

        // according to the standard
        self.m_hash[0] = 0x6a09e667;
        self.m_hash[1] = 0xbb67ae85;
        self.m_hash[2] = 0x3c6ef372;
        self.m_hash[3] = 0xa54ff53a;
        self.m_hash[4] = 0x510e527f;
        self.m_hash[5] = 0x9b05688c;
        self.m_hash[6] = 0x1f83d9ab;
        self.m_hash[7] = 0x5be0cd19;
    }

    fn rotate(a: u32, c: u32) -> u32 {
        (a >> c) | (a << (32 - c))
    }

    fn swap(x: u32) -> u32 {
        x.swap_bytes()
    }

    fn f1(e: u32, f: u32, g: u32) -> u32 {
        let term1 = Self::rotate(e, 6) ^ Self::rotate(e, 11) ^ Self::rotate(e, 25);
        let term2 = (e & f) ^ (!e & g);
        term1.wrapping_add(term2)
    }

    fn f2(a: u32, b: u32, c: u32) -> u32 {
        let term1 = Self::rotate(a, 2) ^ Self::rotate(a, 13) ^ Self::rotate(a, 22);
        let term2 = ((a | b) & c) | (a & b);
        term1.wrapping_add(term2)
    }

    pub fn process_block(&mut self, data: &[u8]) {
        let mut a = self.m_hash[0];
        let mut b = self.m_hash[1];
        let mut c = self.m_hash[2];
        let mut d = self.m_hash[3];
        let mut e = self.m_hash[4];
        let mut f = self.m_hash[5];
        let mut g = self.m_hash[6];
        let mut h = self.m_hash[7];

        let mut words = [0u32; 64];
        for i in 0..16 {
            words[i] = Self::swap(u32::from_be_bytes([data[4 * i], data[4 * i + 1], data[4 * i + 2], data[4 * i + 3]]));
        }

        for i in 16..64 {
            let s0 = Self::rotate(words[i - 15], 7) ^ Self::rotate(words[i - 15], 18) ^ (words[i - 15] >> 3);
            let s1 = Self::rotate(words[i - 2], 17) ^ Self::rotate(words[i - 2], 19) ^ (words[i - 2] >> 10);
            words[i] = words[i - 16].wrapping_add(s0).wrapping_add(words[i - 7]).wrapping_add(s1);
        }

        for (j, &i) in [
            0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
            0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
            0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
            0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
            0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
            0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
            0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
            0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
        ].iter().enumerate() {
            let t1 = h.wrapping_add(Self::f1(e, f, g))
                .wrapping_add(i)
                .wrapping_add(words[j]);
            let t2 = Self::f2(a, b, c);
            h = g;
            g = f;
            f = e;
            e = d.wrapping_add(t1);
            d = c;
            c = b;
            b = a;
            a = t1.wrapping_add(t2);
        }

        self.m_hash[0] = self.m_hash[0].wrapping_add(a);
        self.m_hash[1] = self.m_hash[1].wrapping_add(b);
        self.m_hash[2] = self.m_hash[2].wrapping_add(c);
        self.m_hash[3] = self.m_hash[3].wrapping_add(d);
        self.m_hash[4] = self.m_hash[4].wrapping_add(e);
        self.m_hash[5] = self.m_hash[5].wrapping_add(f);
        self.m_hash[6] = self.m_hash[6].wrapping_add(g);
        self.m_hash[7] = self.m_hash[7].wrapping_add(h);
