    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;

        if self.m_buffer_size > 0 {
            while !current.is_empty() && self.m_buffer_size < BLOCK_SIZE {
                self.m_buffer[self.m_buffer_size] = current[0];
                self.m_buffer_size += 1;
                current = &current[1..];
            }
        }

        if self.m_buffer_size == BLOCK_SIZE {
            let buffer_copy = self.m_buffer;
            self.process_block(&buffer_copy);
            self.m_num_bytes += BLOCK_SIZE as u64;
            self.m_buffer_size = 0;
        }

        while current.len() >= BLOCK_SIZE {
            let block = &current[0..BLOCK_SIZE];
            self.process_block(block);
            self.m_num_bytes += BLOCK_SIZE as u64;
            current = &current[BLOCK_SIZE..];
        }

        while !current.is_empty() {
            self.m_buffer[self.m_buffer_size] = current[0];
            self.m_buffer_size += 1;
            current = &current[1..];
        }
    }

    fn process_buffer(&mut self) {
        let mut padded_length = self.m_buffer_size * 8;
        padded_length += 1;

        let lower11_bits = padded_length & 511;
        if lower11_bits <= 448 {
            padded_length += 448 - lower11_bits;
        } else {
            padded_length += 512 + 448 - lower11_bits;
        }
        padded_length /= 8;

        let mut extra = [0u8; BLOCK_SIZE];
        if self.m_buffer_size < BLOCK_SIZE {
            self.m_buffer[self.m_buffer_size] = 128;
        } else {
            extra[0] = 128;
        }

        let mut i = self.m_buffer_size + 1;
        while i < BLOCK_SIZE {
            self.m_buffer[i] = 0;
            i += 1;
        }
        while i < padded_length {
            extra[i - BLOCK_SIZE] = 0;
            i += 1;
        }

        let msg_bits = 8 * (self.m_num_bytes + self.m_buffer_size as u64);
        let add_length = if padded_length < BLOCK_SIZE {
            &mut self.m_buffer[padded_length..]
        } else {
            &mut extra[(padded_length - BLOCK_SIZE)..]
        };

        add_length[0] = (msg_bits >> 56) as u8;
        add_length[1] = (msg_bits >> 48) as u8;
        add_length[2] = (msg_bits >> 40) as u8;
        add_length[3] = (msg_bits >> 32) as u8;
        add_length[4] = (msg_bits >> 24) as u8;
        add_length[5] = (msg_bits >> 16) as u8;
        add_length[6] = (msg_bits >> 8) as u8;
        add_length[7] = msg_bits as u8;

        {
            let buffer_copy = self.m_buffer;
            self.process_block(&buffer_copy);
        }

        if padded_length > BLOCK_SIZE {
            self.process_block(&extra);
        }
    }

    pub fn get_hash(&mut self) -> String {
        let mut raw_hash = [0u8; HASH_BYTES];
        self.get_hash_bytes(&mut raw_hash);

        let mut result = String::with_capacity(2 * HASH_BYTES);
        for byte in &raw_hash {
            result.push_str(&format!("{:02x}", byte));
        }
        result
    }

    pub fn get_hash_bytes(&mut self, buffer: &mut [u8; HASH_BYTES]) {
        let old_hash = self.m_hash.clone();
        self.process_buffer();

        for (i, &hash_value) in self.m_hash.iter().enumerate() {
            buffer[i * 4] = ((hash_value >> 24) & 0xFF) as u8;
            buffer[i * 4 + 1] = ((hash_value >> 16) & 0xFF) as u8;
            buffer[i * 4 + 2] = ((hash_value >> 8) & 0xFF) as u8;
            buffer[i * 4 + 3] = (hash_value & 0xFF) as u8;
        }

        self.m_hash = old_hash;
    }

    pub fn digest(data: &[u8]) -> String {
        let mut sha256 = SHA256::new();
        sha256.add(data);
        sha256.get_hash()
