    println!("SHA256 hash: {}", hash);
}

pub struct SHA256 {
    m_num_bytes: u64,
    m_buffer_size: usize,
    m_hash: [u32; 8],
    m_buffer: [u8; SHA256::BLOCK_SIZE],
}

impl SHA256 {
    const BLOCK_SIZE: usize = 64;
    const HASH_BYTES: usize = 32;
    const HASH_VALUES: usize = 8;

    pub fn new() -> SHA256 {
        let mut sha = SHA256 {
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_hash: [0; 8],
            m_buffer: [0; SHA256::BLOCK_SIZE],
        };
        sha.reset();
        sha
    }

    pub fn reset(&mut self) {
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;

        self.m_hash[0] = 0x6a09e667;
        self.m_hash[1] = 0xbb67ae85;
        self.m_hash[2] = 0x3c6ef372;
        self.m_hash[3] = 0xa54ff53a;
        self.m_hash[4] = 0x510e527f;
        self.m_hash[5] = 0x9b05688c;
        self.m_hash[6] = 0x1f83d9ab;
        self.m_hash[7] = 0x5be0cd19;
    }

    pub fn process_block(&mut self, data: &[u8]) {
        let mut words = [0u32; 64];
        let mut a = self.m_hash[0];
        let mut b = self.m_hash[1];
        let mut c = self.m_hash[2];
        let mut d = self.m_hash[3];
        let mut e = self.m_hash[4];
        let mut f = self.m_hash[5];
        let mut g = self.m_hash[6];
        let mut h = self.m_hash[7];

        // Convert big endian data to words
        for i in 0..16 {
            words[i] = u32::from_be_bytes(data[i * 4..i * 4 + 4].try_into().unwrap());
        }

        let mut x;
        let mut y;

        // First round
        x = h.wrapping_add(f1(e, f, g)).wrapping_add(0x428a2f98).wrapping_add(words[0]);
        y = f2(a, b, c);
        d = d.wrapping_add(x);
        h = x.wrapping_add(y);
        x = g.wrapping_add(f1(d, e, f)).wrapping_add(0x71374491).wrapping_add(words[1]);
        y = f2(h, a, b);
        c = c.wrapping_add(x);
        g = x.wrapping_add(y);
        x = f.wrapping_add(f1(c, d, e)).wrapping_add(0xb5c0fbcf).wrapping_add(words[2]);
        y = f2(g, h, a);
        b = b.wrapping_add(x);
        f = x.wrapping_add(y);
        x = e.wrapping_add(f1(b, c, d)).wrapping_add(0xe9b5dba5).wrapping_add(words[3]);
        y = f2(f, g, h);
        a = a.wrapping_add(x);
        e = x.wrapping_add(y);
        x = d.wrapping_add(f1(a, b, c)).wrapping_add(0x3956c25b).wrapping_add(words[4]);
        y = f2(e, f, g);
        h = h.wrapping_add(x);
        d = x.wrapping_add(y);
        x = c.wrapping_add(f1(h, a, b)).wrapping_add(0x59f111f1).wrapping_add(words[5]);
        y = f2(d, e, f);
        g = g.wrapping_add(x);
        c = x.wrapping_add(y);
        x = b.wrapping_add(f1(g, h, a)).wrapping_add(0x923f82a4).wrapping_add(words[6]);
        y = f2(c, d, e);
        f = f.wrapping_add(x);
        b = x.wrapping_add(y);
        x = a.wrapping_add(f1(f, g, h)).wrapping_add(0xab1c5ed5).wrapping_add(words[7]);
        y = f2(b, c, d);
        e = e.wrapping_add(x);
        a = x.wrapping_add(y);

        // Other rounds and word extensions...
        // Full function implementation would continue...

        self.m_hash[0] = self.m_hash[0].wrapping_add(a);
        self.m_hash[1] = self.m_hash[1].wrapping_add(b);
        self.m_hash[2] = self.m_hash[2].wrapping_add(c);
        self.m_hash[3] = self.m_hash[3].wrapping_add(d);
        self.m_hash[4] = self.m_hash[4].wrapping_add(e);
        self.m_hash[5] = self.m_hash[5].wrapping_add(f);
        self.m_hash[6] = self.m_hash[6].wrapping_add(g);
        self.m_hash[7] = self.m_hash[7].wrapping_add(h);
    }

    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;
        if self.m_buffer_size > 0 {
            while current.len() > 0 && self.m_buffer_size < SHA256::BLOCK_SIZE {
                self.m_buffer[self.m_buffer_size] = current[0];
                self.m_buffer_size += 1;
                current = &current[1..];
            }
        }
        if self.m_buffer_size == SHA256::BLOCK_SIZE {
            self.process_block(&self.m_buffer.clone());
            self.m_num_bytes += SHA256::BLOCK_SIZE as u64;
            self.m_buffer_size = 0;
        }
        while current.len() >= SHA256::BLOCK_SIZE {
            self.process_block(&current[..SHA256::BLOCK_SIZE]);
            current = &current[SHA256::BLOCK_SIZE..];
            self.m_num_bytes += SHA256::BLOCK_SIZE as u64;
        }
        while current.len() > 0 {
            self.m_buffer[self.m_buffer_size] = current[0];
            self.m_buffer_size += 1;
            current = &current[1..];
        }
    }

    pub fn process_buffer(&mut self) {
        let mut padded_length = self.m_buffer_size * 8 + 1;
        let lower_511_bits = padded_length % 512;
        if lower_511_bits <= 448 {
            padded_length += 448 - lower_511_bits;
        } else {
            padded_length += 512 + 448 - lower_511_bits;
        }
        padded_length /= 8;

        let mut extra = [0u8; SHA256::BLOCK_SIZE];

        if self.m_buffer_size < SHA256::BLOCK_SIZE {
            self.m_buffer[self.m_buffer_size] = 128;
        } else {
            extra[0] = 128;
        }

        if padded_length > SHA256::BLOCK_SIZE {
            for i in self.m_buffer_size + 1..SHA256::BLOCK_SIZE {
                self.m_buffer[i] = 0;
            }
            for i in SHA256::BLOCK_SIZE..padded_length {
                extra[i - SHA256::BLOCK_SIZE] = 0;
            }
        }

        let msg_bits = 8 * (self.m_num_bytes + self.m_buffer_size as u64);
        if padded_length < SHA256::BLOCK_SIZE {
            let add_length = &mut self.m_buffer[padded_length..];
            add_length.copy_from_slice(&msg_bits.to_be_bytes());
        } else {
            let add_length = &mut extra[padded_length - SHA256::BLOCK_SIZE..];
            add_length.copy_from_slice(&msg_bits.to_be_bytes());
        }

        self.process_block(&self.m_buffer.clone());

        if padded_length > SHA256::BLOCK_SIZE {
            self.process_block(&extra);
        }
    }

    pub fn get_hash(&mut self) -> String {
        let mut raw_hash = [0u8; SHA256::HASH_BYTES];
        self.get_raw_hash(&mut raw_hash);
        raw_hash.iter().map(|b| format!("{:02x}", b)).collect()
    }

    fn get_raw_hash(&mut self, buffer: &mut [u8]) {
        let old_hash = self.m_hash;
        self.process_buffer();

        let mut current = &mut buffer[..];
        for &hash in &self.m_hash {
            current[..4].copy_from_slice(&hash.to_be_bytes());
            current = &mut current[4..];
        }
        self.m_hash = old_hash;
    }

    pub fn digest(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }
}

fn rotate(a: u32, c: u32) -> u32 {
    (a >> c) | (a << (32 - c))
}

fn swap(x: u32) -> u32 {
    x.swap_bytes()
}

fn f1(e: u32, f: u32, g: u32) -> u32 {
    let term1 = rotate(e, 6) ^ rotate(e, 11) ^ rotate(e, 25);
    let term2 = (e & f) ^ (!e & g);
    term1.wrapping_add(term2)
}

fn f2(a: u32, b: u32, c: u32) -> u32 {
    let term1 = rotate(a, 2) ^ rotate(a, 13) ^ rotate(a, 22);
    let term2 = ((a | b) & c) | (a & b);
    term1.wrapping_add(term2)
}

fn main() {
    let mut sha256 = SHA256::new();
    let hash = sha256.digest(b"hello world");
    println!("Hash: {}", hash);
}

