const SHA256_BUFFER_SIZE: usize = 64;
const SHA256_HASH_BYTES: usize = 32;
const SHA256_HASH_VALUES: usize = SHA256_HASH_BYTES / 4;
const SHA256_BLOCK_SIZE: usize = 64;

/// SHA256 processor
pub struct SHA256 {
    m_num_bytes: u64,
    m_buffer_size: usize,
    m_buffer: [u8; SHA256_BUFFER_SIZE],
    m_hash: [u32; SHA256_HASH_VALUES],
}

impl SHA256 {
    /// Same as reset()
    pub fn new() -> SHA256 {
        let mut instance = SHA256 {
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_buffer: [0; SHA256_BUFFER_SIZE],
            m_hash: [0; SHA256_HASH_VALUES],
        };
        instance.reset();
        instance
    }

    /// Restart
    pub fn reset(&mut self) {
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;

        // according to RFC 1321
        self.m_hash[0] = 0x6a09e667;
        self.m_hash[1] = 0xbb67ae85;
        self.m_hash[2] = 0x3c6ef372;
        self.m_hash[3] = 0xa54ff53a;
        self.m_hash[4] = 0x510e527f;
        self.m_hash[5] = 0x9b05688c;
        self.m_hash[6] = 0x1f83d9ab;
        self.m_hash[7] = 0x5be0cd19;
    }

    /// Process 64 bytes
    pub fn process_block(&mut self, data: &[u8]) {
        assert_eq!(data.len(), SHA256_BLOCK_SIZE);

        let mut a = self.m_hash[0];
        let mut b = self.m_hash[1];
        let mut c = self.m_hash[2];
        let mut d = self.m_hash[3];
        let mut e = self.m_hash[4];
        let mut f = self.m_hash[5];
        let mut g = self.m_hash[6];
        let mut h = self.m_hash[7];

        let mut words = [0u32; 64];
        for i in 0..16 {
            words[i] = u32::from_be_bytes([
                data[4 * i],
                data[4 * i + 1],
                data[4 * i + 2],
                data[4 * i + 3],
            ]);
        }

        for i in 16..64 {
            words[i] = words[i - 16]
                .wrapping_add(SHA256::sigma0(words[i - 15]))
                .wrapping_add(words[i - 7])
                .wrapping_add(SHA256::sigma1(words[i - 2]));
        }

        for i in 0..64 {
            let t1 = h
                .wrapping_add(SHA256::big_sigma1(e))
                .wrapping_add(SHA256::ch(e, f, g))
                .wrapping_add(SHA256::K[i])
                .wrapping_add(words[i]);
            let t2 = SHA256::big_sigma0(a).wrapping_add(SHA256::maj(a, b, c));
            h = g;
            g = f;
            f = e;
            e = d.wrapping_add(t1);
            d = c;
            c = b;
            b = a;
            a = t1.wrapping_add(t2);
        }

        self.m_hash[0] = self.m_hash[0].wrapping_add(a);
        self.m_hash[1] = self.m_hash[1].wrapping_add(b);
        self.m_hash[2] = self.m_hash[2].wrapping_add(c);
        self.m_hash[3] = self.m_hash[3].wrapping_add(d);
        self.m_hash[4] = self.m_hash[4].wrapping_add(e);
        self.m_hash[5] = self.m_hash[5].wrapping_add(f);
        self.m_hash[6] = self.m_hash[6].wrapping_add(g);
        self.m_hash[7] = self.m_hash[7].wrapping_add(h);
    }

    fn big_sigma0(x: u32) -> u32 {
        x.rotate_right(2) ^ x.rotate_right(13) ^ x.rotate_right(22)
    }

    fn big_sigma1(x: u32) -> u32 {
        x.rotate_right(6) ^ x.rotate_right(11) ^ x.rotate_right(25)
    }

    fn sigma0(x: u32) -> u32 {
        x.rotate_right(7) ^ x.rotate_right(18) ^ (x >> 3)
    }

    fn sigma1(x: u32) -> u32 {
        x.rotate_right(17) ^ x.rotate_right(19) ^ (x >> 10)
    }

    fn ch(x: u32, y: u32, z: u32) -> u32 {
        (x & y) ^ (!x & z)
    }

    fn maj(x: u32, y: u32, z: u32) -> u32 {
        (x & y) ^ (x & z) ^ (y & z)
    }

    const K: [u32; 64] = [
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4,
        0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe,
        0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f,
        0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
        0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc,
        0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
        0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116,
        0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7,
        0xc67178f2,
    ];

    /// Add arbitrary number of bytes
    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;
        if self.m_buffer_size > 0 {
            while !current.is_empty() && self.m_buffer_size < SHA256_BLOCK_SIZE {
                self.m_buffer[self.m_buffer_size] = current[0];
                current = &current[1..];
                self.m_buffer_size += 1;
            }
        }

        if self.m_buffer_size == SHA256_BLOCK_SIZE {
            let buffer_copy = self.m_buffer.clone();
            self.process_block(&buffer_copy);
            self.m_num_bytes += SHA256_BLOCK_SIZE as u64;
            self.m_buffer_size = 0;
        }

        while current.len() >= SHA256_BLOCK_SIZE {
            self.process_block(&current[..SHA256_BLOCK_SIZE]);
            self.m_num_bytes += SHA256_BLOCK_SIZE as u64;
            current = &current[SHA256_BLOCK_SIZE..];
        }

        for &byte in current {
            self.m_buffer[self.m_buffer_size] = byte;
            self.m_buffer_size += 1;
        }
    }

    /// Process final block, less than 64 bytes
    pub fn process_buffer(&mut self) {
        let mut padded_length = self.m_buffer_size * 8;
        padded_length += 1;

        let mut extra = [0u8; SHA256_BLOCK_SIZE];

        let lower_11_bits = padded_length & 511;
        if lower_11_bits <= 448 {
            padded_length += 448 - lower_11_bits;
        } else {
            padded_length += 512 + 448 - lower_11_bits;
        }

        padded_length /= 8;

        if self.m_buffer_size < SHA256_BLOCK_SIZE {
            self.m_buffer[self.m_buffer_size] = 0x80;
        } else {
            extra[0] = 0x80;
        }

        for i in (self.m_buffer_size + 1)..SHA256_BLOCK_SIZE {
            self.m_buffer[i] = 0;
        }

        for i in SHA256_BLOCK_SIZE..padded_length {
            extra[i - SHA256_BLOCK_SIZE] = 0;
        }

        let msg_bits = 8 * (self.m_num_bytes + self.m_buffer_size as u64);

        let add_length = if padded_length < SHA256_BLOCK_SIZE {
            &mut self.m_buffer[padded_length..]
        } else {
            &mut extra[(padded_length - SHA256_BLOCK_SIZE)..]
        };

        add_length[..8].copy_from_slice(&msg_bits.to_be_bytes());

        {
            let buffer_copy = self.m_buffer.clone();
            self.process_block(&buffer_copy);
        }
        if padded_length > SHA256_BLOCK_SIZE {
            self.process_block(&extra);
        }
    }

    /// Return latest hash as 64 hex characters
    pub fn get_hash(&mut self) -> String {
        let mut raw_hash = [0u8; SHA256_HASH_BYTES];
        self.get_hash_bytes(&mut raw_hash);
        raw_hash.iter().map(|b| format!("{:02x}", b)).collect()
    }

    /// Return latest hash as bytes
    pub fn get_hash_bytes(&mut self, buffer: &mut [u8; SHA256_HASH_BYTES]) {
        let old_hash = self.m_hash.clone();
        self.process_buffer();

        for (i, chunk) in buffer.chunks_mut(4).enumerate() {
            chunk.copy_from_slice(&self.m_hash[i].to_be_bytes());
        }

        self.m_hash = old_hash;
    }

    /// Compute SHA256 of a memory block
    pub fn hash_from_data(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    /// Compute SHA256 of a string, excluding final zero
    pub fn hash_from_string(&mut self, text: &str) -> String {
        self.reset();
        self.add(text.as_bytes());
        self.get_hash()
    }
}

fn main() {
    let mut sha256 = SHA256::new();
    sha256.add(b"Hello, world!");
    println!("Hash: {}", sha256.get_hash());
}

const BLOCK_SIZE: usize = 64;
const HASH_VALUES: usize = 8;
const HASH_BYTES: usize = 32;

pub struct SHA256 {
    m_num_bytes: u64,
    m_buffer: [u8; BLOCK_SIZE],
    m_buffer_size: usize,
    m_hash: [u32; HASH_VALUES],
}

impl SHA256 {
    pub fn new() -> SHA256 {
        let mut sha256 = SHA256 {
            m_num_bytes: 0,
            m_buffer: [0; BLOCK_SIZE],
            m_buffer_size: 0,
            m_hash: [0; HASH_VALUES],
        };
        sha256.reset();
        sha256
    }

    /// Restart
    pub fn reset(&mut self) {
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;

        self.m_hash[0] = 0x6a09e667;
        self.m_hash[1] = 0xbb67ae85;
        self.m_hash[2] = 0x3c6ef372;
        self.m_hash[3] = 0xa54ff53a;
        self.m_hash[4] = 0x510e527f;
        self.m_hash[5] = 0x9b05688c;
        self.m_hash[6] = 0x1f83d9ab;
        self.m_hash[7] = 0x5be0cd19;

        #[cfg(feature = "sha2_224_seed_vector")]
        {
            self.m_hash[0] = 0xc1059ed8;
            self.m_hash[1] = 0x367cd507;
            self.m_hash[2] = 0x3070dd17;
            self.m_hash[3] = 0xf70e5939;
            self.m_hash[4] = 0xffc00b31;
            self.m_hash[5] = 0x68581511;
            self.m_hash[6] = 0x64f98fa7;
            self.m_hash[7] = 0xbefa4fa4;
        }
    }

    /// Process 64 bytes
    fn process_block(&mut self, data: &[u8]) {
        let mut a = self.m_hash[0];
        let mut b = self.m_hash[1];
        let mut c = self.m_hash[2];
        let mut d = self.m_hash[3];
        let mut e = self.m_hash[4];
        let mut f = self.m_hash[5];
        let mut g = self.m_hash[6];
        let mut h = self.m_hash[7];

        let input: &[u32] = unsafe { std::slice::from_raw_parts(data.as_ptr() as *const u32, 16) };
        let mut words = [0u32; 64];
        let mut i = 0;

        for x in input.iter().take(16) {
            if cfg!(target_endian = "big") {
                words[i] = *x;
            } else {
                words[i] = x.to_be();
            }
            i += 1;
        }

        // Extend words
        for j in 16..64 {
            words[j] = words[j - 16]
                .wrapping_add(sigma0(words[j - 15]))
                .wrapping_add(words[j - 7])
                .wrapping_add(sigma1(words[j - 2]));
        }

        // First round
        macro_rules! round {
            ($a:expr, $b:expr, $c:expr, $d:expr, $e:expr, $f:expr, $g:expr, $h:expr, $k:expr, $w:expr) => {{
                let t1 = $h
                    .wrapping_add(f1($e, $f, $g))
                    .wrapping_add($k)
                    .wrapping_add($w);
                let t2 = f2($a, $b, $c);
                $d = $d.wrapping_add(t1);
                $h = t1.wrapping_add(t2);
            }};
        }

        round!(a, b, c, d, e, f, g, h, 0x428a2f98, words[0]);
        round!(h, a, b, c, d, e, f, g, 0x71374491, words[1]);
        round!(g, h, a, b, c, d, e, f, 0xb5c0fbcf, words[2]);
        round!(f, g, h, a, b, c, d, e, 0xe9b5dba5, words[3]);

        round!(e, f, g, h, a, b, c, d, 0x3956c25b, words[4]);
        round!(d, e, f, g, h, a, b, c, 0x59f111f1, words[5]);
        round!(c, d, e, f, g, h, a, b, 0x923f82a4, words[6]);
        round!(b, c, d, e, f, g, h, a, 0xab1c5ed5, words[7]);

        // Remaining rounds
        for j in (8..64).step_by(8) {
            round!(a, b, c, d, e, f, g, h, K[j], words[j]);
            round!(h, a, b, c, d, e, f, g, K[j + 1], words[j + 1]);
            round!(g, h, a, b, c, d, e, f, K[j + 2], words[j + 2]);
            round!(f, g, h, a, b, c, d, e, K[j + 3], words[j + 3]);
            round!(e, f, g, h, a, b, c, d, K[j + 4], words[j + 4]);
            round!(d, e, f, g, h, a, b, c, K[j + 5], words[j + 5]);
            round!(c, d, e, f, g, h, a, b, K[j + 6], words[j + 6]);
            round!(b, c, d, e, f, g, h, a, K[j + 7], words[j + 7]);
        }

        // Update hash
        self.m_hash[0] = self.m_hash[0].wrapping_add(a);
        self.m_hash[1] = self.m_hash[1].wrapping_add(b);
        self.m_hash[2] = self.m_hash[2].wrapping_add(c);
        self.m_hash[3] = self.m_hash[3].wrapping_add(d);
        self.m_hash[4] = self.m_hash[4].wrapping_add(e);
        self.m_hash[5] = self.m_hash[5].wrapping_add(f);
        self.m_hash[6] = self.m_hash[6].wrapping_add(g);
        self.m_hash[7] = self.m_hash[7].wrapping_add(h);
    }

    /// Add arbitrary number of bytes
    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;

        if self.m_buffer_size > 0 {
            while !current.is_empty() && self.m_buffer_size < BLOCK_SIZE {
                self.m_buffer[self.m_buffer_size] = current[0];
                current = &current[1..];
                self.m_buffer_size += 1;
            }
        }

        if self.m_buffer_size == BLOCK_SIZE {
            // Clone buffer for use as immutable reference
            let buffer = self.m_buffer.clone();
            self.process_block(&buffer);
            self.m_num_bytes += BLOCK_SIZE as u64;
            self.m_buffer_size = 0;
        }

        while current.len() >= BLOCK_SIZE {
            self.process_block(&current[..BLOCK_SIZE]);
            current = &current[BLOCK_SIZE..];
            self.m_num_bytes += BLOCK_SIZE as u64;
        }

        current.iter().for_each(|&b| {
            self.m_buffer[self.m_buffer_size] = b;
            self.m_buffer_size += 1;
        });
    }

    /// Process final block, less than 64 bytes
    fn process_buffer(&mut self) {
        let padded_length = (self.m_buffer_size * 8 + 1 + 447) & !511; // rounds up to multiple of 512
        let mut extra = [0u8; BLOCK_SIZE];
        let total_bytes = self.m_num_bytes + self.m_buffer_size as u64;

        let buffer = if padded_length < (BLOCK_SIZE * 8) as usize {
            &mut self.m_buffer
        } else {
            &mut extra
        };

        buf_has_len_bytes_fill(&mut buffer[self.m_buffer_size..BLOCK_SIZE], 0);
        buffer[self.m_buffer_size] = 128;

        let add_length = if padded_length < (BLOCK_SIZE * 8) as usize {
            &mut buffer[BLOCK_SIZE - 8..BLOCK_SIZE]
        } else {
            &mut buffer[BLOCK_SIZE - 8..]
        };

        let bit_length = (total_bytes * 8).to_be_bytes();
        add_length.clone_from_slice(&bit_length);

        // Clone buffer for use as immutable reference
        let buffer_clone = self.m_buffer.clone();
        self.process_block(&buffer_clone);
        if padded_length >= (BLOCK_SIZE * 8) as usize {
            self.process_block(&extra);
        }
    }

    /// Return latest hash as 64 hex characters
    pub fn get_hash(&mut self) -> String {
        let mut raw_hash = [0u8; HASH_BYTES];
        self.get_hash_bytes(&mut raw_hash);

        let mut result = String::with_capacity(2 * HASH_BYTES);
        for byte in raw_hash.iter() {
            result.push_str(&format!("{:02x}", byte));
        }

        result
    }

    /// Return latest hash as bytes
    pub fn get_hash_bytes(&mut self, buffer: &mut [u8; HASH_BYTES]) {
        self.process_buffer();

        for (i, &word) in self.m_hash.iter().enumerate() {
            let bytes = word.to_be_bytes();
            buffer[i * 4..i * 4 + 4].copy_from_slice(&bytes);
        }
    }

    /// Compute SHA256 of a memory block
    pub fn sha256(data: &[u8]) -> String {
        let mut hasher = SHA256::new();
        hasher.add(data);
        hasher.get_hash()
    }

    /// Compute SHA256 of a string, excluding final zero
    pub fn sha256_string(text: &str) -> String {
        SHA256::sha256(text.as_bytes())
    }
}

fn rotate(value: u32, bits: u32) -> u32 {
    (value >> bits) | (value << (32 - bits))
}

fn bswap(value: u32) -> u32 {
    value.to_be()
}

fn f1(e: u32, f: u32, g: u32) -> u32 {
    rotate(e, 6) ^ rotate(e, 11) ^ rotate(e, 25) + ((e & f) ^ ((!e) & g))
}

fn f2(a: u32, b: u32, c: u32) -> u32 {
    rotate(a, 2) ^ rotate(a, 13) ^ rotate(a, 22) + ((a & b) | (b & c) | (a & c))
}

fn sigma0(value: u32) -> u32 {
    rotate(value, 7) ^ rotate(value, 18) ^ (value >> 3)
}

fn sigma1(value: u32) -> u32 {
    rotate(value, 17) ^ rotate(value, 19) ^ (value >> 10)
}

fn buf_has_len_bytes_fill(buf: &mut [u8], value: u8) {
    for b in buf.iter_mut() {
        *b = value;
    }
}

