fn f1(e: u32, f: u32, g: u32) -> u32 {
    let term1 = rotate(e, 6) ^ rotate(e, 11) ^ rotate(e, 25);
    let term2 = (e & f) ^ (!e & g);
    term1.wrapping_add(term2)
}

fn f2(a: u32, b: u32, c: u32) -> u32 {
    let term1 = rotate(a, 2) ^ rotate(a, 13) ^ rotate(a, 22);
    let term2 = ((a | b) & c) | (a & b);
    term1.wrapping_add(term2)
}

pub struct SHA256 {
    m_num_bytes: u64,
    m_buffer_size: usize,
    m_hash: [u32; 8],
    m_buffer: [u8; 64],
}

impl SHA256 {
    pub const HASH_BYTES: usize = 32;
    pub const HASH_VALUES: usize = 8;
    pub const BLOCK_SIZE: usize = 64;

    pub fn new() -> SHA256 {
        let mut sha = SHA256 {
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_hash: [0; 8],
            m_buffer: [0; 64],
        };
        sha.reset();
        sha
    }

    pub fn reset(&mut self) {
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;

        self.m_hash[0] = 0x6a09e667;
        self.m_hash[1] = 0xbb67ae85;
        self.m_hash[2] = 0x3c6ef372;
        self.m_hash[3] = 0xa54ff53a;
        self.m_hash[4] = 0x510e527f;
        self.m_hash[5] = 0x9b05688c;
        self.m_hash[6] = 0x1f83d9ab;
        self.m_hash[7] = 0x5be0cd19;
    }

    pub fn process_block(&mut self, data: &[u8]) {
        let mut a = self.m_hash[0];
        let mut b = self.m_hash[1];
        let mut c = self.m_hash[2];
        let mut d = self.m_hash[3];
        let mut e = self.m_hash[4];
        let mut f = self.m_hash[5];
        let mut g = self.m_hash[6];
        let mut h = self.m_hash[7];

        let mut words = [0u32; 64];
        for i in 0..16 {
            words[i] = u32::from_be_bytes([data[i * 4], data[i * 4 + 1], data[i * 4 + 2], data[i * 4 + 3]]);
        }

        for i in 16..64 {
            let s0 = rotate(words[i - 15], 7) ^ rotate(words[i - 15], 18) ^ (words[i - 15] >> 3);
            let s1 = rotate(words[i - 2], 17) ^ rotate(words[i - 2], 19) ^ (words[i - 2] >> 10);
            words[i] = words[i - 16]
                .wrapping_add(s0)
                .wrapping_add(words[i - 7])
                .wrapping_add(s1);
        }

        for i in 0..64 {
            let t1 = h
                .wrapping_add(f1(e, f, g))
                .wrapping_add(SHA256_CONSTANTS[i])
                .wrapping_add(words[i]);
            let t2 = f2(a, b, c);
            h = g;
            g = f;
            f = e;
            e = d.wrapping_add(t1);
            d = c;
            c = b;
            b = a;
            a = t1.wrapping_add(t2);
        }

        self.m_hash[0] = self.m_hash[0].wrapping_add(a);
        self.m_hash[1] = self.m_hash[1].wrapping_add(b);
        self.m_hash[2] = self.m_hash[2].wrapping_add(c);
        self.m_hash[3] = self.m_hash[3].wrapping_add(d);
        self.m_hash[4] = self.m_hash[4].wrapping_add(e);
        self.m_hash[5] = self.m_hash[5].wrapping_add(f);
        self.m_hash[6] = self.m_hash[6].wrapping_add(g);
        self.m_hash[7] = self.m_hash[7].wrapping_add(h);
    }

    pub fn add(&mut self, data: &[u8]) {
        let mut data = data;

        if self.m_buffer_size > 0 {
            let buffer_space = SHA256::BLOCK_SIZE - self.m_buffer_size;
            let needed = std::cmp::min(buffer_space, data.len());
            self.m_buffer[self.m_buffer_size..self.m_buffer_size + needed]
                .copy_from_slice(&data[..needed]);
            self.m_buffer_size += needed;
            data = &data[needed..];

            if self.m_buffer_size == SHA256::BLOCK_SIZE {
                self.process_block(&self.m_buffer.clone());
                self.m_num_bytes += SHA256::BLOCK_SIZE as u64;
                self.m_buffer_size = 0;
            }
        }

        let mut chunks = data.chunks_exact(SHA256::BLOCK_SIZE);
        for chunk in chunks.by_ref() {
            self.process_block(chunk);
            self.m_num_bytes += SHA256::BLOCK_SIZE as u64;
        }

        let remainder = chunks.remainder();
        self.m_buffer[..remainder.len()].copy_from_slice(remainder);
        self.m_buffer_size = remainder.len();
    }

    pub fn process_buffer(&mut self) {
        let bit_size = (self.m_num_bytes + self.m_buffer_size as u64) * 8;
        let mut padding_size = (self.m_buffer_size * 8 + 1) as u64;

        if padding_size <= 448 {
            padding_size = 448 - padding_size;
        } else {
            padding_size = 512 + 448 - padding_size;
        }

        padding_size /= 8;

        let mut padding = [0u8; 64];
        padding[0] = 0x80;

        if self.m_buffer_size + (padding_size as usize) < 64 {
            self.m_buffer[self.m_buffer_size..self.m_buffer_size + padding_size as usize]
                .copy_from_slice(&padding[..(padding_size as usize)]);
            self.m_buffer[(self.m_buffer_size + padding_size as usize)..63].fill(0);
            for i in 0..8 {
                self.m_buffer[63 - i] = (bit_size >> (8 * i)) as u8;
            }
            let buffer: [u8; 64] = self.m_buffer.clone(); 
            self.process_block(&buffer);
        } else {
            let extra_size = self.m_buffer_size + padding_size as usize - 64;
            self.m_buffer[self.m_buffer_size..].copy_from_slice(&padding[..(64 - self.m_buffer_size)]);
            {
                let buffer: [u8; 64] = self.m_buffer.clone();
                self.process_block(&buffer);
            }
            self.m_buffer[..extra_size].fill(0);
            for i in 0..8 {
                self.m_buffer[63 - i] = (bit_size >> (8 * i)) as u8;
            }
            let buffer: [u8; 64] = self.m_buffer.clone();
            self.process_block(&buffer);
        }
    }

    pub fn get_hash(&mut self) -> String {
        let mut buf = [0u8; SHA256::HASH_BYTES];
        self.get_hash_bytes(&mut buf);

        buf.iter()
            .map(|byte| format!("{:02x}", byte))
            .collect()
    }

    fn get_hash_bytes(&mut self, buffer: &mut [u8; SHA256::HASH_BYTES]) {
        let old_state = self.m_hash;
        self.process_buffer();

        for i in 0..self.m_hash.len() {
            buffer[i * 4..i * 4 + 4].copy_from_slice(&self.m_hash[i].to_be_bytes());
        }

        self.m_hash = old_state;
    }

    pub fn digest(&mut self, data: &[u8]) -> Vec<u8> {
        self.reset();
        self.add(data);
        let buf = vec![0; SHA256::HASH_BYTES];
        let mut clone_buf: [u8; SHA256::HASH_BYTES] = buf.clone().try_into().unwrap();
        self.get_hash_bytes(&mut clone_buf);
        clone_buf.to_vec()
    }
}

