use std::convert::TryInto;

const SHA2_BLOCK_SIZE: usize = 64;
const SHA2_HASH_BYTES: usize = 32;

pub struct SHA256 {
    m_num_bytes: usize,
    m_buffer_size: usize,
    m_buffer: [u8; SHA2_BLOCK_SIZE],
    m_hash: [u32; 8],
}

impl SHA256 {
    pub fn new() -> Self {
        let mut instance = Self {
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_buffer: [0; SHA2_BLOCK_SIZE],
            m_hash: [0; 8],
        };
        instance.reset();
        instance
    }

    pub fn reset(&mut self) {
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;

        // Seed values for SHA-256
        self.m_hash[0] = 0x6a09e667;
        self.m_hash[1] = 0xbb67ae85;
        self.m_hash[2] = 0x3c6ef372;
        self.m_hash[3] = 0xa54ff53a;
        self.m_hash[4] = 0x510e527f;
        self.m_hash[5] = 0x9b05688c;
        self.m_hash[6] = 0x1f83d9ab;
        self.m_hash[7] = 0x5be0cd19;

        // Uncomment for SHA-224
        // self.m_hash[0] = 0xc1059ed8;
        // self.m_hash[1] = 0x367cd507;
        // self.m_hash[2] = 0x3070dd17;
        // self.m_hash[3] = 0xf70e5939;
        // self.m_hash[4] = 0xffc00b31;
        // self.m_hash[5] = 0x68581511;
        // self.m_hash[6] = 0x64f98fa7;
        // self.m_hash[7] = 0xbefa4fa4;
    }

    pub fn process_block(&mut self, data: &[u8; SHA2_BLOCK_SIZE]) {
        let mut words: [u32; 64] = [0; 64];

        // Cast data to u32 array and handle endianess
        let input = unsafe { std::slice::from_raw_parts(data.as_ptr() as *const u32, 16) };
        for i in 0..16 {
            words[i] = u32::from_be(input[i]);
        }

        let (mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut h) =
            (self.m_hash[0], self.m_hash[1], self.m_hash[2], self.m_hash[3], self.m_hash[4], self.m_hash[5], self.m_hash[6], self.m_hash[7]);

        // Calculate words 16-63
        for i in 16..64 {
            words[i] = words[i - 16]
                .wrapping_add(rotate(words[i - 15], 7) ^ rotate(words[i - 15], 18) ^ (words[i - 15] >> 3))
                .wrapping_add(words[i - 7])
                .wrapping_add(rotate(words[i - 2], 17) ^ rotate(words[i - 2], 19) ^ (words[i - 2] >> 10));
        }

        // Compression function
        for i in 0..64 {
            let k = match i {
                0..=15 => [0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
                           0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174][i],
                16..=31 => [0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
                            0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967][i - 16],
                32..=47 => [0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
                            0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070][i - 32],
                48..=63 => [0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
                            0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2][i - 48],
                _ => unreachable!(),
            };

            let x = h
                .wrapping_add(f1(e, f, g))
                .wrapping_add(k)
                .wrapping_add(words[i]);
            let y = f2(a, b, c);

            d = d.wrapping_add(x);
            h = x.wrapping_add(y);

            std::mem::swap(&mut h, &mut g);
            std::mem::swap(&mut g, &mut f);
            std::mem::swap(&mut f, &mut e);
            e = e.wrapping_add(d);
            std::mem::swap(&mut d, &mut c);
            std::mem::swap(&mut c, &mut b);
            std::mem::swap(&mut b, &mut a);
            a = h;
        }

        // Update state
        self.m_hash[0] = self.m_hash[0].wrapping_add(a);
        self.m_hash[1] = self.m_hash[1].wrapping_add(b);
        self.m_hash[2] = self.m_hash[2].wrapping_add(c);
        self.m_hash[3] = self.m_hash[3].wrapping_add(d);
        self.m_hash[4] = self.m_hash[4].wrapping_add(e);
        self.m_hash[5] = self.m_hash[5].wrapping_add(f);
        self.m_hash[6] = self.m_hash[6].wrapping_add(g);
        self.m_hash[7] = self.m_hash[7].wrapping_add(h);
    }

    pub fn add(&mut self, data: &[u8]) {
        let mut current = 0;
        let mut num_bytes = data.len();

        if self.m_buffer_size > 0 {
            while num_bytes > 0 && self.m_buffer_size < SHA2_BLOCK_SIZE {
                self.m_buffer[self.m_buffer_size] = data[current];
                self.m_buffer_size += 1;
                current += 1;
                num_bytes -= 1;
            }
        }

        if self.m_buffer_size == SHA2_BLOCK_SIZE {
            self.process_block(&self.m_buffer.try_into().unwrap());
            self.m_num_bytes += SHA2_BLOCK_SIZE;
            self.m_buffer_size = 0;
        }

        while num_bytes >= SHA2_BLOCK_SIZE {
            let block: [u8; SHA2_BLOCK_SIZE] = data[current..current + SHA2_BLOCK_SIZE].try_into().unwrap();
            self.process_block(&block);
            current += SHA2_BLOCK_SIZE;
            self.m_num_bytes += SHA2_BLOCK_SIZE;
            num_bytes -= SHA2_BLOCK_SIZE;
        }

        while num_bytes > 0 {
            self.m_buffer[self.m_buffer_size] = data[current];
            self.m_buffer_size += 1;
            current += 1;
            num_bytes -= 1;
        }
    }

    fn process_buffer(&mut self) {
        let num_bits = (self.m_num_bytes + self.m_buffer_size) as u64 * 8;
        let mut padding_length = if self.m_buffer_size < SHA2_BLOCK_SIZE {
            self.m_buffer[self.m_buffer_size] = 0x80;
            self.m_buffer_size + 1
        } else {
            0
        };

        let mut total_buffer = [0u8; SHA2_BLOCK_SIZE * 2];
        total_buffer[..self.m_buffer_size].copy_from_slice(&self.m_buffer[..self.m_buffer_size]);
        if self.m_buffer_size >= SHA2_BLOCK_SIZE {
            self.process_block(&total_buffer[..SHA2_BLOCK_SIZE].try_into().unwrap());
            total_buffer[..].fill(0);
            padding_length = 0;
        }

        if padding_length > 0 || self.m_buffer_size == SHA2_BLOCK_SIZE {
            while padding_length != 56 {
                total_buffer[padding_length] = 0;
                padding_length += 1;
                if padding_length == SHA2_BLOCK_SIZE {
                    self.process_block(&total_buffer[..SHA2_BLOCK_SIZE].try_into().unwrap());
                    total_buffer[..].fill(0);
                    padding_length = 0;
                }
            }
        }

        total_buffer[56..].copy_from_slice(&num_bits.to_be_bytes()[..8]);
        self.process_block(&total_buffer[..SHA2_BLOCK_SIZE].try_into().unwrap());
    }

    pub fn get_hash(&mut self) -> String {
        let mut hash = [0u8; SHA2_HASH_BYTES];
        self.get_raw_hash(&mut hash);

        hash.iter().map(|byte| format!("{:02x}", byte)).collect()
    }

    pub fn get_raw_hash(&mut self, hash_buffer: &mut [u8; SHA2_HASH_BYTES]) {
        let saved_hash = self.m_hash;
        self.process_buffer();

        for (i, value) in self.m_hash.iter().enumerate() {
            hash_buffer[i * 4..(i + 1) * 4].copy_from_slice(&value.to_be_bytes());
        }

        self.m_hash = saved_hash;
    }

    pub fn compute_hash(data: &[u8]) -> String {
        let mut hasher = SHA256::new();
        hasher.reset();
        hasher.add(data);
        hasher.get_hash()
    }

    pub fn compute_hash_from_string(text: &str) -> String {
        let mut hasher = SHA256::new();
        hasher.reset();
        hasher.add(text.as_bytes());
        hasher.get_hash()
    }
}

fn rotate(x: u32, c: u32) -> u32 {
    (x >> c) | (x << (32 - c))
}

fn f1(e: u32, f: u32, g: u32) -> u32 {
    let term1 = rotate(e, 6) ^ rotate(e, 11) ^ rotate(e, 25);
    let term2 = (e & f) ^ ((!e) & g);
    term1.wrapping_add(term2)
}

fn f2(a: u32, b: u32, c: u32) -> u32 {
    let term1 = rotate(a, 2) ^ rotate(a, 13) ^ rotate(a, 22);
    let term2 = (a & b) | (c & (a | b));
    term1.wrapping_add(term2)
}

