pub struct SHA256 {
    m_num_bytes: usize,
    m_buffer_size: usize,
    m_hash: [u32; 8],
    m_buffer: [u8; Self::BLOCK_SIZE],
}

impl SHA256 {
    pub const BLOCK_SIZE: usize = 64;
    pub const HASH_BYTES: usize = 32;
    pub const HASH_VALUES: usize = 8;

    pub fn new() -> Self {
        let mut instance = SHA256 {
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_hash: [0; Self::HASH_VALUES],
            m_buffer: [0; Self::BLOCK_SIZE],
        };
        instance.reset();
        instance
    }

    pub fn reset(&mut self) {
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;
        self.m_hash = [
            0x6a09e667,
            0xbb67ae85,
            0x3c6ef372,
            0xa54ff53a,
            0x510e527f,
            0x9b05688c,
            0x1f83d9ab,
            0x5be0cd19,
        ];
    }

    pub fn add(&mut self, data: &[u8]) {
        let mut num_bytes = data.len();
        let mut current = data;

        if self.m_buffer_size > 0 {
            while num_bytes > 0 && self.m_buffer_size < Self::BLOCK_SIZE {
                self.m_buffer[self.m_buffer_size] = current[0];
                self.m_buffer_size += 1;
                current = &current[1..];
                num_bytes -= 1;
            }
        }

        if self.m_buffer_size == Self::BLOCK_SIZE {
            let buffer_copy = self.m_buffer.clone();
            self.process_block(&buffer_copy);
            self.m_num_bytes += Self::BLOCK_SIZE;
            self.m_buffer_size = 0;
        }

        while num_bytes >= Self::BLOCK_SIZE {
            self.process_block(&current[..Self::BLOCK_SIZE]);
            current = &current[Self::BLOCK_SIZE..];
            self.m_num_bytes += Self::BLOCK_SIZE;
            num_bytes -= Self::BLOCK_SIZE;
        }

        for byte in current.iter() {
            self.m_buffer[self.m_buffer_size] = *byte;
            self.m_buffer_size += 1;
        }
    }

    pub fn get_hash_string(&mut self) -> String {
        let mut raw_hash = [0u8; Self::HASH_BYTES];
        self.get_hash(&mut raw_hash);

        let mut result = String::new();
        for byte in raw_hash.iter() {
            result.push_str(&format!("{:02x}", byte));
        }

        result
    }

    pub fn get_hash(&mut self, buffer: &mut [u8]) {
        let old_hash = self.m_hash.clone();

        self.process_buffer();

        for (i, &val) in self.m_hash.iter().enumerate() {
            buffer[4 * i] = ((val >> 24) & 0xFF) as u8;
            buffer[4 * i + 1] = ((val >> 16) & 0xFF) as u8;
            buffer[4 * i + 2] = ((val >> 8) & 0xFF) as u8;
            buffer[4 * i + 3] = (val & 0xFF) as u8;
        }

        self.m_hash = old_hash;
    }

    pub fn process_block(&mut self, data: &[u8]) {
        let mut a = self.m_hash[0];
        let mut b = self.m_hash[1];
        let mut c = self.m_hash[2];
        let mut d = self.m_hash[3];
        let mut e = self.m_hash[4];
        let mut f = self.m_hash[5];
        let mut g = self.m_hash[6];
        let mut h = self.m_hash[7];

        let mut words = [0u32; 64];
        for i in 0..16 {
            words[i] = u32::from_be_bytes([
                data[(i * 4) + 0],
                data[(i * 4) + 1],
                data[(i * 4) + 2],
                data[(i * 4) + 3],
            ]);
        }

        for i in 16..64 {
            words[i] = words[i - 16]
                .wrapping_add(sigma0(words[i - 15]))
                .wrapping_add(words[i - 7])
                .wrapping_add(sigma1(words[i - 2]));
        }

        let mut x: u32;
        let mut y: u32;

        for i in 0..64 {
            const K: [u32; 64] = [
                0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5,
                0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
                0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
                0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
                0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc,
                0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
                0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
                0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
                0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
                0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
                0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3,
                0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
                0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5,
                0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
                0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
                0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
            ];

            x = h
                .wrapping_add(f1(e, f, g))
                .wrapping_add(K[i])
                .wrapping_add(words[i]);
            y = f2(a, b, c);
            d = d.wrapping_add(x);
            h = x.wrapping_add(y);

            macro_rules! rotate {
                () => {
                    let tmp = h;
                    h = g;
                    g = f;
                    f = e;
                    e = d;
                    d = c;
                    c = b;
                    b = a;
                    a = tmp;
                };
            }

            rotate!();
        }

        self.m_hash[0] = self.m_hash[0].wrapping_add(a);
        self.m_hash[1] = self.m_hash[1].wrapping_add(b);
        self.m_hash[2] = self.m_hash[2].wrapping_add(c);
        self.m_hash[3] = self.m_hash[3].wrapping_add(d);
        self.m_hash[4] = self.m_hash[4].wrapping_add(e);
        self.m_hash[5] = self.m_hash[5].wrapping_add(f);
        self.m_hash[6] = self.m_hash[6].wrapping_add(g);
        self.m_hash[7] = self.m_hash[7].wrapping_add(h);
    }

    fn process_buffer(&mut self) {
        let mut padded_length = self.m_buffer_size * 8;
        padded_length += 1;

        let lower11_bits = padded_length & 511;
        if lower11_bits <= 448 {
            padded_length += 448 - lower11_bits;
        } else {
            padded_length += 512 + 448 - lower11_bits;
        }
        padded_length /= 8;

        let mut extra = [0u8; Self::BLOCK_SIZE];
        if self.m_buffer_size < Self::BLOCK_SIZE {
            self.m_buffer[self.m_buffer_size] = 128;
        } else {
            extra[0] = 128;
        }

        for i in self.m_buffer_size + 1..Self::BLOCK_SIZE {
            self.m_buffer[i] = 0;
        }

        let msg_bits = 8 * (self.m_num_bytes + self.m_buffer_size);

        let add_length = if padded_length < Self::BLOCK_SIZE {
            &mut self.m_buffer[padded_length..]
        } else {
            &mut extra[(padded_length - Self::BLOCK_SIZE)..]
        };

        add_length[0] = ((msg_bits >> 56) & 0xFF) as u8;
        add_length[1] = ((msg_bits >> 48) & 0xFF) as u8;
        add_length[2] = ((msg_bits >> 40) & 0xFF) as u8;
        add_length[3] = ((msg_bits >> 32) & 0xFF) as u8;
        add_length[4] = ((msg_bits >> 24) & 0xFF) as u8;
        add_length[5] = ((msg_bits >> 16) & 0xFF) as u8;
        add_length[6] = ((msg_bits >> 8) & 0xFF) as u8;
        add_length[7] = (msg_bits & 0xFF) as u8;

        let buffer_copy = self.m_buffer.clone();
        self.process_block(&buffer_copy);
        if padded_length > Self::BLOCK_SIZE {
            self.process_block(&extra);
        }
    }

    pub fn compute_hash(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash_string()
    }
}

fn rotate(a: u32, c: u32) -> u32 {
    (a >> c) | (a << (32 - c))
}

fn swap(x: u32) -> u32 {
    x.to_be()
}

fn f1(e: u32, f: u32, g: u32) -> u32 {
    let term1 = rotate(e, 6) ^ rotate(e, 11) ^ rotate(e, 25);
    let term2 = (e & f) ^ (!e & g);
    term1.wrapping_add(term2)
}

fn f2(a: u32, b: u32, c: u32) -> u32 {
    let term1 = rotate(a, 2) ^ rotate(a, 13) ^ rotate(a, 22);
    let term2 = ((a | b) & c) | (a & b);
    term1.wrapping_add(term2)
}

fn sigma0(x: u32) -> u32 {
    rotate(x, 7) ^ rotate(x, 18) ^ (x >> 3)
}

fn sigma1(x: u32) -> u32 {
    rotate(x, 17) ^ rotate(x, 19) ^ (x >> 10)
}

fn main() {
    let data = b"hello world";
    let mut sha256 = SHA256::new();
    let hash = sha256.compute_hash(data);
    println!("Hash: {}", hash);
}

