/// Structure representing the state of a SHA256 computation
pub struct SHA256 {
    m_num_bytes: u64,
    m_buffer_size: usize,
    m_hash: [u32; 8],
    m_buffer: [u8; SHA256::BLOCK_SIZE],
}

impl SHA256 {
    pub const BLOCK_SIZE: usize = 64;
    pub const HASH_BYTES: usize = 32;
    const HASH_VALUES: usize = 8;

    pub fn new() -> Self {
        let mut sha = Self {
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_hash: [0; 8],
            m_buffer: [0; SHA256::BLOCK_SIZE],
        };
        sha.reset();
        sha
    }

    pub fn reset(&mut self) {
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;

        self.m_hash[0] = 0x6a09e667;
        self.m_hash[1] = 0xbb67ae85;
        self.m_hash[2] = 0x3c6ef372;
        self.m_hash[3] = 0xa54ff53a;
        self.m_hash[4] = 0x510e527f;
        self.m_hash[5] = 0x9b05688c;
        self.m_hash[6] = 0x1f83d9ab;
        self.m_hash[7] = 0x5be0cd19;
    }

    fn rotate(a: u32, c: u32) -> u32 {
        (a >> c) | (a << (32 - c))
    }

    fn swap(x: u32) -> u32 {
        x.swap_bytes()
    }

    fn f1(e: u32, f: u32, g: u32) -> u32 {
        let term1 = Self::rotate(e, 6) ^ Self::rotate(e, 11) ^ Self::rotate(e, 25);
        let term2 = (e & f) ^ (!e & g);
        term1.wrapping_add(term2)
    }

    fn f2(a: u32, b: u32, c: u32) -> u32 {
        let term1 = Self::rotate(a, 2) ^ Self::rotate(a, 13) ^ Self::rotate(a, 22);
        let term2 = ((a | b) & c) | (a & b);
        term1.wrapping_add(term2)
    }

    pub fn process_block(&mut self, data: &[u8; SHA256::BLOCK_SIZE]) {
        let mut w = [0u32; 64];
        for i in 0..16 {
            w[i] = u32::from_be_bytes(data[4 * i..4 * (i + 1)].try_into().unwrap());
        }

        for i in 16..64 {
            let s0 = Self::rotate(w[i - 15], 7) ^ Self::rotate(w[i - 15], 18) ^ (w[i - 15] >> 3);
            let s1 = Self::rotate(w[i - 2], 17) ^ Self::rotate(w[i - 2], 19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16].wrapping_add(s0).wrapping_add(w[i - 7]).wrapping_add(s1);
        }

        let mut a = self.m_hash[0];
        let mut b = self.m_hash[1];
        let mut c = self.m_hash[2];
        let mut d = self.m_hash[3];
        let mut e = self.m_hash[4];
        let mut f = self.m_hash[5];
        let mut g = self.m_hash[6];
        let mut h = self.m_hash[7];

        // Round constants
        let k = [
            0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1,
            0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
            0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786,
            0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
            0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147,
            0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
            0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
            0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
            0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
            0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
            0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
        ];

        for i in 0..64 {
            let t1 = h
                .wrapping_add(Self::f1(e, f, g))
                .wrapping_add(k[i])
                .wrapping_add(w[i]);
            let t2 = Self::f2(a, b, c);
            h = g;
            g = f;
            f = e;
            e = d.wrapping_add(t1);
            d = c;
            c = b;
            b = a;
            a = t1.wrapping_add(t2);
        }

        self.m_hash[0] = self.m_hash[0].wrapping_add(a);
        self.m_hash[1] = self.m_hash[1].wrapping_add(b);
        self.m_hash[2] = self.m_hash[2].wrapping_add(c);
        self.m_hash[3] = self.m_hash[3].wrapping_add(d);
        self.m_hash[4] = self.m_hash[4].wrapping_add(e);
        self.m_hash[5] = self.m_hash[5].wrapping_add(f);
        self.m_hash[6] = self.m_hash[6].wrapping_add(g);
        self.m_hash[7] = self.m_hash[7].wrapping_add(h);
    }

    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;
        if self.m_buffer_size > 0 {
            let n = std::cmp::min(Self::BLOCK_SIZE - self.m_buffer_size, current.len());
            self.m_buffer[self.m_buffer_size..self.m_buffer_size + n]
                .copy_from_slice(&current[..n]);
            current = &current[n..];
            self.m_buffer_size += n;
        }
        if self.m_buffer_size == Self::BLOCK_SIZE {
            let buffer_copy = self.m_buffer; // Immutable borrow workaround
            self.process_block(&buffer_copy);
            self.m_num_bytes += Self::BLOCK_SIZE as u64;
            self.m_buffer_size = 0;
        }
        while current.len() >= Self::BLOCK_SIZE {
            self.process_block(&current[..Self::BLOCK_SIZE].try_into().unwrap());
            self.m_num_bytes += Self::BLOCK_SIZE as u64;
            current = &current[Self::BLOCK_SIZE..];
        }
        if !current.is_empty() {
            self.m_buffer[..current.len()].copy_from_slice(current);
            self.m_buffer_size = current.len();
        }
    }

    fn process_buffer(&mut self) {
        let padded_length = if self.m_buffer_size < 56 {
            64
        } else {
            128
        };

        let mut extra = [0u8; SHA256::BLOCK_SIZE];
        self.m_buffer[self.m_buffer_size] = 128;
        for i in self.m_buffer_size + 1..Self::BLOCK_SIZE {
            self.m_buffer[i] = 0;
        }
        let bit_len = 8 * (self.m_num_bytes + self.m_buffer_size as u64);
        for (i, _byte) in (0..8).rev().enumerate() { // Changed `byte` to `_byte` to avoid warning
            let pos = padded_length - 8 + i;
            if pos < Self::BLOCK_SIZE {
                self.m_buffer[pos] = ((bit_len >> (8 * (7 - i))) & 0xFF) as u8;
            } else {
                extra[pos - Self::BLOCK_SIZE] = ((bit_len >> (8 * (7 - i))) & 0xFF) as u8;
            }
        }
        let buffer_copy = self.m_buffer; // Immutable borrow workaround
        self.process_block(&buffer_copy);
        if padded_length > Self::BLOCK_SIZE {
            self.process_block(&extra);
        }
    }

    pub fn get_hash_bytes(&mut self) -> [u8; Self::HASH_BYTES] {
        let mut hash = [0u8; Self::HASH_BYTES];
        let old_hash = self.m_hash;
        self.process_buffer();
        for (i, &h) in self.m_hash.iter().enumerate() {
            hash[4 * i..4 * (i + 1)].copy_from_slice(&h.to_be_bytes());
        }
        self.m_hash = old_hash;
        hash
    }

    pub fn get_hash(&mut self) -> String {
        let raw_hash = self.get_hash_bytes();
        raw_hash.iter().map(|byte| format!("{:02x}", byte)).collect()
    }

    pub fn digest(data: &[u8]) -> String {
        let mut sha = Self::new();
        sha.add(data);
        sha.get_hash()
    }

    pub fn digest_str(text: &str) -> String {
        Self::digest(text.as_bytes())
    }
}

