impl SHA3 {
    pub fn new(bits: Bits) -> SHA3 {
        let block_size = 200 - 2 * (bits as usize / 8);
        let mut sha3 = SHA3 {
            m_blockSize: block_size,
            m_bits: bits,
            m_hash: [0; 25],
            m_buffer: [0; 200],
            m_numBytes: 0,
            m_bufferSize: 0,
        };
        sha3.reset();
        sha3
    }

    pub fn reset(&mut self) {
        for i in &mut self.m_hash {
            *i = 0;
        }
        self.m_numBytes = 0;
        self.m_bufferSize = 0;
    }

    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;

        if self.m_bufferSize > 0 {
            while !current.is_empty() && self.m_bufferSize < self.m_blockSize {
                self.m_buffer[self.m_bufferSize] = current[0];
                self.m_bufferSize += 1;
                current = &current[1..];
            }
        }

        if self.m_bufferSize == self.m_blockSize {
            let buffer_clone = self.m_buffer; // Make a copy of the buffer
            self.process_block(&buffer_clone); // Pass the copy to avoid aliasing
            self.m_numBytes += self.m_blockSize;
            self.m_bufferSize = 0;
        }

        while current.len() >= self.m_blockSize {
            self.process_block(&current[..self.m_blockSize]);
            current = &current[self.m_blockSize..];
            self.m_numBytes += self.m_blockSize;
        }

        for &byte in current {
            self.m_buffer[self.m_bufferSize] = byte;
            self.m_bufferSize += 1;
        }
    }

    fn process_block(&mut self, data: &[u8]) {
        fn little_endian(x: u64) -> u64 {
            if cfg!(target_endian = "big") {
                x.swap_bytes()
            } else {
                x
            }
        }

        let data64 = as_u64_array(data);
        for i in 0..self.m_blockSize / 8 {
            self.m_hash[i] ^= little_endian(data64[i]);
        }

        for round in 0..ROUNDS {
            let mut coefficients = [0u64; 5];
            for i in 0..5 {
                coefficients[i] = self.m_hash[i]
                    ^ self.m_hash[i + 5]
                    ^ self.m_hash[i + 10]
                    ^ self.m_hash[i + 15]
                    ^ self.m_hash[i + 20];
            }

            for i in 0..5 {
                let one = coefficients[mod5(i + 4)] ^ rotate_left(coefficients[mod5(i + 1)], 1);
                for j in (0..25).step_by(5) {
                    self.m_hash[i + j] ^= one;
                }
            }

            // Rho Pi
            let mut last = self.m_hash[1];
            for &(pos, shift) in &[(10, 1), (7, 3), (11, 6), (17, 10), (18, 15),
                                   (3, 21), (5, 28), (16, 36), (8, 45), (21, 55),
                                   (24, 2), (4, 14), (15, 27), (23, 41), (19, 56),
                                   (13, 8), (12, 25), (2, 43), (20, 62), (14, 18),
                                   (22, 39), (9, 61), (6, 20)] {
                let one = self.m_hash[pos];
                self.m_hash[pos] = rotate_left(last, shift);
                last = one;
            }
            self.m_hash[1] = rotate_left(last, 44);

            // Chi
            for j in (0..STATE_SIZE).step_by(5) {
                let one = self.m_hash[j];
                let two = self.m_hash[j + 1];
                self.m_hash[j] ^= self.m_hash[j + 2] & !two;
                self.m_hash[j + 1] ^= self.m_hash[j + 3] & !self.m_hash[j + 2];
                self.m_hash[j + 2] ^= self.m_hash[j + 4] & !self.m_hash[j + 3];
                self.m_hash[j + 3] ^= one & !self.m_hash[j + 4];
                self.m_hash[j + 4] ^= two & !one;
            }

            // Iota
            self.m_hash[0] ^= XOR_MASKS[round];
        }
    }

    fn process_buffer(&mut self) {
        let mut offset = self.m_bufferSize;
        self.m_buffer[offset] = 0x06;
        offset += 1;
        while offset < self.m_blockSize {
            self.m_buffer[offset] = 0;
            offset += 1;
        }
        self.m_buffer[offset - 1] |= 0x80;
        let buffer_clone = self.m_buffer;
        self.process_block(&buffer_clone);
    }

    pub fn get_hash(&mut self) -> String {
        let old_hash = self.m_hash;
        self.process_buffer();

        let mut result = String::with_capacity(self.m_bits as usize / 4);
        let hash_length = self.m_bits as usize / 64;

        for i in 0..hash_length {
            for j in 0..8 {
                let byte = ((self.m_hash[i] >> (8 * j)) & 0xFF) as u8;
                result.push(DEC2HEX[(byte >> 4) as usize]);
                result.push(DEC2HEX[(byte & 0xF) as usize]);
            }
        }

        let remainder = self.m_bits as usize - hash_length * 64;
        let mut processed = 0;
        while processed < remainder {
            let byte = ((self.m_hash[hash_length] >> processed) & 0xFF) as u8;
            result.push(DEC2HEX[(byte >> 4) as usize]);
            result.push(DEC2HEX[(byte & 0xF) as usize]);
            processed += 8;
        }

        self.m_hash = old_hash;
        result
    }

    pub fn compute(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

