            one = self.m_hash[8];  self.m_hash[8] = rotate_left(last, 45); last = one;
            one = self.m_hash[21]; self.m_hash[21] = rotate_left(last, 55); last = one;
            one = self.m_hash[24]; self.m_hash[24] = rotate_left(last, 2); last = one;
            one = self.m_hash[4];  self.m_hash[4] = rotate_left(last, 14); last = one;
            one = self.m_hash[15]; self.m_hash[15] = rotate_left(last, 27); last = one;
            one = self.m_hash[23]; self.m_hash[23] = rotate_left(last, 41); last = one;
            one = self.m_hash[19]; self.m_hash[19] = rotate_left(last, 56); last = one;
            one = self.m_hash[13]; self.m_hash[13] = rotate_left(last, 8); last = one;
            one = self.m_hash[12]; self.m_hash[12] = rotate_left(last, 25); last = one;
            one = self.m_hash[2];  self.m_hash[2] = rotate_left(last, 43); last = one;
            one = self.m_hash[20]; self.m_hash[20] = rotate_left(last, 62); last = one;
            one = self.m_hash[14]; self.m_hash[14] = rotate_left(last, 18); last = one;
            one = self.m_hash[22]; self.m_hash[22] = rotate_left(last, 39); last = one;
            one = self.m_hash[9];  self.m_hash[9] = rotate_left(last, 61); last = one;
            one = self.m_hash[6];  self.m_hash[6] = rotate_left(last, 20); last = one;
            self.m_hash[1] = rotate_left(last, 44);

            for j in (0..StateSize).step_by(5) {
                let one = self.m_hash[j];
                let two = self.m_hash[j + 1];
                self.m_hash[j] ^= self.m_hash[j + 2] & !two;
                self.m_hash[j + 1] ^= self.m_hash[j + 3] & !self.m_hash[j + 2];
                self.m_hash[j + 2] ^= self.m_hash[j + 4] & !self.m_hash[j + 3];
                self.m_hash[j + 3] ^= one & !self.m_hash[j + 4];
                self.m_hash[j + 4] ^= two & !one;
            }

            self.m_hash[0] ^= XOR_MASKS[round];
        }
    }

    fn add(&mut self, data: &[u8]) {
        let mut current = data;

        if self.m_bufferSize > 0 {
            while !current.is_empty() && self.m_bufferSize < self.m_blockSize {
                self.m_buffer[self.m_bufferSize] = current[0];
                self.m_bufferSize += 1;
                current = &current[1..];
            }
        }

        if self.m_bufferSize == self.m_blockSize {
            let buffer_copy = self.m_buffer.clone(); 
            self.process_block(&buffer_copy);
            self.m_numBytes += self.m_blockSize;
            self.m_bufferSize = 0;
        }

        while current.len() >= self.m_blockSize {
            self.process_block(&current[..self.m_blockSize]);
            current = &current[self.m_blockSize..];
            self.m_numBytes += self.m_blockSize;
        }

        self.m_buffer[..current.len()].copy_from_slice(current);
        self.m_bufferSize += current.len();
    }

    fn process_buffer(&mut self) {
        let offset = self.m_bufferSize;
        self.m_buffer[offset] = 0x06;

        for i in offset + 1..self.m_blockSize {
            self.m_buffer[i] = 0;
        }

        self.m_buffer[self.m_blockSize - 1] |= 0x80;

        let buffer_copy = self.m_buffer.clone(); 
        self.process_block(&buffer_copy[..self.m_blockSize]);
    }

    pub fn get_hash(&mut self) -> String {
        let old_hash = self.m_hash.clone();
        self.process_buffer();

        let dec2hex = b"0123456789abcdef";

        let hash_length = self.m_bits / 64;
        let mut result = String::with_capacity(self.m_bits / 4);

        for i in 0..hash_length {
            for j in 0..8 {
                let one_byte = (self.m_hash[i] >> (8 * j)) as u8;
                result.push(dec2hex[(one_byte >> 4) as usize] as char);
                result.push(dec2hex[(one_byte & 15) as usize] as char);
            }
        }

        let remainder = self.m_bits - hash_length * 64;
        let mut processed = 0;

        while processed < remainder {
            let one_byte = (self.m_hash[hash_length] >> processed) as u8;
            result.push(dec2hex[(one_byte >> 4) as usize] as char);
            result.push(dec2hex[(one_byte & 15) as usize] as char);
            processed += 8;
        }

        self.m_hash.copy_from_slice(&old_hash);
        result
    }

    pub fn hash_memory(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    pub fn hash_string(&mut self, text: &str) -> String {
        self.reset();
        self.add(text.as_bytes());
        self.get_hash()
    }
}

fn main() {
    // Example usage
    let mut sha3 = SHA3::new(256);
    let message = "hello world";
    let hash = sha3.hash_string(message);
    println!("SHA3-256 of '{}': {}", message, hash);
}

pub struct SHA3 {
    m_block_size: usize,
    m_bits: Bits,
    m_num_bytes: usize,
    m_buffer_size: usize,
    m_hash: [u64; StateSize],
    m_buffer: [u8; 200], // Maximum buffer size needed
}

// The equivalent of Bits enum in Rust
#[derive(Copy, Clone)]
pub enum Bits {
    Bits224 = 224,
    Bits256 = 256,
    Bits384 = 384,
    Bits512 = 512,
}

// Constants and local helper functions
const ROUNDS: usize = 24;
const XOR_MASKS: [u64; ROUNDS] = [
    0x0000000000000001, 0x0000000000008082, 0x800000000000808a,
    0x8000000080008000, 0x000000000000808b, 0x0000000080000001,
    0x8000000080008081, 0x8000000000008009, 0x000000000000008a,
    0x0000000000000088, 0x0000000080008009, 0x000000008000000a,
    0x000000008000808b, 0x800000000000008b, 0x8000000000008089,
    0x8000000000008003, 0x8000000000008002, 0x8000000000000080,
    0x000000000000800a, 0x800000008000000a, 0x8000000080008081,
    0x8000000000008080, 0x0000000080000001, 0x8000000080008008,
];

const StateSize: usize = 25;

/// Rotate left and wrap around to the right
fn rotate_left(x: u64, num_bits: u8) -> u64 {
    x.rotate_left(num_bits.into())
}

/// Convert little vs big endian
fn swap(x: u64) -> u64 {
    x.to_be()
}

/// Return x % 5 for 0 <= x <= 9
fn mod5(x: u32) -> u32 {
    if x < 5 {
        x
    } else {
        x - 5
    }
}

impl SHA3 {
    /// Same as reset()
    pub fn new(bits: Bits) -> SHA3 {
        let mut instance = SHA3 {
            m_block_size: 200 - 2 * (bits as usize / 8),
            m_bits: bits,
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_hash: [0u64; StateSize],
            m_buffer: [0u8; 200],
        };
        instance.reset();
        instance
    }

    /// Restart
    pub fn reset(&mut self) {
        self.m_hash = [0u64; StateSize];
        self.m_num_bytes = 0;
        self.m_buffer_size = 0;
    }

    /// Process a full block
    fn process_block(&mut self, data: &[u8]) {
        let data64: &[u64] = unsafe { std::slice::from_raw_parts(data.as_ptr() as *const u64, self.m_block_size / 8) };

        for i in 0..self.m_block_size / 8 {
            self.m_hash[i] ^= u64::from_le(data64[i]);
        }

        for round in 0..ROUNDS {
            // Theta
            let mut coefficients = [0u64; 5];
            for i in 0..5 {
                coefficients[i] = self.m_hash[i] ^ self.m_hash[i + 5] ^ self.m_hash[i + 10] ^ self.m_hash[i + 15] ^ self.m_hash[i + 20];
            }

            for i in 0..5 {
                let one = coefficients[mod5(i + 4) as usize] ^ rotate_left(coefficients[mod5(i + 1) as usize], 1);
                let index = i as usize;
                self.m_hash[index] ^= one;
                self.m_hash[index + 5] ^= one;
                self.m_hash[index + 10] ^= one;
                self.m_hash[index + 15] ^= one;
                self.m_hash[index + 20] ^= one;
            }

            // Rho Pi
            let mut last = self.m_hash[1];
            let mut one;
            one = self.m_hash[10]; self.m_hash[10] = rotate_left(last, 1); last = one;
            one = self.m_hash[7]; self.m_hash[7] = rotate_left(last, 3); last = one;
            one = self.m_hash[11]; self.m_hash[11] = rotate_left(last, 6); last = one;
            one = self.m_hash[17]; self.m_hash[17] = rotate_left(last, 10); last = one;
            one = self.m_hash[18]; self.m_hash[18] = rotate_left(last, 15); last = one;
            one = self.m_hash[3]; self.m_hash[3] = rotate_left(last, 21); last = one;
            one = self.m_hash[5]; self.m_hash[5] = rotate_left(last, 28); last = one;
            one = self.m_hash[16]; self.m_hash[16] = rotate_left(last, 36); last = one;
            one = self.m_hash[8]; self.m_hash[8] = rotate_left(last, 45); last = one;
            one = self.m_hash[21]; self.m_hash[21] = rotate_left(last, 55); last = one;
            one = self.m_hash[24]; self.m_hash[24] = rotate_left(last, 2); last = one;
            one = self.m_hash[4]; self.m_hash[4] = rotate_left(last, 14); last = one;
            one = self.m_hash[15]; self.m_hash[15] = rotate_left(last, 27); last = one;
            one = self.m_hash[23]; self.m_hash[23] = rotate_left(last, 41); last = one;
            one = self.m_hash[19]; self.m_hash[19] = rotate_left(last, 56); last = one;
            one = self.m_hash[13]; self.m_hash[13] = rotate_left(last, 8); last = one;
            one = self.m_hash[12]; self.m_hash[12] = rotate_left(last, 25); last = one;
            one = self.m_hash[2]; self.m_hash[2] = rotate_left(last, 43); last = one;
            one = self.m_hash[20]; self.m_hash[20] = rotate_left(last, 62); last = one;
            one = self.m_hash[14]; self.m_hash[14] = rotate_left(last, 18); last = one;
            one = self.m_hash[22]; self.m_hash[22] = rotate_left(last, 39); last = one;
            one = self.m_hash[9]; self.m_hash[9] = rotate_left(last, 61); last = one;
            one = self.m_hash[6]; self.m_hash[6] = rotate_left(last, 20);
            self.m_hash[1] = rotate_left(one, 44);

            // Chi
            for j in 0..StateSize {
                if j % 5 == 0 {
                    let one = self.m_hash[j];
                    let two = self.m_hash[j + 1];
                    self.m_hash[j] ^= self.m_hash[j + 2] & !two;
                    self.m_hash[j + 1] ^= self.m_hash[j + 3] & !self.m_hash[j + 2];
                    self.m_hash[j + 2] ^= self.m_hash[j + 4] & !self.m_hash[j + 3];
                    self.m_hash[j + 3] ^= one & !self.m_hash[j + 4];
                    self.m_hash[j + 4] ^= two & !one;
                }
            }

            // Iota
            self.m_hash[0] ^= XOR_MASKS[round];
        }
    }

    /// Add arbitrary number of bytes
    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;

        // Copy data to buffer
        if self.m_buffer_size > 0 {
            while !current.is_empty() && self.m_buffer_size < self.m_block_size {
                self.m_buffer[self.m_buffer_size] = current[0];
                current = &current[1..];
                self.m_buffer_size += 1;
            }
        }

        // Full buffer
        if self.m_buffer_size == self.m_block_size {
            let mut buffer_copy = [0u8; 200];
            buffer_copy.copy_from_slice(&self.m_buffer);
            self.process_block(&buffer_copy);
            self.m_num_bytes += self.m_block_size;
            self.m_buffer_size = 0;
        }

        // No more data?
        if current.is_empty() {
            return;
        }

        // Process full blocks
        while current.len() >= self.m_block_size {
            let block = &current[..self.m_block_size];
            self.process_block(block);
            current = &current[self.m_block_size..];
            self.m_num_bytes += self.m_block_size;
        }

        // Keep remaining bytes in buffer
        for &byte in current {
            self.m_buffer[self.m_buffer_size] = byte;
            self.m_buffer_size += 1;
        }
    }

    /// Process everything left in the internal buffer
    pub fn process_buffer(&mut self) {
        // Add padding
        let mut offset = self.m_buffer_size;
        // Add a "1" byte
        self.m_buffer[offset] = 0x06;
        offset += 1;
        // Fill with zeros
        while offset < self.m_block_size {
            self.m_buffer[offset] = 0;
            offset += 1;
        }

        // Add a single set bit
        self.m_buffer[self.m_buffer_size] |= 0x80;

        let mut buffer_copy = [0u8; 200];
        buffer_copy.copy_from_slice(&self.m_buffer);
        self.process_block(&buffer_copy);
    }

    /// Return latest hash as hex string
    pub fn get_hash(&mut self) -> String {
        // Save hash state
        let old_hash = self.m_hash;

        // Process remaining bytes
        self.process_buffer();

        // Convert hash to string
        const DEC2HEX: &[u8] = b"0123456789abcdef";
        let hash_length = self.m_bits as usize / 64;

        let mut result = String::with_capacity(self.m_bits as usize / 4);
        for i in 0..hash_length {
            for j in 0..8 { // 64 bits => 8 bytes
                let one_byte = (self.m_hash[i] >> (8 * j)) as u8;
                result.push(DEC2HEX[(one_byte >> 4) as usize] as char);
                result.push(DEC2HEX[(one_byte & 15) as usize] as char);
            }
        }

        // SHA3-224's last entry in m_hash provides only 32 bits instead of 64 bits
        let remainder = self.m_bits as usize - hash_length * 64;
        let mut processed = 0;
        while processed < remainder {
            let one_byte = (self.m_hash[hash_length] >> processed) as u8;
            result.push(DEC2HEX[(one_byte >> 4) as usize] as char);
            result.push(DEC2HEX[(one_byte & 15) as usize] as char);
            processed += 8;
        }

        // Restore state
        self.m_hash = old_hash;

        result
    }

    /// Compute SHA3 of a memory block
    pub fn compute(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    /// Compute SHA3 of a string, excluding final zero
    pub fn compute_str(&mut self, text: &str) -> String {
        self.reset();
        self.add(text.as_bytes());
        self.get_hash()
    }
}

fn main() {
    let mut sha3 = SHA3::new(Bits::Bits256);
    let hash = sha3.compute_str("Hello, world!");
    println!("Hash: {}", hash);
}

