        let block_size = 200 - 2 * (bits as usize / 8);
        let mut sha3 = SHA3 {
            m_hash: [0; STATE_SIZE],
            m_buffer: [0; 200],
            m_num_bytes: 0,
            m_buffer_size: 0,
            m_block_size: block_size,
