    pub fn process_block(&mut self, data: &[u8]) {
        let data64: &[u64] = unsafe { std::slice::from_raw_parts(data.as_ptr() as *const u64, data.len() / 8) };

        for (i, &block) in data64.iter().enumerate().take(self.m_block_size / 8) {
