            self.m_hash[12] = rotate_left(last, 25);
            last = one;
            one = self.m_hash[2];
            self.m_hash[2] = rotate_left(last, 43);
            last = one;
            one = self.m_hash[20];
            self.m_hash[20] = rotate_left(last, 62);
            last = one;
