            one = self.m_hash[22];
            self.m_hash[22] = rotate_left(last, 39);
            last = one;
            one = self.m_hash[9];
            self.m_hash[9] = rotate_left(last, 61);
            last = one;
            one = self.m_hash[6];
            self.m_hash[6] = rotate_left(last, 20);
            self.m_hash[1] = rotate_left(one, 44);

            // Chi
            for j in (0..STATE_SIZE).step_by(5) {
                let t1 = self.m_hash[j];
                let t2 = self.m_hash[j + 1];

                self.m_hash[j] ^= self.m_hash[j + 2] & !t2;
                self.m_hash[j + 1] ^= self.m_hash[j + 3] & !self.m_hash[j + 2];
                self.m_hash[j + 2] ^= self.m_hash[j + 4] & !self.m_hash[j + 3];
                self.m_hash[j + 3] ^= t1 & !self.m_hash[j + 4];
                self.m_hash[j + 4] ^= t2 & !t1;
            }

            // Iota
            self.m_hash[0] ^= XOR_MASKS[round];
        }
