    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;

        if self.m_buffer_size > 0 {
            while !current.is_empty() && self.m_buffer_size < self.m_block_size {
                self.m_buffer[self.m_buffer_size] = current[0];
                self.m_buffer_size += 1;
                current = &current[1..];
            }

            if self.m_buffer_size == self.m_block_size {
                let buffer_copy = self.m_buffer.clone();
                self.process_block(&buffer_copy[..self.m_block_size]);
                self.m_num_bytes += self.m_block_size;
                self.m_buffer_size = 0;
            }
        }

        while current.len() >= self.m_block_size {
            self.process_block(&current[..self.m_block_size]);
            current = &current[self.m_block_size..];
            self.m_num_bytes += self.m_block_size;
        }

        while !current.is_empty() {
            self.m_buffer[self.m_buffer_size] = current[0];
            self.m_buffer_size += 1;
            current = &current[1..];
        }
    }

    pub fn process_buffer(&mut self) {
        let mut offset = self.m_buffer_size;
        self.m_buffer[offset] = 0x06;
        offset += 1;

        while offset < self.m_block_size {
            self.m_buffer[offset] = 0;
            offset += 1;
        }

        self.m_buffer[offset - 1] |= 0x80;
        let buffer_copy = self.m_buffer.clone();
        self.process_block(&buffer_copy[..self.m_block_size]);
    }

    pub fn get_hash(&mut self) -> String {
        let old_hash = self.m_hash.clone();
        self.process_buffer();

        let hash_length = self.m_bits as usize / 64;
        let mut result = String::with_capacity(self.m_bits as usize / 4);
        let dec2hex = b"0123456789abcdef";

        for i in 0..hash_length {
            for j in 0..8 {
                let byte = (self.m_hash[i] >> (8 * j)) as u8;
                result.push(dec2hex[(byte >> 4) as usize] as char);
                result.push(dec2hex[(byte & 0x0F) as usize] as char);
            }
        }

        let remainder = self.m_bits as usize - hash_length * 64;
        let mut processed = 0;
        while processed < remainder {
            let byte = (self.m_hash[hash_length] >> processed) as u8;
            result.push(dec2hex[(byte >> 4) as usize] as char);
            result.push(dec2hex[(byte & 0x0F) as usize] as char);
            processed += 8;
        }

        self.m_hash.copy_from_slice(&old_hash);
        result
    }

    pub fn calculate(data: &[u8], bits: Bits) -> String {
        let mut sha3 = SHA3::new(bits);
        sha3.add(data);
        sha3.get_hash()
    }

    pub fn calculate_from_str(text: &str, bits: Bits) -> String {
        Self::calculate(text.as_bytes(), bits)
    }
}

fn main() {
    let text = "hello world";
    let hash = SHA3::calculate_from_str(text, Bits::B256);
    println!("SHA3-256 of '{}': {}", text, hash);
}

