use std::fmt;

const STATE_SIZE: usize = 25;

pub struct SHA3 {
    m_block_size: usize,
    m_bits: Bits,
    m_hash: [u64; STATE_SIZE],
    m_buffer: [u8; 200],
    m_num_bytes: usize,
    m_buffer_size: usize,
}

#[derive(Copy, Clone, Debug)]
pub enum Bits {
    Bits224 = 224,
    Bits256 = 256,
    Bits384 = 384,
    Bits512 = 512,
}

impl SHA3 {
    /// same as reset()
    pub fn new(bits: Bits) -> Self {
        let mut sha3 = SHA3 {
            m_block_size: 200 - 2 * (bits as usize / 8),
            m_bits: bits,
            m_hash: [0; STATE_SIZE],
            m_buffer: [0; 200],
            m_num_bytes: 0,
            m_buffer_size: 0,
        };
        sha3.reset();
        sha3
    }

    /// restart
    pub fn reset(&mut self) {
        for i in 0..STATE_SIZE {
            self.m_hash[i] = 0;
        }

        self.m_num_bytes = 0;
        self.m_buffer_size = 0;
    }

    /// process a full block
    fn process_block(&mut self, data: &[u8]) {
        use std::convert::TryInto;

        let data64 = data
            .chunks_exact(8)
            .map(|bytes| u64::from_le_bytes(bytes.try_into().unwrap()));

        for (i, d) in data64.enumerate().take(self.m_block_size / 8) {
            self.m_hash[i] ^= d;
        }

        static ROUNDS: usize = 24;
        static XOR_MASKS: [u64; ROUNDS] = [
            0x0000000000000001_u64,
            0x0000000000008082_u64,
            0x800000000000808a_u64,
            0x8000000080008000_u64,
            0x000000000000808b_u64,
            0x0000000080000001_u64,
            0x8000000080008081_u64,
            0x8000000000008009_u64,
            0x000000000000008a_u64,
            0x0000000000000088_u64,
            0x0000000080008009_u64,
            0x000000008000000a_u64,
            0x000000008000808b_u64,
            0x800000000000008b_u64,
            0x8000000000008089_u64,
            0x8000000000008003_u64,
            0x8000000000008002_u64,
            0x8000000000000080_u64,
            0x000000000000800a_u64,
            0x800000008000000a_u64,
            0x8000000080008081_u64,
            0x8000000000008080_u64,
            0x0000000080000001_u64,
            0x8000000080008008_u64,
        ];

        let rotate_left = |x: u64, num_bits: u8| -> u64 {
            x.rotate_left(num_bits.into())
        };

        for round in 0..ROUNDS {
            let mut c = [0_u64; 5];
            for i in 0..5 {
                c[i] = self.m_hash[i]
                    ^ self.m_hash[i + 5]
                    ^ self.m_hash[i + 10]
                    ^ self.m_hash[i + 15]
                    ^ self.m_hash[i + 20];
            }

            for i in 0..5 {
                let temp = c[mod5(i + 4)] ^ rotate_left(c[mod5(i + 1)], 1);
                for j in 0..5 {
                    self.m_hash[i + 5 * j] ^= temp;
                }
            }

            let mut last = self.m_hash[1];
            let mut temp;
            for &(i, shift) in &[
                (10, 1),
                (7, 3),
                (11, 6),
                (17, 10),
                (18, 15),
                (3, 21),
                (5, 28),
                (16, 36),
                (8, 45),
                (21, 55),
                (24, 2),
                (4, 14),
                (15, 27),
                (23, 41),
                (19, 56),
                (13, 8),
                (12, 25),
                (2, 43),
                (20, 62),
                (14, 18),
                (22, 39),
                (9, 61),
                (6, 20),
                (1, 44),
            ] {
                temp = self.m_hash[i];
                self.m_hash[i] = rotate_left(last, shift);
                last = temp;
            }

            for j in (0..STATE_SIZE).step_by(5) {
                let one = self.m_hash[j];
                let two = self.m_hash[j + 1];

                self.m_hash[j] ^= self.m_hash[j + 2] & !two;
                self.m_hash[j + 1] ^= self.m_hash[j + 3] & !self.m_hash[j + 2];
                self.m_hash[j + 2] ^= self.m_hash[j + 4] & !self.m_hash[j + 3];
                self.m_hash[j + 3] ^= one & !self.m_hash[j + 4];
                self.m_hash[j + 4] ^= two & !one;
            }

            self.m_hash[0] ^= XOR_MASKS[round];
        }
    }

    /// add arbitrary number of bytes
    pub fn add(&mut self, data: &[u8]) {
        let mut current = data;

        if self.m_buffer_size > 0 {
            while !current.is_empty() && self.m_buffer_size < self.m_block_size {
                self.m_buffer[self.m_buffer_size] = current[0];
                current = &current[1..];
                self.m_buffer_size += 1;
            }
        }

        if self.m_buffer_size == self.m_block_size {
            let block = self.m_buffer[..self.m_block_size].to_vec(); // Make a copy
            self.process_block(&block);
            self.m_num_bytes += self.m_block_size;
            self.m_buffer_size = 0;
        }

        while current.len() >= self.m_block_size {
            let block = current[..self.m_block_size].to_vec(); // Make a copy
            self.process_block(&block);
            current = &current[self.m_block_size..];
            self.m_num_bytes += self.m_block_size;
        }

        for &byte in current {
            self.m_buffer[self.m_buffer_size] = byte;
            self.m_buffer_size += 1;
        }
    }

    /// process everything left in the internal buffer
    fn process_buffer(&mut self) {
        let mut offset = self.m_buffer_size;
        self.m_buffer[offset] = 0x06;
        offset += 1;

        while offset < self.m_block_size {
            self.m_buffer[offset] = 0;
            offset += 1;
        }

        self.m_buffer[offset - 1] |= 0x80;

        let block = self.m_buffer[..self.m_block_size].to_vec(); // Make a copy
        self.process_block(&block);
    }

    fn get_hash(&mut self) -> String {
        let mut old_hash = [0_u64; STATE_SIZE];
        old_hash.copy_from_slice(&self.m_hash);

        self.process_buffer();

        let hash_length = self.m_bits as usize / 64;

        let mut result = String::with_capacity(self.m_bits as usize / 4);
        static DEC2HEX: &[u8; 16] = b"0123456789abcdef";

        for i in 0..hash_length {
            for j in 0..8 {
                let one_byte = (self.m_hash[i] >> (8 * j)) as u8;
                result.push(DEC2HEX[(one_byte >> 4) as usize] as char);
                result.push(DEC2HEX[(one_byte & 0x0f) as usize] as char);
            }
        }

        let remainder = self.m_bits as usize - hash_length * 64;
        let mut processed = 0;

        while processed < remainder {
            let one_byte = (self.m_hash[hash_length] >> processed) as u8;
            result.push(DEC2HEX[(one_byte >> 4) as usize] as char);
            result.push(DEC2HEX[(one_byte & 0x0f) as usize] as char);
            processed += 8;
        }

        self.m_hash.copy_from_slice(&old_hash);

        result
    }

    /// compute SHA3 of a memory block
    pub fn compute(&mut self, data: &[u8]) -> String {
        self.reset();
        self.add(data);
        self.get_hash()
    }

    /// compute SHA3 of a string, excluding final zero
    pub fn compute_str(&mut self, text: &str) -> String {
        self.compute(text.as_bytes())
    }
}

fn mod5(x: usize) -> usize {
    x % 5
}

impl fmt::Debug for SHA3 {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(
            f,
            "SHA3 {{ m_block_size: {}, m_bits: {:?}, m_num_bytes: {}, m_buffer_size: {} }}",
            self.m_block_size, self.m_bits, self.m_num_bytes, self.m_buffer_size
        )
    }
}

fn main() {
    // Example usage:
    let mut sha3 = SHA3::new(Bits::Bits256);
    let hash = sha3.compute_str("hello");
    println!("Hash: {}", hash);
}

