fn hex2bin(hex: &str) -> Result<Vec<u8>, FromUtf8Error> {
    let bytes = (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
        .collect::<Vec<u8>>();
    Ok(bytes)
}

