        .chunks(2)
        .map(|chunk| {
            let high = chunk[0] as char;
            let low = chunk[1] as char;
            let h = if high.is_digit(16) {
                high.to_digit(16).unwrap()
            } else {
                (high as u8 - b'a' + 10) as u32
            };
            let l = if low.is_digit(16) {
                low.to_digit(16).unwrap()
            } else {
                (low as u8 - b'a' + 10) as u32
            };
            (h * 16 + l) as u8
        })
        .collect()
}

